SELECT 'moj-all-verified-judgments-review-002-chunk-102' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"55663ac6-4ea3-5786-ad61-177e05c24c03","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة لقصد التعاطي -إقرار - التعزير باجللد والسجن واإلبعاد عن الباد لقاء تعاطي احلبوب","document_number":"34275893","case_number":"34321229","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/23","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة لقصد التعاطي -إقرار - التعزير باجللد والسجن واإلبعاد عن الباد لقاء تعاطي احلبوب","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34275893:‬تاريخه ‪1434/7/23:‬هـ‬\n                  ‫رقم القضية ‪34321229:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34294097‬تاريخه‪1434/08/10:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة لقصــد التعاطــي ‪ -‬إقــرار ‪-‬‬\n‫التعزيــر باجللــد والســجن واإلبعــاد عــن البــاد لقــاء تعاطــي احلبــوب‬\n                                                               ‫احملظــورة‪.‬‬\n\n\n\n\n         ‫‪ -1‬قوله تعالى( وال تقتلوا النفس التي حرم اهلل إال باحلق )‪.‬‬\n               ‫‪ -2‬قوله تعالى ( والتفسدوا يف األرض بعد إصالحها )‪.‬‬\n           ‫‪ -3‬املادة(‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n           ‫‪ -4‬املادة(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n          ‫‪ -5‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة حبــة واحــدة مــن حبــوب‬\n‫اإلمفيتامــن وربــع حبــة مــن حبــوب الترامــادول ‪ -‬و طلــب املدعــى العــام‬\n‫تعزيــر املدعــى عليــه لقــاء تعاطيــه للحبــوب احملظــورة ‪ -‬طلــب املدعــي‬\n‫العــام ســجن املدعــى عليــه وتســفيره إلــى بالده بناء على املــواد (‪)56/ 41‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -‬أقــر املدعــى عليــه‬\n‫مبــا جــاء يف دعــوى املدعــي العــام حيــث أنــه مت القبــض عليــه وبتفتيــش‬\n‫الســيارة وجــد حبــة واحــدة وربــع احلبــة يشــتبه أن تكــون محظــورة ‪ ،‬بناء‬\n\n                                                                                  ‫‪222‬‬\n\f      ‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه لقــاء اســتعماله‬\n      ‫احلبــوب احملظــورة واحلكــم بتعزيــر املدعــى عليــه بالســجن واإلبعــاد عــن‬\n      ‫اململكــة العربيــة الســعودية وال يســمح بالعــودة إليهــا إال فيمــا تســمح بــه‬\n      ‫تعليمــات احلــج والعمــرة‪ ،‬وقــرر املدعــى عليــه اعتراضــه علــى احلكــم‬\n      ‫بــدون الئحــة‪ ،‬وقنــع املدعــى عليــه مبــا صــدر بحقــه مــن حكــم و صــدق‬\n                                                   ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫ـدي‬\n        ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n      ‫ـاء علــى املعاملــة الــواردة إلينــا‬\n                                           ‫أنــا ‪ ....‬باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n      ‫مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة اإلحســاء برقــم وتاريــخ‬\n      ‫‪1434/7/9‬ه ـ واملقيــدة بهــذه احملكمــة برقــم وتاريــخ ‪1434/7/11‬ه ـ‬\n      ‫واحملالــة إلينــا مــن فضيلــة الرئيــس برقــم وتاريــخ ‪1434/7/11‬ه ـ‬\n      ‫فتحــت اجللســة األولــى يــوم األربعــاء ‪1434/7/19‬ه ـ الســاعة العاشــرة‬\n      ‫وفيهــا حضــر املدعــي العــام امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n      ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n       ‫ا‪:‬‬  ‫األحســاء ذي الرقــم والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لدائــرة التحقيــق واالدعــاء‬\n      ‫العــام مبحافظــة اإلحســاء أدعــي علــى ‪ ......‬اجلنــس ‪ ،‬ذكــر اجلنســية‪،‬‬\n      ‫مصــري‪ ،‬الديانــة‪ :‬مســلم‪ ،‬تاريــخ امليــاد‪1409/02/20 :‬هـ‪،‬العمــر‪:‬‬\n      ‫‪ ،25‬نــوع الهويــة‪ :‬رخصــة إقامــة رقــم الهويــة‪ ..........:‬تاريــخ اإلصــدار‪:‬‬\n      ‫‪1432/10/23‬هــ‪ ،‬جهــة اإلصــدار‪ :‬جــوازات جنــران املهنــة‪ :‬موظــف‬\n      ‫أهلــي احلالــة االجتماعيــة ‪ :‬أعــزب‪ ،‬مــكان اإلقامــة‪ ...........:‬الهاتــف‬\n\n‫‪223‬‬\n\f‫احملمول‪..............:‬جهــة اإليقــاف‪ :‬ســجن األحســاء‪ ،‬تاريــخ القبــض‪:‬‬\n‫‪1434/6/9‬ه ـ ‪ ،‬حالــة املتهــم ‪ :‬موقــوف‪ ،‬االتهــام ‪ :‬تعاطــي املؤثــرات‬\n‫العقليــة وحيــازة مؤثــرات عقليــة بقصــد التعاطــي أو االســتعمال‬\n‫الشــخصي أنــه باإلطــاع علــى تنفيــذ املهمــة رقــم (‪ )9150‬املعــد مــن قبــل‬\n‫رجــال ضبــط أمــن الطــرق بطريــق الريــاض الدمــام الســريع تبــن أنــه‬\n‫مت القبــض علــى املدعــى عليــه وبقيادتــه ســيارة مــن نــوع (‪ ).....‬وبتفتيــش‬\n‫الســيارة ضبــط بهــا (‪ )1‬حبــة واحــدة و ربــع حبــة وربــع حبــة أخــرى يشــتبه‬\n‫أنهــا محظــورة مت ضبطهــا جميعهــا يف علبــة (الفيــوزات) وقــد اثبــت‬\n‫التقريــر الكيمــاوي الشــرعي رقــم (‪ 2857‬ك ش) لعــام ‪1434‬هـ الصادر‬\n‫مــن املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية إيجابيــة احلبــة‬\n‫ملــادة اإلمفيتامــن املنبــه احملظــور املــدرج يف اجلــدول رقــم (‪ )2‬فئــة (ب)‬\n‫وربــع احلبــة وربــع احلبــة لعقــار الترامــادول املــدرج يف اجلــدول رقــم (‪)1‬‬\n‫فئــة (هــ) وبســماع أقوالــه أقــر بحيازتــه مــا ضبــط معــه بقصــد التعاطــي‬\n‫وتعاطيــه لنوعــه‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام لــ‪ /‬بحيــازة (‪)1‬‬\n‫حبــة مــن حبــوب اإلمفتيامــن املنبــه احملظــور وربــع حبــة وربــع حبــة مــن‬\n‫عقــار الترامــادول لقصــد التعاطــي وتعاطيــه اإلمفيتامــن املنبــه احملظــور‬\n                                 ‫والترامــادول‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n                          ‫‪ -1‬محضر تنفيذ املهمة املرفق على اللفة رقم (‪.)4‬‬\n‫‪ -2‬أقــوال املدعــى عليــه املدونــة علــى الصفحــات رقــم (‪ )3،2‬مــن دفتــر‬\n                               ‫االســتدالالت األوليــة املرفــق علــى اللفــة رقــم (‪.)8‬‬\n                          ‫‪ -3‬التقرير الكيماوي املرفق على اللفة رقم (‪)16‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا ‪ -‬فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا وفقـ ًا للفقــرة الثانيــة‬\n\n\n                                                                                           ‫‪224‬‬\n\f      ‫مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫الصــادر باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n                       ‫لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪:‬‬\n      ‫‪-1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة حيازتــه مــا ضبــط معــه بقصــد‬\n                                                            ‫التعاطــي وتعاطيــه لنوعــه‪.‬‬\n      ‫‪-2‬بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املــادة (‪ )56‬مــن النظــام وذلــك‬\n      ‫بإبعــاده عــن البــاد بعــد تنفيــذ محكوميتــه‪ .‬وبــاهلل التوفيــق‪ ،‬هكــذا‬\n      ‫ا َّدعــى؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى‬\n      ‫ا ‪ :‬صحيــح مــا نســبه لــي‬   ‫عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـ ً‬\n      ‫املدعــي العــام مــن واقعــة القبــض ومــن حيازتــي لعــدد حبــة واحــدة مــن‬\n      ‫حبــوب االمفيتامــن احملظــورة وربعــي حبــة مــن عقــار الترامــدول املنبــه‬\n      ‫احملظــور بقصــد التعاطــي ومــن اســتعمالي للحب ــوب احملظــورة وصحيح‬\n      ‫اعتــرايف هكــذا أجــاب‪ .‬ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة‬\n      ‫ومنهــا‪ :‬التقريــر الكيمــاوي الشــرعي الصــادر مــن قســم الكيميــاء‬\n      ‫الشــرعية باملركــز اإلقليمــي ملراقبــة الســموم التابــع للمديريــة العامــة‬\n      ‫للشــؤون الصحيــة باملنطقــة الشــرقية برقــم (‪ 2857‬ك ش) لعــام ‪1434‬ه ـ‬\n      ‫املتضمــن إيجابيــة عي ــنة مــا ضبــط ملــادة اإلمفيتامــن املنبــه احملظــور‬\n      ‫ولعقــار الترامــدول املنبــه احملظــور كمــا جــرى اإلطــاع علــى كــرت‬\n      ‫ســوابق املدعــى عليــه املتضمــن خلــوه مــن الســوابق كمــا جــرى اإلطــاع‬\n      ‫علــى مذكــرة إيقــاف املدعــى عليــه املتضمنــة أنــه أوقــف بتاريــخ‬\n                                                                       ‫‪1434/06/09‬ه ـ‬\n      ‫فبنــاء علــى مــا ورد مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى‬\n\n\n‫‪225‬‬\n\f‫عليــه والتأكــد مــن أهليتــه وملــا ورد يف محضــر القبــض واعتــراف‬\n‫املدعــي عليــه ومبــا أنــه صــادق علــى صحــة مــا نســب إليــه مــن حيــازة‬\n‫احلبــوب احملظــورة علــى صفــة مــا ورد يف الدعــوى ومبــا أن مــا صــدر منــه‬\n‫حــرام يف الشــريعة ملــا يف احلبــوب احملظــورة مــن اخلطــر و الضــرر علــى‬\n‫البــاد والعبــاد وعلــى مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس‬\n‫التــي حــرم اهلل إال باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا)‬\n‫ممــا يســتوجب معاقبــة املدعــى عليــه و تعزيــزه بالعقوبــة الــواردة يف املــادة‬\n‫الواحــدة واألربعــن مــن نظــام مكافحــة املخــدرات ويتوجــه أن يكــون‬\n‫أقــل عقوبــة ملــا ظهــر مــن حالــه مــن النــدم وألنــه ال ســوابق لــه ولصغــر‬\n‫ســنه ولقلــة الكميــة التــي وجــدت بحيازتــه كمــا يتوجــه تخفيــف تلــك‬\n‫العقوبــة أيضــا حســب مقتضــى املــادة الســتني مــن النظــام نفســه ملــا‬\n‫ظهــر مــن حالــه مــن النــدم ولصغــر ســنه ولظروفــه االجتماعيــة التــي‬\n‫اقتنعــت بهــا احملكمــة وألنــه ال ســوابق لــه كمــا يتوجــه اســتحقاقه‬\n‫للعقوبــة الــواردة يف املــادة السادســة واخلمســن الفقــرة الثانيــة منهــا ومبــا‬\n‫أن املدعــى عليــه أقـ َّـر باســتعمال احلبــوب احملظــورة واســتعمالها ال يأخــذ‬ ‫َّ‬\n‫حكــم املســكر لعــدم التوافــق بينهمــا يف منــاط احلكــم ممــا يتوجــه‬\n‫معــه تعزيــر املدعــى عليــه باجللــد دون حــد املســكر لــذا كلــه وألجــل‬\n‫ـدي إدانــة‬\n          ‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي‪ :‬أوالً‪ /‬ثبــت لـ َّ‬\n‫املدعــى عليــه باســتعمال احلبــوب احملظــورة ويجلــد تعزيــز ًا لقــاء ذلــك‬\n‫بجلــده خمــس وســبعني جلــد ًة دفعــة واحــدة علنـاً‪ .‬ثانيـاً‪ /‬ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بحيــازة احلبــوب احملظــورة املوصــوف يف الدعــوى وعــدده‬\n‫حبــة واحــدة مــن حبــوب االمفيتامــن احملظــورة وربعــي حبــة مــن عقــار‬\n‫الترامــدول املنبــه احملظــور بقصــد التعاطــي وأن يعــزر بســجنه شــهرين‬\n\n\n                                                                                       ‫‪226‬‬\n\f      ‫مــن تاريــخ توقيفــه علــى ذمــة القضيــة وذلــك مبوجــب املــادة الواحــدة‬\n      ‫واألربعــن مــن نظــام مكافحــة املخــدرات واملــادة الســتني‪ .‬ثالثــا‪ /‬وأن‬\n      ‫يبعــد عــن اململكــة بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه واســتيفاء مــا‬\n      ‫لــه ومــا عليــه مــن حقــوق وال يســمح لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح‬\n      ‫بــه تعليمــات احلــج والعمــرة حســب مقتضــى مــا ورد يف املــادة السادســة‬\n      ‫واخلمســن مــن النظــام نفســه الفقــرة الثانيــة ‪ .‬وبتــاوة احلكــم علــى‬\n      ‫الطرفــن وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم‬\n      ‫وطلــب املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة‬\n      ‫هــي الئحــة الدعــوى هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن‬\n      ‫ذلــك حرمــة اســتعمال احلبــوب احملظــورة وأثــره الســيئ علــى العقــل واملــال‬\n      ‫وأقفلــت اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف ‪1434/07/19‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم وتاريــخ ‪1434/08/07‬ه ـ الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف برقــم وتاريــخ‬\n      ‫‪1434/08/01‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ ....‬املســجل برقــم‪ ....‬وتاريــخ ‪1434/07/23‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد‪( ....‬مصــري اجلنســية) يف قضيــة مخــدرات‬\n      ‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه وســلم‪.‬‬\n                                                            ‫حــرر يف ‪1434/08/10‬هــ‪.‬‬\n\n\n‫‪227‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":222,"source_page_end":227,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b0dc362ba545a91495ac6b7af6c0bf764ae2dd4f28fb952870c081e3c33d0db6","normalized_text_hash":"729f546bec2e46bbeb817fd31bc31376f4366b55c19a2fb324ba7ce648d359ac","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p222-34275893"},{"id":"5aa68656-f73b-5fe2-bd64-75bfddcbc17b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد االجتار وتعاطيها -صدم الدورية الرسمية -بينة غير موصلة -إدانة باحليازة بقصد التعاطي -عقوبة بحدها األعلى -إقامة حد املسكر -تعزير بالسجن واجللد واملنع من السفر -رد دعوى لعدم كفاية األدلة.","document_number":"34278299","case_number":"34327580","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/24","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد االجتار وتعاطيها -صدم الدورية الرسمية -بينة غير موصلة -إدانة باحليازة بقصد التعاطي -عقوبة بحدها األعلى -إقامة حد املسكر -تعزير بالسجن واجللد واملنع من السفر -رد دعوى لعدم كفاية األدلة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34278299:‬تاريخه‪1434/07/24 :‬هـ‬\n                    ‫رقم الدعوى‪34327580:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34298169‬تاريخه‪1434/8/15:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصد االجتــار وتعاطيها‬\n ‫‪ -‬صــدم الدوريــة الرســمية ‪ -‬بينــة غيــر موصلــة ‪ -‬إدانــة باحليــازة بقصــد‬\n ‫التعاطــي ‪ -‬عقوبــة بحدهــا األعلــى ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر‬\n ‫بالســجن واجللــد واملنــع مــن الســفر ‪ -‬رد دعــوى لعــدم كفايــة األدلــة‪.‬‬\n\n\n\n\n     ‫املادتان (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة بقصــد االجتــار وصــدم‬\n ‫الدوريــة الرســمية‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n ‫وعقوبــة تعزيريــة لقــاء صدمــه للدوريــة األمنيــة‪ ،‬طلــب رجــال األمــن‬\n ‫منــه التوقــف فــاذ بالفــرار وهــو يقــود ســيارته بســرعة جنونيــة وأثنــاء‬\n ‫محاولتهــم اســتيقافه شــوهد وهــو يرمــي كيــس بــه عــدد مــن احلبــوب‬\n ‫احملظــورة‪ ،‬وبعــد القبــض عليــه مت تفتيــش منزلــه فعثــر بــه علــى قطعــة‬\n ‫يشــتبه كونهــا مــن احلشــيش املخــدر وحبــة يشــتبه أن تكــون مــن احلبــوب‬\n ‫احملظــورة‪ -‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n\n                                                                                  ‫‪228‬‬\n\f      ‫للحشــيش املخــدر واإلمفيتامــن‪ ،‬أقــر أمــام احملكمــة بحيــازة مــا ضبــط‬\n      ‫معــه بقصــد التعاطــي وتعاطيــه لنوعهمــا وأنكــر قصد االجتــار‪ ،‬املدعي‬\n      ‫العــام لــم يقــدم بينــة موصلــة وال مــا يكفــي مــن القرائــن إلدانــة املدعــى‬\n      ‫عليــه بقصــد االجتــار‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه بحيــازة‬\n      ‫احلشــيش املخــدر واحلبــوب احملظــورة بقصــد التعاطــي وتعاطيــه لهمــا‬\n      ‫وقــررت إقامــة حــد املســكر عليــه بجلــده ثمانــن جلــدة دفعــة واحــدة‬\n      ‫علنــا وســجنه ملــدة ســنتني ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‬\n      ‫كمــا قضــت بــرد دعــوى املدعــي العــام بطلــب إدانتــه بقصــد االجتــار‬\n      ‫لعــدم كفايــة األدلــة‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‬\n          ‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم ‪ 34327580‬وتاريــخ ‪1434/07/16‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341710405‬وتاريــخ ‪1434/07/16‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق ‪1434/07/22‬ه ـ افتتحــت اجللســة الســاعة ‪11 :30‬‬\n      ‫وفيهــا حضــر املدعــي العــام مبوجــب التكليــف الصــادر مــن هيئــة‬\n      ‫التحقيــق واالدعــاء العــام بنجــران رقــم ه ـ ن ‪ 11178/2/1‬بتاريــخ‬\n      ‫‪1430/12/29‬ه ـ وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ‪....‬‬\n      ‫ســعودي مبوجــب الســجل املدنــي رقــم‪ ....‬قائــا يف دعــواه عليــه حيث ورد‬\n      ‫مبحضــر البــاغ املعــد مــن قبــل الفرقــة القابضــة تؤكــد امتهــان املتهــم‬\n      ‫الترويــج ويتــردد عليــه أشــخاص مشــبوهني‪ .‬و ورد مبحضــر القبــض‬\n\n‫‪229‬‬\n\f‫املعــد مــن قبــل الفرقــة القابضــة أنــه بنــاء علــى إخباريــة احــد مصادرهــم‬\n‫الســرية تفيــد بــأن املتهــم ميتهــن الترويــج ‪ ،‬وأفــاد املصــدر بــان املتهــم‬\n‫يتواجــد حاليــا يف حــي ‪ ....‬بالقــرب مــن مستشــفى القلــب ويســتقل ســيارة‬\n‫مــن نــوع ‪ .......‬حتمــل اللوحــة رقــم (‪ )........‬وعنــد االقتراب منــه الذ بالفرار‬\n‫ومت توجيــه الدوريــة الرســمية لــه وطلبــوا منــه الوقــوف ولــم يســتجب ومت‬\n‫التضيــق عليــه وتوجيــه كامــل الفــرق للمذكــور والســيطرة عليــه وعنــد‬\n‫احتكاكــه باجليــب الرســمي قــام بصــدم جــدار احــد املنــازل نتــج عــن‬\n‫ذلــك تلفيــات باجلــدار بطــول ثالثــة أمتــار تقريبــا وتلفيــات بســيارة املتهــم‪،‬‬\n‫إال أنــه لــم يســتجب وأســتمر بالهــرب بســرعة جنونيــة وخوفا على ســامة‬\n‫ســالك الطريــق ولعــدم اســتجابته لنــداء الفرقــة مت إطــاق طلقتــن‬\n‫حتذيريــة يف الهــواء ولــم يســتجب أيضـ ًا عندهــا مت إطــاق طلقتــن علــى‬\n‫إطــار الســيارة ممــا أدى إلــى إعطابــه وارتــداد الطلقــات لزجــاج الســيارة‬\n‫اخللفــي و بــودي الســيارة مــن اخللــف ‪ ،‬و واصــل املتهــم الهــرب وشــوهد‬\n‫وهــو يقــوم برمــي كيــس أبيــض اللــون تبــن فيمــا بعــد أنــه يحتــوي علــى‬\n‫حبــوب بيضــاء اللــون بلــغ عددهــا (‪ )135‬حبــة وفتــات مــن نفــس النــوع بلــغ‬\n‫وزنهــا (‪8,3‬جــم) ‪ ،‬وبعــد مســافة تقــدر بســبعمائة متــر تقريبــا وقــع املتهــم‬\n‫يف منطقــة وحــل تغمرهــا امليــاه أجبرتــه علــى التوقــف‪ .‬ومت عمــل رســم‬\n‫تخطيطــي للحــادث متهيدنــا ملطالبتهــم للمتهــم بإصــاح التلفيــات التــي‬\n‫أحدثهــا‪ ،‬ومت إرســاله إلــى مستشــفى امللــك خالــد لتلقــي العــاج الــازم‪.‬‬\n‫كمــا أنــه بتاريــخ ‪1434/6/26‬ه ـ ورد محضــر تفتيــش منــزل املتهــم‬\n‫املتضمــن أنــه بنــاء علــى مــا توفــر مــن معلومــات مؤكــدة عــن وجــود‬\n‫كميــات مــن احلشــيش املخــدر لــدى املتهــم أعــاه فقــد مت أخــذ أذن‬\n‫بتفتيــش منزلــه ‪ ،‬وباالنتقــال للمنــزل وهــو عبــارة عــن حــوش بــه هنقــر‬\n\n\n                                                                                        ‫‪230‬‬\n\f      ‫مكــون مــن غرفــة نــوم ومجلــس ومطبــخ وبتفتيــش الغرفــة وجــدت قطعــة‬\n      ‫ســمراء اللــون بلــغ وزنهــا (‪182.6‬جــم) أثــان وثمانــون جرام ـ ًا وســته مــن‬\n      ‫العشــرة مــن اجلــرام حتــت الســرير ‪ ،‬كمــا عثــر علــى حبــة يشــتبه أن‬\n      ‫تكــون مــن احلبــوب احملظــورة فــوق دوالب املالبــس‪ .‬مت إيقافــه وإيداعــه‬\n      ‫شــعبة الســجن العــام بنجــران اســتنا ًدا للمــادة (‪)112‬من نظــام اإلجراءات‬\n      ‫اجلزائيــة‪ .‬وبســماع أقــوال املتهــم‪ ......./‬لــم يفــد التحقيــق معــه بشــيء‪.‬‬\n      ‫وباســتجواب املتهــم أقــر بــأن ســبب القبــض عليــه حيازتــه لعــدد (‪)180‬‬\n      ‫حبــه وأنهــا لالســتخدام الشــخصي وأنــه حصــل عليهــا من شــخص يدعى‬\n      ‫ورقــم جوالــه مخــزن بجــوال املتهــم وقــد أدلــى بــه للمكافحــة وقــد‬\n      ‫اشــترى منــه قرابــة (‪ )200‬حبــة مــن احلبــوب احملظــورة مقابــل (‪)4000‬‬\n      ‫ريــال ســعودي ولــم يعطــي أحــدا منهــا شــيئا وأنــه يعمــل يف الصبــاح لــدى‬\n      ‫شــركة و يعمــل ويكــد بســيارته مشــاوير طويلــة ‪ ،‬وأن ســبب هروبــه‬\n      ‫مــن الفرقــة القابضــة هــو عــدم معرفتــه بهــم يف بدايــة األمــر كــون‬\n      ‫الســيارة األولــى كانــت مدنيــة وبعــد ذلــك حضــرت الدوريــة الرســمية‬\n      ‫وقامــت بصدمــه جهــة اجلــدار وتوقــف يف مــكان بــه مــاء ‪ ،‬وأن الســيارة‬\n      ‫عائــدة ألخيــه ‪ ،‬وأنــه لديــه ســابقة مخــدرات يف حفــر الباطــن وحكــم‬\n      ‫بثالثــة أشــهر وســابقة يف القصيــم وحكــم بأربــع ســنوات ‪ ،‬ومبــا جهتــه‬\n      ‫مبحضــر تفتيــش منزلــه أقــر بحيازتــه حلبــة مــن احلبــوب احملظــورة ‪،‬‬\n      ‫وحيــازة لقطعــة حشــيش بلــغ وزنهــا (‪182.6‬جــم) أثــان وثمانــون جرام ـ ًا‬\n      ‫وســته مــن العشــرة مــن اجلــرام بقصــد التعاطــي ‪ ،‬وتعاطيــه لــه بالســابق‬\n      ‫وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )11555‬الصــادر مــن‬\n      ‫مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة‬\n      ‫املكرمــة أن العينــة املرســلة باحلــرز الســري رقــم (‪334‬س) حتتــوي علــى‬\n\n\n‫‪231‬‬\n\f‫مــادة اإلمفيتامــن املؤثــر عقلي ـاً‪ ،‬واإلمفيتامــن مــن املــواد املدرجــة‬\n‫بجــداول املخــدرات واملؤثــرات العقليــة رقــم (‪ 2‬فئــة ب) امللحقــة بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ .‬وأثبــت التقريــر الكيميائــي الشــرعي‬\n‫رقــم (‪/11560‬س‪1434/2‬ه ـ ) الصــادر مــن مركــز مراقبــة الســموم‬\n‫والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة املكرمــة أن العينــة‬\n‫املرســلة للتحليــل باحلــرز الســري رقــم (‪ )339‬ثبــت أنهــا حشــيش مخــدر‬\n‫وحتتــوي علــى املــادة الفعالــة للحشــيش املخــدر‪ ،‬وتعاطيــه لــه بالســابق ‪،‬‬\n‫واحلشــيش املخــدر مــن املــواد املدرجــة بجــداول املخــدرات واملؤثــرات‬\n‫العقليــة رقــم (‪ 1‬فئــة أ) امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n‫وقــد انتهــى التحقيــق بتوجيــه االتهــام لــ‪ ،....‬بحيــازة (‪ )136‬مائــة وســت‬\n‫وثالثــون حبــة و وفتــات مكســور مــن نفــس احلبــوب بلــغ وزنــه (‪81,3‬جــم)‬\n‫مــن احلبــوب احملتويــة علــى مــادة اإلمفيتامــن املؤثــرة عقليــا بقصــد‬\n‫االجتــار ‪ ،‬وحيــازة (‪182.6‬جــرام) مــن احلشــيش املخــدر بقصــد االجتــار‬\n‫ا مجرم ـ ًا اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن‬\n                                                                      ‫‪ ،‬ممــا يعــد فع ـ ً‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وعــدم االمتثــال لرجــال األمــن‬\n‫وصــدم دوريتهــم‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جــاء يف إقــراره‬\n‫حتقيقــا املــدون مبحضــر االســتجواب املرفــق لفــة رقــم ( ‪ )15‬ص (‪)3-1‬‬\n‫‪ ،‬وعلــى ص(‪ )2-1‬مــن دفتــر االســتجواب املرفــق لفــة (‪ -2 .)16‬مــا جــاء‬\n‫يف محاضــر البــاغ والقبــض والتفتيــش املنــوه عنــه املــدون علــى دفتــر‬\n‫االســتدالل املرفــق لفــه رقــم (‪ )1‬علــى ص (‪ ، )2.11.12‬وعلــى ص(‪)11‬‬\n\n\n                                                                                             ‫‪232‬‬\n\f      ‫مــن دفتــر االســتدالل املرفــق لفــة(‪ -3 .)19‬مــا تضمنــاه التقريريــن‬\n      ‫الكيميائيــن الشــرعيني املنــوه عنهمــا املرفقــن لفــة رقــم ( ‪.) 18 ،17‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املتهــم ‪ /‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n      ‫فعــل مجــرم ومعاقــب عليــه نظام ـ ًا مبوجــب نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة يف عقوباتــه األصليــة والتكميليــة لــذا أطلــب إثبــات‬\n      ‫إدانتــه مبــا أســند إليــه ‪ ،‬واحلكــم عليــه مبــا يلــي‪ .1 :‬العقوبــة الــواردة يف‬\n      ‫الفقــرة األولــى مــن املــادة (‪ )38‬الثامنــة والثالثــن مــن نظــام مكافحــة‬\n      ‫املخــدرات املنــوه عنــه‪ .2 .‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ‬\n      ‫محكوميته اســتناد ًا للفقرة األولى من املادة (‪ )56‬السادســة واخلمســن‬\n      ‫مــن نظــام مكافحــة املخــدرات املنــوه عنــه‪ .3 .‬معاقبتــه بعقوبــة تعزيريــة‬\n      ‫رادعــة لــه وزاجــرة لغيــره لعــدم امتثالــه لرجــال األمــن وصــدم دوريتهــم‪.‬‬\n      ‫(علمــا بــان احلــق اخلــاص مــازال قائمــا) هــذه دعــواي وبعــرض الدعــوى‬\n      ‫علــى املدعــى عليــه وســؤاله اجلــواب أجــاب بقولــه مــا ذكــره املدعــي‬\n      ‫العــام يف دعــواه مــن أننــي حــزت (‪ )136‬مائــة وســت وثالثــون حبــة وفتــات‬\n      ‫مكســور مــن نفــس احلبــوب بلــغ وزنــه (‪81,3‬جــم) مــن احلبــوب احملتويــة‬\n      ‫علــى مــادة اإلمفيتامــن املؤثــرة عقليــا‪ ،‬وأننــي حــزت قطعــة مــن احلشــيش‬\n      ‫املخــدر تــزن (‪182.6‬جــرام) فهــذا صحيــح وأنــا أتعاطــى احلشــيش املخــدر‬\n      ‫واحلبــوب احملظــورة‪ ،‬وأمــا مــا ذكــره مــن أن قصــدي مــن حيازتهــا‬\n      ‫االجتــار فهــذا غيــر صحيــح والصحيــح أن قصــدي مــن حيازتهــا‬\n      ‫االســتعمال الشــخصي‪ ،‬وغيــر صحيــح أننــي لــم أمتثــل لرجــال األمــن‬\n      ‫وصدمــت دوريتهــم فأنــا لــم أكــن أعلــم بأنهــم مــن رجــال املكافحــة ولــم‬\n      ‫أصطــدم بدوريتهــم الرســمية بــل هــم الذيــن اصطدمــوا بــي وقــد تبــت‬\n      ‫إلــى اهلل تعالــى وندمــت علــى مــا فعلــت وعلــي ســابقتي مخــدرات هــذه‬\n\n\n‫‪233‬‬\n\f‫إجابتــي وقــال املدعــي العــام الصحيــح مــا ذكرتــه وال صحــة ملــا أنكــره‬\n‫املدعــى عليــه ممــا جــاء يف الئحــة الدعــوى وبينتــي علــى ذلــك مــا جــاء يف‬\n‫الئحــة الدعــوى وأوراق املعاملــة‪ .‬أ‪.‬ه ـ وبالرجــوع إليهــا وجــدت مطابقــة ملــا‬\n‫جــاء يف جــواب املدعــى عليــه وبســؤال املدعــي العــام هــل لديــه زيــادة بينــة‬\n‫علــى أن املدعــى عليــه قصــد مــن حيازته االجتار فقــال إن كبر الكمية‬\n‫دليــل علــى قصــد االجتــار كمــا أن الفرقــة القابضــة وردتهــم إخباريــة‬\n‫مــن أحــد مصادرهــم الســرية تفيــد بــأن املتهــم ميتهــن الترويــج وبســؤال‬\n‫املدعــي العــام هــل لديــه زيــادة بينة على أن املدعــى عليه تعمد االصطدام‬\n‫بالدوريــة الرســمية وإحــداث تلفيــات بهــا ليعاقــب علــى ذلــك القصــد‬\n‫اجلنائــي قــال ليــس لــدي ســوى مــا جــاء يف الئحــة الدعــوى وأوراق املعاملة‪.‬‬\n‫أ‪.‬ه ـ وبعــد ســماع الدعــوى واإلجابــة جــرى االطالع على صــورة التقريرين‬\n‫الكيميائيــة الشــرعية املشــار إليــه يف الدعــوى فوجــدا يتضمننــا إيجابية‬\n‫مــا ضبــط بحــوزة املدعــى عليــه للحشــيش املخــدر ولإلمفيتامــن‪ .‬أ‪.‬هــ‪.‬‬\n‫فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وبعــد دراســة القضيــة‬\n‫واالطــاع علــى أوراق املعاملــة ومبــا أن املدعــى عليــه أقــر مبــا جــاء يف‬\n‫دعــوى املدعــي العــام مــن حيازتــه ملائــة وســت وثالثــن حبــة وفتــات‬\n‫مكســور مــن نفــس احلبــوب بلــغ وزنــه (‪81,3‬جــم) مــن احلبــوب احملتويــة‬\n‫علــى مــادة اإلمفيتامــن املؤثــرة عقليــا‪ ،‬وحيازتــه لقطعــة مــن احلشــيش‬\n‫املخــدر تــزن (‪182.6‬جــرام) وتعاطيــه للحشــيش املخــدر واحلبــوب‬\n‫احملظــورة يف الســابق‪ ،‬وألنــه أقــر بــأن قصــده مــن حيازتهــا االســتعمال‬\n‫الشــخصي وأنكــر أن يكــون قصــده االجتــار‪ ،‬كمــا أنــه أقــر‬\n‫باالصطــدام بالدوريــة الرســمية ودفــع بأنــه لــم يتعمــد ذلــك وأن قائــد‬\n‫الدوريــة انحــرف عليــه‪ ،‬وألن املدعــي العــام لــم يقــم بينــة موصلــة وال مــا‬\n\n\n                                                                                       ‫‪234‬‬\n\f      ‫يكفــي مــن القرائــن إلثبــات إدانــة املدعــى عليــه بحيــازة مــا ضبــط معــه‬\n      ‫بقصــد االجتــار إذ أن الكميــة املضبوطــة معــه ليســت كبيــرة بالقــدر‬\n      ‫الــذي يجــزم معــه بحيازتــه لهــا بقصــد االجتــار ومــا ذكــره املدعــي العــام‬\n      ‫مــن وجــود إخباريــة بحــق املدعــى عليــه ال يعــول عليهــا يف إثبــات اإلدانــة‬\n      ‫مبــا ذكــر‪ ،‬كمــا أن املدعــي العــام لــم يقــم بينــة موصلــة وال مــا يكفــي‬\n      ‫مــن القرائــن إلثبــات إدانــة املدعــى عليــه بتعمــد القصــد اجلنائــي بهــذا‬\n      ‫االصطــدام‪ ،‬وألن املدعــى عليــه لــه عــدة ســوابق مــن نفــس جنــس هــذه‬\n      ‫اجلرميــة لــم تردعــه عقوباتهــا‪ ،‬واســتناد ًا إلــى املــواد (‪ )56-41‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬ولــكل هــذه األســباب فقــد‬\n      ‫قــررت اآلتــي‪ :‬أوالً‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي احلشــيش‬\n      ‫املخــدر واحلبــوب احملظــورة وقــررت تعزيــره لقــاء ذلــك بإقامــة حــد‬\n      ‫املســكر عليــه بجلــده ثمانــن جلــدة دفعــة واحــدة علنــا‪ .‬ثانيـاً‪ :‬حكمــت‬\n      ‫بــرد دعــوى املدعــي العــام بطلــب إثبــات إدانــة املدعــى عليــه بحيــازة‬\n      ‫احلبــوب املنبهــة احملظــورة واحلشــيش املخــدر بقصــد االجتــار وطلبــه‬\n      ‫تطبيــق العقوبــة الــواردة يف املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة بحقــه لعــدم كفايــة األدلــة‪ .‬ثالث ـاً‪ :‬ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بحيــازة (‪ )136‬مائــة وســت وثالثــون حبــة وفتــات مكســور‬\n      ‫مــن نفــس احلبــوب بلــغ وزنــه (‪81,3‬جــم) مــن احلبــوب احملتويــة علــى مــادة‬\n      ‫اإلمفيتامــن املؤثــرة عقليــا‪ ،‬وقطعــة مــن احلشــيش املخــدر تــزن‬\n      ‫(‪182.6‬جــرام) بقصــد االســتخدام الشــخصي وقــررت تعزيــره لقــاء ذلــك‬\n      ‫بســجنه ملــدة ســنتني اعتبــار ًا مــن تاريــخ توقيفــه‪ .‬رابعــا‪ :‬مينــع املدعــى عليــه‬\n      ‫مــن الســفر خــارج البــاد ملــدة ســنتني تبــدأ بعــد انتهــاء مــدة تنفيــذ عقوبــة‬\n      ‫الســجن‪ .‬خامس ـاً‪ :‬حكمــت بــرد دعــوى املدعــي العــام بطلــب تعزيــر‬\n\n\n‫‪235‬‬\n\f‫املدعــى عليــه لقــاء صدمــه للدوريــة الرســمية التابعــة للفرقــة القابضــة‬\n‫لعــدم ثبــوت موجبــه‪ .‬وبذلــك كلــه حكمــت وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر قناعتــه باحلكــم كمــا قــرر املدعــي العــام اعتراضــه‬\n‫علــى احلكــم بــدون الئحــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                      ‫محمد وآله وصحبه أجمعني‪ .‬حرر يف ‪1434/7/22‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n‫‪ 341710405‬وتاريــخ ‪1434/7/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ................./‬برقــم ‪34278299‬‬\n‫وتاريــخ ‪1434/7/24‬ه ـ اخلــاص بدعوى املدعــي العام ضد ‪.................../‬‬\n‫يف قضيــة (مخــدرات ‪ ،‬والهــروب مــن رجــال األمــن وصــدم ســيارة‬\n‫رســمية) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪236‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":228,"source_page_end":236,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d7a5ef2aa466c577c5ff2e61d8bace2c8c1060e7d4274b1218d84765671f022","normalized_text_hash":"1d362b4b1308712de1e54f6d6ecf566c464199e0a9b06cb4fad77c7352d8d8d6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p228-34278299"},{"id":"9bf36e3e-9bcf-5146-96d0-0d0928d74a7f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي والترويج وتعاطيه -إثبات بالقرائن -إدانة باحليازة املجردة -تعزير للتهمة القوية -سجن وجلد وإبعاد عن الباد -براءة أحد املتهمن لعدم","document_number":"34293242","case_number":"34367823","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/09","year":"1434","subject":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي والترويج وتعاطيه -إثبات بالقرائن -إدانة باحليازة املجردة -تعزير للتهمة القوية -سجن وجلد وإبعاد عن الباد -براءة أحد املتهمن لعدم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34293242:‬تاريخه‪1434/08/09 :‬هـ‬\n                          ‫رقم الدعوى‪34367823:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34374737‬تاريخه‪1434/12/01:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬اشــتراك يف حيــازة حشــيش بقصــد التعاطــي والترويــج‬\n       ‫وتعاطيــه‪ -‬إثبــات بالقرائــن‪ -‬إدانــة باحليــازة املجــردة‪ -‬تعزيــر للتهمــة‬\n       ‫القويــة ‪ -‬ســجن وجلــد وإبعــاد عــن البــاد ‪ -‬بــراءة أحــد املتهمــن لعــدم‬\n                                                                      ‫ثبــوت التهمــة‪.‬‬\n\n\n\n\n                    ‫‪ -1‬قول اهلل تعالى‪ ( :‬وتعاونوا على البر والتقوى‪ ..‬اآلية )‪.‬‬\n        ‫‪ -2‬قول اهلل تعالى‪ ( :‬يا أيها الذين آمنوا إمنا اخلمر وامليسر‪ ..‬اآلية)‪.‬‬\n       ‫‪ -3‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                          ‫حــرام )‪.‬رواه مســلم‪.‬‬\n           ‫‪ -4‬املواد (‪ )39‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهــم تتضمــن طلــب إثبــات إدانتهــم‬\n       ‫بحيــازة احلشــيش املخــدر بقصــد الترويــج والتعاطــي‪ ،‬واحلكــم عليهــم‬\n       ‫بعقوبــة الســجن واجللــد والغرامــة واملصــادرة واإلبعــاد عــن البــاد طبقــا‬\n       ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -‬مت متابعــة الســيارة‬\n       ‫التــي يســتقلونها وبعــد توقفهــا وترجلهــم منهــا مت القبــض عليهــم يف أحــد‬\n       ‫احملــات املجــاورة وبتفتيــش املركبــة عثــر فيهــا علــى احلشــيش املخــدر‪-‬‬\n\n‫‪243‬‬\n\f‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش‬\n‫املخــدر‪ -‬أنكــر املدعــى عليهــم أمــام احملكمــة مــا أســنده إليهــم املدعــي‬\n‫العــام وأقــر الثالــث بتعاطــي احلشــيش‪ -‬قضــت احملكمــة بإدانــة املدعــى‬\n‫عليــه الثالــث بتعاطــي احلشــيش املخــدر وقــررت إقامة حد املســكر عليه‬\n‫بجلــده ثمانــن جلــدة دفعــة واحــدة علنــا‪ ،‬وقضــت بإدانــة األول والثالــث‬\n‫بحيــازة احلشــيش املخــدر حيــازة مجــردة مــع توجــه الشــبهة بــأن يكــون‬\n‫قصدهمــا مــن حيازتهــا الترويــج والتعاطــي وقــررت ســجن كل واحــد‬\n‫منهمــا ثــاث ســنوات وجلــده خمســن جلــدة تكــرر عليــه ثمــان مــرات‬\n‫وتغرميــه مبلــغ خمســة آالف ريــال وإبعادهمــا عــن البــاد‪ ،‬كمــا قضــت‬\n‫بــرد مطالبــة املدعــي العــام تطبيــق العقوبــات الــواردة يف املــادة (‪)53-38‬‬\n‫بحقهمــا وقضــت بــرد الدعــوى جتــاه الثانــي وأخلــت ســبيله منهــا‪ -‬قنــع‬\n‫املدعــى عليهــم باحلكــم وعــارض املدعــي العــام عليــه‪ -‬قــررت محكمــة‬\n                              ‫االســتئناف باألكثريــة املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34367823‬وتاريــخ‬\n‫‪ 1434/08/07‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341895628‬وتاريــخ‬\n‫‪ 1434/08/06‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/08/09‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 :30‬لســماع دعــوى املدعــي العــام ضــد ويف هــذه‬\n‫اجللســة حضــر املدعــي العــام ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم واملكلــف مــن قبــل هيئــة التحقيــق واالدعــاء العــام مبباشــرة‬\n\n                                                                                   ‫‪244‬‬\n\f      ‫الدعــاوى بهــذه احملكمــة مبوجــب كتابهم رقم هــ‪ 15832/6/2‬وتاريخ‬\n      ‫‪1433/03/06‬ه ـ نيابــة عــن املدعــى العــام بفرع هيئــة التحقيق مبحافظة‬\n      ‫وادعــى علــى‪)38( ،‬عام ـاً‪ ،‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫() غيــر متعلــم ‪ ،‬يقيــم بطريقــة غيــر نظاميــة ‪ ،‬املقبــوض عليــه بتاريــخ‬\n      ‫‪1434/6/6‬ه ـ واملوقــوف بالســجن العــام مبحافظــة جــدة بأمــر متديــد‬\n      ‫التوقيــف رقــم (ه ـ م‪ )40774/5/2‬بتاريــخ ‪1434/6/17‬ه ـ اســتناد ًا‬\n      ‫للقــرار الــوزاري رقــم (‪ )1900‬الصــادر بتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى‬\n      ‫املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪)28( ،‬عامـ ًا ‪ ،‬مينــي اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم () متعلــم ‪ ،‬مهنتــه عامــل بالقطــاع اخلــاص‪،‬‬\n      ‫املقبوض عليه بتاريخ ‪1434/6/6‬هـ واملوقوف بالســجن العام مبحافظة‬\n      ‫جــدة بأمــر متديــد التوقيــف رقــم (ه ـ م‪ )40743/5/2‬بتاريــخ‬\n      ‫‪1434/6/17‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬الصــادر بتاريــخ‬\n      ‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫و‪)23( .....‬عام ًا ‪ ...‬ميني اجلنسية مبوجب البطاقة البديلة رقم (‪)34/795‬‬\n      ‫الصــادرة مــن مكافحــة املخــدرات مبحافظة جــدة بتاريخ ‪1434/6/7‬هـ‬\n      ‫متعلــم ‪ ،‬يقيــم بطريقــة غيــر نظاميــة‪ ،‬املقبــوض عليــه بتاريــخ‬\n      ‫‪1434/6/6‬ه ـ واملوقــوف بالســجن العــام مبحافظــة جــدة بأمــر متديــد‬\n      ‫التوقيــف رقــم (ه ـ م‪ )40742/5/2‬بتاريــخ ‪1434/6/17‬ه ـ اســتناد ًا‬\n      ‫للقــرار الــوزاري رقــم (‪ )1900‬الصــادر بتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى‬\n      ‫املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة قائــا يف الئحتــه إنــه بتاريــخ‬\n      ‫‪1434/6/6‬ه ـ وبنــاء علــى معلومــات ســابقه لــدى مكافحــة املخــدرات‬\n      ‫مت رصــد املدعــى عليهــم يســتقلون مركبــه مــن نــوع (‪ )....‬حتمــل اللوحــة‬\n      ‫رقــم (‪ )....‬بقيــادة املدعــى عليــه األول ويرافقــه يف املقعــد األمامــي املدعى‬\n\n\n‫‪245‬‬\n\f‫عليــه الثانــي ويف املقعــد اخللفــي املدعــى عليــه الثالــث ومبتابعهــم إلــى‬\n‫حــي الكنــدرة توقفــت املركبــة وترجلــوا املدعــى عليهــم الثالثــة و‬\n‫توجهــوا إلــى أحــد محــات االتصــاالت املجــاورة وبالقبــض عليهــم‬\n‫وتفتيشــهم شــخصي ًا ضبــط بحــوزة األول علــى مبلــغ مالــي قــدره (‪)29‬‬\n‫ريــاالً‪ ،‬ومبلــغ (‪ )1288‬ريــا ًال بحــوزة الثانــي ‪ ،‬ومبلــغ (‪ )480‬ريــاال بحــوزة‬\n‫الثالــث‪ ،‬وبســؤالهم عــن املركبــة أنكــروا عالقتهــم بهــا وبتفتيشــها‬\n‫ضبــط عنــد موضــع أقــدام الراكــب الثالــث (كيــس نايلــون) كبيــر‬\n‫احلجــم لونــه أخضــر بداخلــه عــدد (‪ )7‬ســبع قطــع ســوداء اللــون بلــغ‬\n‫مجمــوع أوزانهــا (‪)7073‬جــم‪ ،‬ســبعة آالف وثالثــة وســبعني جرامـاً‪ ،‬مــن‬\n‫مــادة احلشــيش املخــدر‪ .‬و أثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪/2130‬ك ش م) لعــام ‪1434‬ه ـ الصــادر مــن مركــز مراقبــة الســموم‬\n‫والكيميــاء الطبيــة الشــرعية بجــدة ايجابيــة عينــة ممــا ضبط للحشــيش‬\n‫املخــدر واحتوائهــا علــى املــادة الفعالــة لــه املــدرج بجــدول املــواد املخــدرة‬\n‫رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصادر باملرســوم امللكي رقم م‪ 39/‬بتاريخ ‪1426/7/8‬هـ وباســتجواب‬\n‫املدعــى عليــه األول أقــر بــأن قطــع احلشــيش املخــدر املضبوطــة عائــدة‬\n‫لشــقيقه املدعــى عليــه الثالــث‪ .‬باســتجواب املدعــى عليــه الثالــث‪ :‬أفــاد‬\n‫بــأن املضبوطــات لشــخص يدعــى هــرب عنــد القبــض عليهــم‪ .‬وأســفر‬\n‫التحقيــق عــن توجيــه االتهــام إلــى املدعــى عليهــم‪ :‬بحيــازة (‪ )7073‬جــم‪،‬‬\n‫ســبعة آالف وثالثــة وســبعني جرام ـ ًا مــن مــادة احلشــيش املخــدر بقصــد‬\n‫الترويــج والتعاطــي وتعاطــي الثالــث لنوعهــا مــن الســابق املجــرم اســتناد ًا‬\n‫للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة املنــوه عنــه وذلــك لألدلة والقرائن التاليــة‪.1 :‬ما ورد يف إقراراتهم‬\n\n\n                                                                                         ‫‪246‬‬\n\f      ‫املنــوه عنهــا واملدونــة علــى الصفحــات املرفقــة لفــة (‪.2 .)35،37،39‬‬\n      ‫شــهادة الشــهود الــواردة يف محضــر البــاغ و القبــض والتفتيــش املنــوه‬\n      ‫عنهــا واملدونــة علــى الصفحتــن رقــم (‪ )18-12‬من ملــف ضبط إجراءات‬\n      ‫االســتدالل املرفــق لفــه (‪.3 .)1‬مــا ورد يف التقريــر الكيميائــي الشــرعي‬\n      ‫املنــوه عنــه واملرفــق لفــه (‪.4 .)54‬كبــر الكميــة قرينــة علــى قصــد‬\n      ‫ترويجهــا‪ .‬وبالبحــث عــن ســوابقهم عثــر لــأول علــى خمســة ســوابق‪:‬‬\n      ‫ثالثــة منهــا ترويــج القــات وســابقتي حيــازة قــات كمــا عثــر للثالــث علــى‬\n      ‫ثالثــة ســوابق‪ :‬األولــى اختــاء محــرم مقترنــة بشــرب املســكرات وقيــادة‬\n      ‫الســيارة بحالــة ســكر والثانيــة‪ :‬حيــازة قــات والثالثــة‪ :‬مخــدرات‪ .‬بينمــا‬\n      ‫لــم يعثــر للثانــي علــى ســوابق وحيــث إن مــا أقــدم عليــه املدعــى عليهــم‬\n      ‫وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظامــا‬\n      ‫طبقـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫واملعاقــب عليهــا اســتنادا للمادتــن (‪ )38،41‬مــن النظــام املشــار إليــه مــع‬\n      ‫مراعــاة مــا ورد يف الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن ذات النظــام فيمــا‬\n      ‫يتعلــق بالثالــث لــذا فإننــي أطلــب إثبــات إدانتهــم مبــا أســند إليهــم‬\n      ‫واحلكــم عليهــم بالعقوبــات األصليــة والتكميليــة التاليــة‪.1 :‬الســجن‬\n      ‫واجللــد والغرامــة ‪ ،‬اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة املنــوه عنــه‪.2 .‬مصــادرة املبالــغ‬\n      ‫املاليــة املضبوطــة بحوزتهــم والبالــغ مجموعهــا (‪)1797‬ريــاالً‪ ،‬اســتناد ًا‬\n      ‫للفقــرة (‪ )2‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املنــوه عنــه‪.3 .‬إبعادهــم عــن اململكــة بعــد االنتهــاء مــن تنفيــذ‬\n      ‫عقوبتهــم اســتناد ًا للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة املنــوه عنــه‪ .‬كمــا أطلــب تشــديد العقوبــة‬\n\n\n‫‪247‬‬\n\f‫علــى األول والثالــث مبــا يردعهمــا لقــاء تعــدد ســوابقهما اســتنادا لتعميــم‬\n‫ســمو نائــب وزيــر الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ‬\n‫‪1429/8/23‬ه ـ هــذه دعــواي وبتــاوة الئحــة املدعــي العــام علــى املدعــى‬\n‫عليهــم احلاضريــن يف مجلــس احلكــم وســؤالهم اجلــواب أجــاب املدعــى‬\n‫ا مــا ذكــره املدعــي العــام مــن أنــه قبــض علـ ّـي مــن قبــل‬‫عليــه األول قائـ ً‬\n‫مكافحــة املخــدرات بتاريــخ ‪1434/06/06‬ه ـ فذلــك كلــه صحيــح‬\n‫وقــد كنــت أنــا وشــخص آخــر يدعــى وأخــي املدعــى الثالــث يف الســيارة‬\n‫وعنــد القبــض علينــا هــرب املدعــو وبعــد القبــض علينــا أخرجــوا مــن‬\n‫الســيارة التــي كنــت أقودهــا قطــع مــن احلشــيش ال عالقــة لــي بهــا وال‬\n‫عالقــة لنــا باملدعــى عليــه الثانــي فلــم نشــاهده قبــل هــذا اليــوم ومــا‬\n‫ذكــره املدعــي العــام مــن وجــود عــدد خمــس ســوابق منهــا ثــاث منهــا يف‬\n‫ترويــج القــات وســابقتني يف حيازتــه كلهــا مســجلة علـ ّـي فذلــك صحيــح‬\n‫أيضــا أمــا مــا طالــب بــه املدعــي العــام مــن مصــادرة املبلــغ الــذي بحوزتــي‬\n‫فهــو لــي وعائــد مــن غيــر الترويــج هكــذا أجــاب وأجــاب املدعــى عليــه‬\n‫ا كل مــا ذكــره املدعــي العــام مــن أنــه قبــض علـ ّـي مــن قبــل‬  ‫الثانــي قائـ ً‬\n‫مكافحــة املخــدرات بتاريــخ ‪1434/06/06‬ه ـ فذلــك كلــه صحيــح أمــا‬\n‫مــا ذكــره املدعــي العــام مــن قيامــي باالشــتراك يف حيــازة احلشــيش‬\n‫املخــدر مــع بقيــة املدعــى عليهــم فغيــر صحيــح جملــة وتفصيــا فــا‬\n‫عالقــة بــي بهــم وبحمــد اهلل ال توجــد لــدي ســوابق مســجلة أمــا مــا طالــب‬\n‫بــه املدعــي العــام مــن مصــادرة املبلــغ الــذي بحوزتــي فهــو لــي وعائــد مــن‬\n‫ا‬\n‫غيــر الترويــج علـ ّـي هكــذا أجــاب وأجــاب املدعــى عليــه الثالــث قائ ـ ً‬\n‫مــا ذكــره املدعــي العــام مــن أنــه قبــض علـ ّـي مــن قبــل مكافحــة‬\n‫املخــدرات بتاريــخ ‪1434/06/06‬ه ـ فذلــك كلــه صحيــح وقــد كنــت‬\n\n\n                                                                                         ‫‪248‬‬\n\f      ‫أنــا وشــخص آخــر يدعــى وأخــي املدعــى األول يف الســيارة وعنــد القبــض‬\n      ‫علينــا هــرب املدعــو وبعــد القبــض علينــا أخرجــوا مــن الســيارة التــي‬\n      ‫كنــت أركــب فيهــا قطعــا مــن احلشــيش ال عالقــة لــي بهــا وهــي عائــدة‬\n      ‫لصديقــي املدعــو وال عالقــة لنــا باملدعــى عليــه الثانــي فلــم نشــاهده قبــل‬\n      ‫هــذا اليــوم وصحيــح مــا ذكــره املدعــي العــام مــن أننــي كنــت راكبــا‬\n      ‫يف املقعــد اخللفــي ومــا ذكــره املدعــي العــام مــن أننــي تعاطيــت احلشــيش‬\n      ‫إلــى يــوم القبــض علــي فذلــك صحيــح أيضــا ومــا ذكــره املدعــي العــام‬\n      ‫مــن وجــود عــدد ثــاث ســوابق األولــى اختــاء محــرم مقترنــة بشــرب‬\n      ‫املســكرات وقيــادة الســيارة بحالــة ســكر والثانيــة‪ :‬حيــازة قــات‬\n      ‫والثالثــة‪ :‬مخــدرات مســجلة علـ ّـي فذلــك صحيــح أيضــا أمــا مــا طالــب بــه‬\n      ‫املدعــي العــام مــن مصــادرة املبلــغ الــذي بحوزتــي فهــو لــي وعائــد مــن غيــر‬\n      ‫الترويــج هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه علــى أن املدعى‬\n      ‫عليهــم كانــت الكميــة بحوزتهــم بقصــد الترويــج والتعاطــي وأن مــا‬\n      ‫وجــد معهــم مــن مبالــغ عائــد مــن ترويــج احلشــيش أجــاب قائــا بينتــي مــا‬\n      ‫ذكرتــه يف املعاملــة مــن أدلــة وقرائــن هكــذا أجــاب هــذا وقــد جــرى‬\n      ‫اطالعــي علــى أوراق املعاملــة وعلــى التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم(‪/2130‬ك ش م) لعــام ‪1434‬ه ـ املرفــق باملعاملــة لفــة رقــم (‪)54‬‬\n      ‫ويتضمــن إيجابيــة احتــواء العينــة للحشــيش املخــدر كمــا جــرى اطالعي‬\n      ‫علــى اقــرار املدعــى عليــه األول املرفــق باملعاملــة باللفــة رقــم (‪)37‬‬\n      ‫املتضمــن مــا نصــه أقــر أنــا مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ()‬\n      ‫أقــر وأنــا بكامــل قــواي العقليــة املعتبــرة شــرعا دون إكــراه أو إجبــار‬\n      ‫مــن احــد بأننــي مت القبــض علــى بتاريخ ‪1434/6/6‬هـ من قبل مكافحة‬\n      ‫املخــدرات أثنــاء تواجدنــا يف حــي الكنــدرة يف محــل جــواالت وكان‬\n\n\n‫‪249‬‬\n\f‫يرافقنــي أخــي ‪ /‬وشــخص مينــي اســمه ‪ /‬وكان املدعــو‪ /‬يف محــل‬\n‫اجلــواالت وليــس لنــا بــه عالقــة وليــس لــه أي علــم أو عالقــة مبــا ضبــط‬\n‫معنــا وبتفتيــش ســيارة أخــي ‪ /‬مــن نــوع (‪ )....‬صنــع (‪ )...‬لوحــه رقــم (‪)....‬‬\n‫لــون الســيارة (‪ ).....‬قمــت باســتئجارها وضبــط كيــس بداخلــة حشــيش‬\n‫مخــدر يــزن (‪ )7073‬ســبعه االف جــرام وثالثــة وســبعني جرامـ ًا ضبطــت‬\n‫يف املرتبــة اخللفيــة عائــد ألخــي ‪ /‬وصاحبــة حيــث كان مرافقــا لنــا يف‬\n‫الســيارة هــذا إقــرار منــي بذلــك وعليــه أوقــع كمــا جــرى اطالعــي علــى‬\n‫اقــرار املدعــى عليــه الثانــي املرفــق باملعاملــة باللفــة رقــم (‪ )35‬املتضمــن‬\n‫مــا نصــه أقــر أنــا مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم () أقــر وأنــا‬\n‫بكامــل قــواي العقليــة املعتبــرة شــرعا دون إكــراه أو إجبــار مــن احــد‬\n‫بأننــي مت القبــض علــى بتاريــخ ‪1434/6/6‬ه ـ مــن قبــل مكافحــة‬\n‫املخــدرات أثنــاء تواجدنــا يف حــي الكنــدرة يف محــل جــواالت وكان‬\n‫يرافقنــي املتهــم ‪ /‬واملتهــم وبتفتيــش ســيارة املتهــم ‪ /‬مــن نــوع (‪ )....‬صنــع‬\n‫(‪ )....‬لوحــه رقــم (‪ )....‬لــون الســيارة (‪ )....‬قمــت باســتئجارها ضبــط‬\n‫كيــس بداخلــة حشــيش مخــدر يــزن (‪ )7073‬ســبعه أالف جــرام وثالثــة‬\n‫وســبعني جرامـ ًا ضبطــت يف املرتبــة اخللفيــة ليــس بهــا أي علــم أو عالقــة‬\n‫وال اعــرف املتهمــن حيــث أنــي حضــرت للمحــل لشــراء جــوال‬\n‫وبإمكانكــم الرجــوع للمحــل للتأكــد وليــس لــي أي عالقــة باملتهمــن‬\n‫هــذا اقــرار منــي بذلــك وعليــه أوقــع كمــا جــرى اطالعــي علــى اقــرار‬\n‫املدعــى عليــه الثالــث املرفــق باملعاملــة باللفــة رقــم (‪ )39‬املتضمــن مــا‬\n‫نصــه أقــر انــا مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )...‬وتاريــخ‬\n‫‪1434/6/7‬ه ـ صــادرة مــن مكافحــة املخــدرات أقــر وأنــا بكامل قواي‬\n‫العقليــة املعتبــرة شــرعا دون إكــراه أو إجبــار مــن احــد بأننــي مت القبــض‬\n\n\n                                                                                         ‫‪250‬‬\n\f      ‫علــى بتاريــخ ‪1434/6/6‬ه ـ مــن قبــل مكافحــة املخــدرات أثنــاء تواجدنا‬\n      ‫يف حــي الكنــدرة يف محــل جــواالت وكان يرافقنــي أخــي ‪ /‬وشــخص‬\n      ‫مينــي اســمه ‪ /‬وكان املدعــو‪ /‬يف محــل اجلــواالت وليــس لنــا بــه عالقــة‬\n      ‫وليــس لــه أي علــم أو عالقــة مبــا ضبــط معنــا وبتفتيــش ســيارة أخــي ‪/‬‬\n      ‫مــن نــوع (‪ ).....‬صنــع (‪ ).....‬لوحــه رقــم (‪ )...‬لــون الســيارة (‪ )....‬قمــت‬\n      ‫باســتئجارها وضبــط كيــس بداخلــة حشــيش مخــدر يــزن (‪)7073‬‬\n      ‫ســبعه أالف جــرام وثالثــة وســبعني جرام ـ ًا ضبطــت يف املرتبــة اخللفيــة‬\n      ‫عائــد للشــخص الــذي كان معنــا‪ /‬حيــث كان مرافقــا لنــا يف الســيارة‬\n      ‫علمــا بأننــي أتعاطــى احلشــيش املخــدر منــذ خمــس ســنوات كان آخرهــا‬\n      ‫يــوم القبــض علــي هــذا إقــرار منــي بذلــك وعليــه أوقــع كمــا جــرى‬\n      ‫اطالعــي علــى شــهادة الشــهود يف محضــر القبــض املرفــق باملعاملــة‬\n      ‫باللفــة رقــم (‪ )1‬صحيفــة رقــم (‪ )13-12‬املتضمــن مــا نصــه بنــاء ملــا تقــدم‬\n      ‫جــرى اتخــاذ الــازم علــى النحــو التالــي جــرى االنتقــال يف متــام الســاعة‬\n      ‫السادســة مســاء برفقــة املصــدر ملوقــع املذكــور ومت البــدء يف اتخــاذ‬\n      ‫املوقــع املناســب علــى النحــو التالــي معاينــة املوقــع واتضــح أنــه عبــارة عــن‬\n      ‫شــارع وســط حــي البغداديــة وجــرى التمركــز بأحــد املواقــع الثانيــة‬\n      ‫وذلــك يف متــام الســاعة السادســة مســاء رصــد املوقــع ويف متــام الســاعة‬\n      ‫التاســعة شــوهدت ســيارة مــن نــوع (‪ ).....‬حتمــل اللوحــة رقــم (‪ )....‬بقيــادة‬\n      ‫شــخص ويرافقــه شــخصان آخــران أشــار املصــدر بــأن قائــد الســيارة هــو‬\n      ‫املقصــود ومتــت متابعتهــم حتــى وصلــوا حلــي الكنــدرة وأوقفــوا الســيارة‬\n      ‫وترجلــوا احــد محــات االتصــاالت وبالقبــض والتفتيــش ومت القبــض‬\n      ‫عليهــم وهــم املدونــة أســمائهم عوضــه األول املقصــود والثانــي املرافــق‬\n      ‫باملرتبــة األماميــة والثالــث املرافــق باملرتبــة اخللفيــة خلــف الســائق‬\n\n\n‫‪251‬‬\n\f‫وبتفتيشــهم شــخصيا لــم يعثــر بحوزتهــم علــى أي مــن املمنوعــات‬\n‫ومبناقشــتهم عــن الســيارة أنكروهــا وبتفتيــش الســيارة عثــر مــكان‬\n‫أقــدام الراكــب اخللفــي خلــف الســائق كيــس نايلــون اخضــر ملفــوف‬\n‫كبيــر احلجــم اتضــح بداخلــة ســبع قطــع مســتطيلة الشــكل مغلفــة‬\n‫بغــاف وضعــي بالســتيكي جميعهــا ســوداء اللــون يشــتبه أنهــا حشــيش‬\n‫مخــدر ومبناقشــة املتهمــن األول والثانــي والثالــث عــن مــا ضبــط‬\n‫بالســيارة أنكروهــا جميعــا وعــن مقــر ســكنهم املقصــود بأنــه يســكن‬\n‫بحــي ‪ ......‬والثالــث يســكن بقربــة يف حــي ‪ ........‬والثالــث أفــاد بأنــه ال‬\n‫يوجــد لديــه ســكن وبتفتيــش منــزل األول وهــو عبــارة عــن شــقة بعمــارة‬\n‫بحــي ‪ .....‬لــم يعثــر علــى شــيء مــن املمنوعــات واتضــح أن الثالــث يســكن‬\n‫بقربــة يف حــي الكنــدرة مكونــة مــن غرفــة مبنافعهــا لــم يعثــر بهــا علــى‬\n‫شــيء مــن املمنوعــات اتضــح أن للســيارة عقــد إيجــار باســم املقصــود‬\n‫األول مســتأجرة مــن شــركة (‪ ).....‬كمــا جــرى اطالعــي علــى محضــر‬\n‫البــاغ يف محضــر القبــض املرفــق باملعاملــة باللفــة رقــم (‪ )1‬صحيفــة رقــم‬\n‫(‪ )2‬املتضمــن مــا نصــه احلمــد هلل وحــدة والصــاة والســام علــى مــن ال‬\n‫نبــي بعــده أمــا بعــد فقــد جــرى بتاريــخ ‪1434/06/06‬ه ـ فتــح هــذا‬\n‫احملضــر مبكتــب الفرقــة امليدانيــة اخلامســة بقســم القيــادة والســيطرة‬\n‫بشــبعة التحريــات بــإدارة مكافحــة املخــدرات مبحافظــة جــدة وذلــك‬\n‫بنــاء للســيطرة علــى مروجــي املخدرات على مســتوى جــدة وحث املصادر‬\n‫الســرية على تزويدنا باملعلومات عنهم وعن وســائل تنقلهم ومســاكنهم‬\n‫واألماكــن التــي يتواجــدون فيهــا ومــن ضمــن هــؤالء األشــخاص شــخص‬\n‫يدعــي مينــي اجلنســية اشــتهر يف أوســاط مروجــي ومتعاطــي احلشــيش‬\n‫املخــدر ولــم تعــرف معلومــات كافيــة عنــه للقبــض عليــه باجلــرم املشــهود‬\n\n\n                                                                                    ‫‪252‬‬\n\f      ‫فقــد كان مــن ضمــن األشــخاص الذيــن نســعى للقبــض عليهــم ولذلــك‬\n      ‫جــرى حــث مصادرنــا بتزويدنــا مبــا يتوفــر عنــه مــن معلومــات وبتاريخــه‬\n      ‫أعــاه أبلغنــا أحــد مصادرنــا الســرية بتوصلــه ملعلومــات عــن مــكان ميــر‬\n      ‫منــه املقصــود وذلــك بحــي البغداديــة وذكــر املصــدر انــه لــم يســتطيع‬\n      ‫التوصــل الــى مســكنه أو وســيلة االتصــال بــه واســتعد باإلرشــاد علــى‬\n      ‫املوقــع وبنــاء عليــه متــت املباشــرة مبــا ذكــر حســب مــا يتضــح يف ثنايــا‬\n      ‫هــذا امللــف كمــا جــرى اطالعــي علــى صحيفــة ســوابق املدعــى عليــه‬\n      ‫األول املرفقــة باملعاملــة باللفــة رقــم (‪ )48-47‬املتضمنــة وجــود عــدد‬\n      ‫خمــس ســوابق منهــا ثــاث منهــا يف ترويــج القــات وســابقتني يف حيازتــه‬\n      ‫كلهــا مســجلة علــى املدعــى عليــه كمــا جــرى اطالعــي علــى صحيفــة‬\n      ‫ســوابق املدعــى عليــه الثالــث املرفقــة باملعاملــة باللفة رقــم (‪ )51‬املتضمنة‬\n      ‫وجــود عــدد ثــاث ســوابق منهــا عــدد ثــاث ســوابق األولــى‪ :‬اختــاء‬\n      ‫محــرم مقترنــة بشــرب املســكرات وقيــادة الســيارة بحالــة ســكر‬\n      ‫والثانيــة‪ :‬حيــازة قــات والثالثــة‪ :‬حيــازة حشــيش وقــات للتعاطــي كلهــا‬\n      ‫مســجلة علــى املدعــى عليــه كمــا جــرى اطالعــي علــى صحيفــة ســوابق‬\n      ‫املدعــى عليــه الثانــي املرفقــة باملعاملــة باللفــة رقــم ( ‪ ) 53‬املتضمنــة عــدم‬\n      ‫وجــود أيــة ســوابق مســجلة علــى املدعــى عليــه وبســؤال املدعــى عليــه‬\n      ‫األول والثالــث عــن احلشــيش أجابــا هــو للمدعــو وبســؤال األول عــن‬\n      ‫احلشــيش أجــاب قائــا هــو ألخــي وزميلــه هكــذا أجــاب عليــه فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره أطــراف الدعــوى وإلنــكار‬\n      ‫املدعــى عليهــم حيــازة الكميــة املضبوطــة بقصــد الترويــج وإنكارهــم‬\n      ‫معرفتهــم بوجودهــا وملــا ذكــره املدعــى عليهمــا األول والثالــث مــن وجود‬\n      ‫كميــة احلشــيش بالســيارة ووجودهــا بجانــب الثالــث يف اخللــف ومــا‬\n\n\n‫‪253‬‬\n\f‫قــرراه مــن عــدم معرفتهمــا باملدعــى عليــه الثانــي وكــون القبــض كان‬\n‫يف ســوق وإنــكار املدعــى عليــه الثانــي معرفتــه بهمــا ولعــدم وجــود‬\n‫ســوابق مســجلة عليــه وملــا ذكــره املدعــي العــام مــن أدلــة وقرائــن وملــا‬\n‫تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه بعاليــة ألجــل ذلــك‬\n‫كلــه فقــد ثبــت لــدي تعاطــي املدعــى عليــه الثالــث للحشــيش املخــدر من‬\n‫الســابق كمــا ثبــت لــدي إدانــة املدعــى عليهمــا األول والثالــث‬\n‫املذكوريــن بعاليــه مبــا نســب إليهمــا مــن اشــتراكهما بحيــازة (‪)7073‬‬\n‫جــم‪ ،‬ســبعة آالف وثالثــة وســبعني جرامـ ًا حتتــوي علــى احلشــيش املخــدر‬\n‫حيــازة مجــردة كمــا لــم يثبــت لــدي إدانــة املدعــى عليهــم املذكوريــن‬\n‫بعاليــه مبــا نســب إليهــم مــن اشــتراك املدعــى عليهــم بحيــازة (‪)7073‬‬\n‫جــم‪ ،‬ســبعة آالف وثالثــة وســبعني جرامـ ًا حتتــوي علــى احلشــيش املخــدر‬\n‫لقصــد الترويــج والتعاطــي لهــا إال أن الشــبهة تتجــه نحــو املدعــى عليهمــا‬\n‫األول والثالــث بحيازتهمــا لســبعة آالف وثالثــة وســبعني جرام ـ ًا حتتــوي‬\n‫علــى احلشــيش املخــدر لقصــد الترويــج والتعاطــي لهــا وذلــك للقرائــن‬\n‫التاليــة‪ :‬أوال‪ :‬وجــود الكميــة يف الســيارة التــي يســتقالنها‪ .‬ثانيــا‪ :‬عــدم‬\n‫قدرتهمــا علــى إثبــات أن الكميــة املضبوطــة عائــدة للشــخص املدعــو‬\n‫‪ ......‬وعــدم إرشــادهما عنــه‪ .‬ثالثــا‪ :‬وجــود ســوابق علــى املدعــى عليهمــا‪.‬‬\n‫رابعــا‪ :‬تعاطــي الثالــث مــن احلشــيش يقــوى الشــبه نحــوه‪ .‬خامســا‪ :‬وجــود‬\n‫املدعــى عليــه الثالــث باملقعــد اخللفــي حيــث وجــدت الكميــة‪ .‬سادســا‪:‬‬\n‫وجــود إخباريــة تفيــد أن املدعــى عليــه األول يقــوم بترويــج احلشــيش‪ .‬ولــم‬\n‫يتوجــه لــدي اجتــاه املدعــى عليــه الثانــي أي شــبهة وذلــك ملــا يلــي‪:‬‬\n‫وإنــكاره معرفــة املدعــى عليهمــا األول والثالــث ثانيــا‪ /‬مــا ذكــره‬\n‫املدعــى عليهمــا األول والثالــث مــن عــدم معرفتهمــا باملدعــى عليــه الثانــي‬\n\n\n                                                                                    ‫‪254‬‬\n\f      ‫ثالثــا‪ :‬كــون القبــض كان يف ســوق ويحتمــل أن يكــون القبــض علــى‬\n      ‫شــخص آخــر غيــر املطلــوب نظــرا ملــا هــو مشــاهد مــن ازدحــام عنــد‬\n      ‫مراكــز االتصــاالت‪ .‬رابعــا‪ :‬عــدم وجــود ســوابق مســجلة عليــه خامســا‪:‬‬\n      ‫مــا اســتند إليــه املدعــي العــام هــو اعتــراف املذكــور وباالطــاع عليــه‬\n      ‫وجدتــه ال يدينــه مبــا نســب إليــه سادســا‪ :‬أن غايــة مــا قدمــه املدعــي‬\n      ‫العــام اجتاهــه هــو مــا جــاء يف محضــر القبــض مــن أن املدعــى عليــه‬\n      ‫قبــض عليــه مــن قبــل الفرقــة‪ .‬ســابعا‪ :‬أن األصــل بــراءة الذمــة وال يجــوز‬\n      ‫شــغلها إال بيقــن يف ثبــوت التهمــة أو االدانــة والدليــل إذا ورد عليــه‬\n      ‫االحتمــال ســقط بــه االســتدالل ثامنــا‪ :‬أنــه ال يجــوز إيقــاع عقوبــة جزائيــة‬\n      ‫إال بعــد ثبــوت اإلدانــة وفقــا للمــادة الثالثــة مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫قبيحــا‬\n          ‫ً‬     ‫ا‬\n                ‫محرمــا وفع ـ ً‬\n                           ‫ً‬     ‫ا‬\n                                 ‫ومبــا أن مــا قــام بــه املدعــى عليهمــا يعــد عم ـ ً‬\n      ‫وجــرأة يف الباطــل يســتحقا العقــاب عليــه ومبــا أن ترويــج ذلــك فيــه نشــر‬\n      ‫للفســاد أوســاط املجتمــع وهــو مــن التعــاون علــى اإلثــم والعــدوان واهلل‬\n      ‫ســبحانه وتعالــى يقــول (وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى‬\n      ‫اإلثــم والعــدوان) ومبــا أن تعاطــي احلشــيش املخــدر يــؤول إلــى االســكار‬\n      ‫واهلل تعالــى يقــول‪ ( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n      ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر حــرام ) وملــا‬\n      ‫يف ذلــك مــن إضــرار بنفــس اإلنســان وعقلــه والواجــب عليــه حفظهمــا‬\n      ‫والشــريعة اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا حفــظ‬\n      ‫النفــس والعقــل والنتشــار هــذه احملظــورات أوســاط املجتمــع وهــذا‬\n      ‫يســتوجب األخــذ علــى مــن يقــوم بترويجهــا بحــزم الســيما مــع كثــرة‬\n      ‫ســوابق املدعى عليهما األول والثالث ولكون املدعى عليهم يســتحقون‬\n\n‫‪255‬‬\n\f‫طبقــا للقواعــد الشــرعية وكــون املدعــى عليهمــا األول الثالــث‬   ‫العقوبــة ً‬\n‫وفقــا للمــادة (‪ )56 -39‬مــن نظــام مكافحــة‬       ‫يســتحقا العقوبــة أيضــا ً‬\n‫املخــدرات فلمــا ســبق فقــد حكمــت علــى املدعــى عليهــم تعزيــر ًا مبــا‬\n‫يلــي‪ :‬أوالً‪ :‬إقامــة حــد املســكر علــى املدعــى عليــه الثالــث وذلــك بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة أمــام مــأ مــن النــاس لقــاء تعاطيــه للحشــيش‬\n‫املخــدر مــن الســابق ثانيـاً‪ :‬يســجن كل واحــد مــن املدعــى عليهمــا األول‬\n‫موقوفــا يف هــذه القضيــة‬\n                        ‫ً‬     ‫والثالــث ملــدة ســنتني يحتســب منهــا مــا أمضــاه‬\n‫ويجلــد كل واحــد منهمــا خمســن جلــدة مكــررة عليــه أربــع مــرات بــن‬\n‫كل مــرة وأخــرى مــدة ال تقــل عــن خمســة عشــر يومــا ويكــون بــن هــذا‬\n‫اجللــد وجلــد احلــد بالنســبة لــأول مــدة ال تقــل عــن خمســة عشــر يومــا‬\n‫ويدفــع كل واحــد منهمــا غرامــة ماليــة قدرهــا خمســة االف ريــال وفقــا‬\n‫للمــادة رقــم (‪ )39‬مــن النظــام املشــار إليــه‪ .‬ثالثــا‪ :‬يبعــد املدعــى عليهمــا‬\n‫األول الثالــث خــارج اململكــة وال يســمح لــه بالعــودة إليهــا إال وفــق‬\n‫تعليمــات احلــج والعمــرة وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن‬\n‫نظــام مكافحــة املخــدرات املشــار إليــه وذلــك لقــاء تعاطيــه للحشــيش‬\n‫املخــدر‪ .‬رابعــا‪ :‬رددت مطالبــة املدعــي العــام بتطبيــق الوصــف اجلرمــي‬\n‫الــوارد يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة والفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬من ذات النظام‬\n‫ومطالبتــه بالغرامــة والســجن واجللــد للمدعــى عليهــم وابعــاد املدعــى‬\n‫عليهمــا األول والثانــي وذلــك لعــدم قــدرة املدعــي العــام علــى اثبــات‬\n‫الوصــف اجلرمــي الــوراد يف املادتــن‪ .‬خامســا‪ :‬رددت مطالبــة املدعــي‬\n‫العــام بتطبيــق الوصــف اجلرمــي الــوارد يف الفقــرة (‪ )2‬مــن املــادة (‪)53‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ومصــادرة املبالــغ‬\n\n\n                                                                                       ‫‪256‬‬\n\f      ‫املاليــة املضبوطــة بحــوزة املدعــى عليهــم والبالــغ مجموعهــا (‪)1797‬ريــا ًال‬\n      ‫وذلــك لعــدم قــدرة املدعــي العــام علــى اثبــات الوصــف اجلرمــي الــوراد يف‬\n      ‫املــادة وعــدم قدرتــه علــى اثبــات عائديــة املبالــغ مــن الترويــج‪ .‬سادســا‪:‬‬\n      ‫يســجن كل واحــد مــن املدعــى عليهمــا األول والثالــث ملــدة ســنة تبــدأ‬\n      ‫مــن تاريــخ انتهــاء مــدة الســجن احملكــوم بهــا يف ثانيــا ويجلــد كل واحــد‬\n      ‫منهمــا خمســن جلــدة مكــررة عليــه أربــع مــرات بــن كل مــرة وأخــرى‬\n      ‫مــدة ال تقــل عــن خمســة عشــر يومــا ويكــون بــن هــذا اجللــد واجللــد‬\n      ‫الســابق مــدة ال تقــل عــن خمســة عشــر يومــا وذلــك لقــاء االشــتباه بهمــا‬\n      ‫فيمــا نســب إليهمــا‪ .‬سادســا‪ :‬أخليــت ســبيل املدعــى عليــه الثانــي وأمــرت‬\n      ‫باإلفــراج عنــه وفقــا للمــادة السادســة عشــرة بعــد املائتــن مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة وذلــك مبوجــب كتابــي رقــم ‪ 341935759‬وتاريــخ‬\n      ‫‪1434/08/09‬ه ـ وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n      ‫معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه‬\n      ‫باحلضــور يف يــوم األربعــاء املوافــق ‪1434/8/10‬ه ـ الســاعة ‪08 :00‬‬\n      ‫الســتالم نســخة مــن قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال مــدة‬\n      ‫ثالثــن يومــا اعتبــار ًا مــن التاريــخ املشــار إليــه فــان مضــت املــدة ولــم‬\n      ‫يســتلم نســخة مــن احلكــم أو لــم يقــدم اعتراضــه عليــه خاللهــا فــان حقــه‬\n      ‫يف تقــدمي الئحــة االعتــراض يكــون ســاقط ًا كمــا قــرر املدعــى عليهــم‬\n      ‫قناعتهــم بــه وجــرى النطــق باحلكــم يف يــوم الثالثــاء املوافــق‬\n      ‫‪1434/08/09‬ه ـ الســاعة ‪ 11 :00‬وبــه أقفلــت اجللســة وعلــى ذلــك جــرى‬\n      ‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                     ‫‪1434/08/09‬هـ ‪.‬‬\n      ‫احلمــد اهلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ....‬نحــن رئيــس‬\n\n\n‫‪257‬‬\n\f‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقة مكة‬\n‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 34293242‬وتاريــخ‬\n‫‪1434/8/9‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ....‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪ ....‬مينــي‬\n‫اجلنســية ورفيقيــه ‪ ،‬املتهمــن بحيــازة مخــدرات‪ ،‬احملكــوم فيــه مبــا دون‬\n‫باطنــه‪ .‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                            ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                  ‫‪258‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":243,"source_page_end":258,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5875388b8dcfbc51a83634c11a5e7e9090f38180ce324f7fc2277c52bea1d254","normalized_text_hash":"90b45546e5412e1a700a4a71018ddc545f207da6d7a9c1221d825728d7e7c883","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p243-34293242"},{"id":"778657fb-fd4a-546a-8669-1072a52b0c2d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة -اشتراك يف حيازة بقصد الترويج والتعاطي- قات -تداخل العقوبات التعزيرية -التعزير بالسجن واجللد .","document_number":"34298921","case_number":"34377739","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/16","year":"1434","subject":"مخدرات -حيازة -اشتراك يف حيازة بقصد الترويج والتعاطي- قات -تداخل العقوبات التعزيرية -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34298921:‬تاريخه‪1434/8/16:‬هـ‬\n                        ‫رقم القضية‪34377739:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34367386‬تاريخه‪1434/11/21:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة ‪ -‬اشــتراك يف حيــازة بقصــد الترويــج والتعاطــي‪-‬‬\n        ‫قــات ‪ -‬تداخــل العقوبــات التعزيريــة‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫‪ -1‬مــا رواه ابــن عبــاس قــال ( لعــن رســول اهلل صلــى اهلل عليــه وســلم‬\n      ‫املتشــبهني مــن الرجــال بالنســاء واملتشــبهات مــن النســاء بالرجــال )‪.‬‬\n                                                              ‫أخرجــه البخــاري‬\n      ‫‪ -2‬مــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة حيــث جــاء‬\n      ‫يف كشــاف القنــاع ج ‪ 485/ 20‬للبهوتــي ( ولــو توجــه عليــه تعزيــرات‬\n      ‫علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل‬\n      ‫أجنبيــة مــرارا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــدا‬\n                                            ‫تداخلــت وكفــاه تعزيــر واحــد ) ‪.‬‬\n      ‫‪ -3‬املادة الرابعة من قرار وزير الداخلية رقم (‪ )2057‬يف ‪1404/5/26‬هـ‪.‬‬\n                             ‫‪ -4‬القرار الوزاري رقم (‪ )3818‬يف ‪ 1410/9/28‬هـ ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه األول باالشــتراك يف حيــازة‬\n      ‫قــات بقصــد الترويــج والتعاطــي والتشــبه بالنســاء لتضليــل رجــال‬\n      ‫األمــن ‪،‬واملدعــى عليــه الثانــي بحيــازة قــات بقصــد الترويــج والتعاطــي‬\n\n‫‪259‬‬\n\f‫وطلــب إثبــات مــا أســند إليهمــا ومعاقبتهــا تعزيــرا ‪،‬حيــث مت االشــتباه‬\n‫يف الســيارة التــي يقودهــا املدعــى عليــه الثانــي عنــد نقطــة التفتيــش‬\n‫ويرافقــه املدعــى عليــه األول بــزي نســائي وعنــد تفتيــش الســيارة عثــر‬\n‫علــى القــات وأثبــت التقريــر الكيميائــي إيجابيــة العينــة املضبوطــة‬\n‫لنبــات القــات احملظــور ‪ ،‬صــادق املدعــى عليهمــا علــى دعــوى املدعــي‬\n‫العــام ماعــدا الترويــج فأنكــرا ذلــك ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n‫احملكمــة بســجنهما ثمانيــة أشــهر وجلدهمــا ســبعني جلــدة دفعــة واحــدة‬\n‫‪،‬وصــدق‬\n      ‫‪،‬وقنــع املدعــى عليهمــا اعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                      ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )341953035‬وتاريــخ ‪1434/8/13‬هـ‬\n‫واحملالة من فضيلة الرئيس برقم (‪ )34377739‬وتاريخ ‪1434/8/13‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪.....‬و‪ .....‬املتهمــن يف قضيــة حيــازة‬\n‫لنبــات القــات عليــه ففــي هــذا اليــوم االثنــن ‪1434/8/15‬ه ـ افتتحــت‬\n‫اجللســة األولــى يف متــام الســاعة الثانيــة عشــرة وفيهــا حضــر املدعــي العــام‬\n‫‪ .....‬املوجــه باخلطــاب رقــم (‪ ).....‬وتاريــخ ‪1431/8/14‬ه ـ وادعــى علــى‬\n‫احلاضريــن ‪.....‬ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله‬\n‫املدنــي (‪ ).....‬و‪ .....‬ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله‬\n‫املدنــي (‪ ).....‬أنــه بتاريــخ ‪1434/7/3‬ه ـ وأثنــاء قيــام الدوريــات األمنيــة‬\n‫بشــرطة العارضــة بواجبهــا يف نقطــة تفتيــش احلظــوة قدمــت ســيارة مــن‬\n\n                                                                                       ‫‪260‬‬\n\f      ‫نــوع ‪ ....‬مــن صنــع عــام (‪2009‬م) حتمــل اللوحــة رقــم (‪ .....‬مت تســليم‬\n      ‫الســيارة) كانــت بقيــادة املدعــى عليــه ‪ .....‬ترافقــه امــرأة حســب أقــوال‬\n      ‫قائــد الســيارة أنهــا زوجتــه وأبــرز لهــم كــرت العائلــة كإثبــات عائلتــه‬\n      ‫وتدعــى ‪.....‬وعنــد االشــتباه يف وضــع العائلــة اتضــح أنــه رجــل ويرتــدي‬\n      ‫الــزي النســائي ويدعــى ‪.....‬وبتفتيــش الســيارة عثــر علــى كميــة مــن نبات‬\n      ‫القــات احملظــور كانــت مخبــأة داخــل املرتبــة اخللفيــة والصــدام اخللفــي‬\n      ‫للســيارة بلــغ وزنهــا (‪25‬كجــم) خمســة وعشــرين كيلــو جــرام وقــد‬\n      ‫أثبــت التقريــر الكيميائــي الشــرعي رقــم(‪ ).....‬وتاريــخ ‪1434/7/11‬ه ـ‬\n      ‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n      ‫بجــازان إيجابيــة العينــة املرســلة منــه لنبــات القــات احملظــور املــدرج علــى‬\n      ‫اجلــدول رقــم (‪ )4‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة علم ًا‬\n      ‫ـاء علــى القــرار الــوزاري (‪ )1900‬يف ‪1428/7/9‬ه ـ‬          ‫أنــه مت إيقافهمــا بنـ ً‬\n      ‫املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة وباســتجواب‬\n      ‫املدعــى عليــه ‪.....‬ومواجهتــه بالتهمــة املنســوبة إليــه أقــر بصحــة واقعــة‬\n      ‫القبــض وذكــر بــأن الكميــة تعــود لــه ولقائــد الســيارة‪.....‬بقصد‬\n      ‫التعاطــي وأنــه حصــل عليهــا مــن محافظــة العارضــة مــن شــخص مينــي ال‬\n      ‫يعــرف اســمه لقيــه خلــف الســوق الشــعبي وأنــه حصــل علــى الكميــة عــن‬\n      ‫طريــق الشــراء مببلــغ قــدره (‪5000‬ريــال) خمســة آالف ريــال مناصفــة‬\n      ‫بينــه وبــن مرافقــه وأنــه كان ينــوي إيصــال الكميــة ملنزلــه الكائــن‬\n      ‫بقريــة ‪.....‬التابعــة حملافظــة العارضــة لغــرض تعاطيهــا وأنــه يقــوم بحفــظ‬\n      ‫القــات داخــل ثالجــة باملنــزل ويتنــاول يوميـ ًا حوالــي أربــع حــزم مــن نبــات‬\n      ‫القــات وأنــه لبــس العبــاءة النســائية خوفـ ًا مــن رجــال األمــن وقــد صــادق‬\n      ‫علــى أقوالــه حتقيقــا وباســتجواب املدعــى عليــه ‪ .....‬ومواجهتــه بالتهمــة‬\n\n\n‫‪261‬‬\n\f‫املنســوبة إليــه أقــر بصحــة واقعــة القبــض وذكــر أن الكميــة تعــود لــه‬\n‫وملرافقــه ‪.....‬بقصــد التعاطــي وأنــه حصــل عليهــا مــن محافظــة العارضــة‬\n‫مــن شــخص مينــي ال يعــرف اســمه لقيــه خلــف الســوق الشــعبي وأنــه‬\n‫حصــل علــى الكميــة عــن طريــق الشــراء مببلــغ قــدره (‪5000‬ريــال)‬\n‫ثالثــة آالف ريــال مناصفــة بينــه وبــن مرافقــه وأنــه كان ينــوي إيصــال‬\n‫الكميــة ملنزلــه الكائــن بقريــة ‪.....‬التابعــة حملافظــة العارضــة لغــرض‬\n‫تعاطيهــا وأنــه يقــوم بحفــظ القــات داخــل ثالجــة باملنــزل ويتنــاول يومي ـ ًا‬\n‫حوالــي ســت حــزم مــن نبــات القــات وأن الســيارة تعــود ألخيــه املدعــو ‪.....‬‬\n‫وليــس لــه علــم أو عالقــة بالكميــة املضبوطــة وأنــه ألبــس مرافقــه ‪.....‬‬\n‫عبــاءة نســائية وقــدم كــرت العائلــة للدوريــة األمنيــة علــى أنهــا زوجتــه‬\n‫وقــد صــادق علــى أقوالــه حتقيقــا وقــد أســفر التحقيــق مــع املدعــى‬\n‫عليهمــا عــن توجيــه االتهــام إلــى ‪.....‬باالشــتراك يف حيــازة مــا وزنــه‬\n‫(‪25‬كجــم) خمســة وعشــرين كيلــو جــرام مــن نبــات القــات احملظــور‬\n‫بقصــد الترويــج والتعاطــي والتشــبه بالنســاء لتضليــل رجــال األمــن‬\n‫وتوجيــه االتهــام إلــى ‪.....‬بحيــازة مــا وزنــه (‪25‬كجــم) خمســة وعشــرين‬\n‫كيلــو جــرام مــن نبــات القــات احملظــور بقصــد الترويــج والتعاطــي‬\n‫واملجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ وألن مــا أقــدم عليــه املدعــى عليهمــا فعــل محــرم‬\n‫شــرع ًا ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات فقــد طلــب املدعــي العــام إثبــات‬\n‫إدانتهمــا مبــا أســند إليهمــا واحلكــم بتعزيرهمــا يف ضــوء املادتــن الثالثــة‬\n‫والرابعــة مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذا لألمــر الســامي‬\n\n\n                                                                                      ‫‪262‬‬\n\f      ‫الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ واحلكــم بتعزيــر املتهــم‬\n      ‫األول لقــاء قيامــه مبحاولــة تضليــل رجــال األمــن والتشــبه بالنســاء‬\n      ‫وبعــرض الدعــوى علــى املدعــى عليه األول صدق القبض عليه يف الزمان‬\n      ‫واملــكان املشــار إليهمــا واشــتراكه يف حيــازة كميــة القــات املضبوطــة‬\n      ‫بقصــد االســتعمال الشــخصي وارتــداءه للعبــاءة النســائية عنــد القبــض‬\n      ‫بقصــد التخفــي لتجــاوز نقطــة التفتيــش هكــذا أجــاب وأنكــر قصــد‬\n      ‫الترويــج وبعــرض الدعــوى علــى املدعــى عليــه الثانــي صــدق القبــض‬\n      ‫عليــه يف الزمــان واملــكان املشــار إليهمــا واشــتراكه يف حيــازة كميــة‬\n      ‫القــات املضبوطــة بقصــد االســتعمال الشــخصي وأنــه أبــرز صــورة مــن‬\n      ‫ســجل أســرته لرجــال األمــن وذكــر لهــم أن مرافقــه امــرأة وأنهــا زوجتــه‬\n      ‫وأقــر بأنــه قبــل الوصــول إلــى نقطــة التفتيــش أشــار علــى املدعــى عليــه‬\n      ‫األول بارتــداء العبــاءة النســائية بقصــد التخفــي لتجــاوز نقطــة التفتيــش‬\n      ‫هكــذا أجــاب وأنكــر قصــد الترويــج عنــد ذلــك جــرى ســؤال املدعــي‬\n      ‫ا‬\n      ‫العــام هــل لديــك بينــة علــى قصــد املدعــى عليهمــا للترويــج فأجــاب قائـ ً‬\n      ‫بينتــي مــا يف أوراق املعاملــة إضافــة إلــى كبــر حجــم الكميــة املضبوطــة‬\n      ‫هكــذا أجــاب وبالرجــوع إلى أوراق املع ــاملة جــرى االطالع على التقرير‬\n      ‫الكيميائــي الشــرعي وثبــت ســوابق املدعــى عليهمــا فوجــدت مطابقــة‬\n      ‫ملــا يف الدعــوى كمــا جــرى االطــاع علــى بقيــة لفــات املعاملــة ولــم أجــد‬\n      ‫بهــا مــا يديــن املدعــى عليهمــا بقصــد الترويــج ســوى قرينــة كبــر حجــم‬\n      ‫الكميــة عنــد ذلــك جــرى ســؤال املدعــي العــام هــل لديــك مزيــد بينــة‬\n      ‫ا ال أعلــم لــي مزيــد بينــة هكــذا أجــاب عليــه فبنــاء علــى مــا‬\n                                                                           ‫فأجــاب قائـ ً‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وملــا رواه ابــن عبــاس رضــي اهلل عنهمــا قــال‬\n      ‫لعــن رســول اهلل صلــى اهلل عليــه وســلم املتشــبهني مــن الرجــال بالنســاء‬\n\n\n‫‪263‬‬\n\f‫واملتشــبهات مــن النســاء بالرجــال رواه البخــاري (‪ )2207/5‬برقــم‬\n‫(‪ )5546‬وملــا تضمنــه األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ يف فقرتــه األولــى مــن املوافقــة علــى أن تطبــق احملاكــم‬\n‫علــى مرتكبــي جرائــم القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة ولعجــز املدعــي العــام عــن‬\n‫إقامــة البينــة املثبتــة إلدانــة املدعــى عليــه بقصــد الترويــج فقــد قــررت‬\n‫مــا يلــي أوال ثبتــت لــدي إدانــة املدعــى عليــه األول بلبســه الــزي النســائي‬\n‫بقصــد التخفــي وجتــاوز نقطــة التفتيــش وهــو يســتحق العقوبــة التعزيريــة‬\n‫لقــاء ذلــك ثانيــا ثبتــت لــدي إدانــة املدعــى عليــه الثانــي بتضليــل رجــال‬\n‫األمــن بدعــواه أن مرافقــه امــرأة وأنهــا زوجتــه وإبــرازه صــورة مــن ســجل‬\n‫أســرته بقصــد جتــاوز نقطــة التفتيــش وهــو يســتحق العقوبــة التعزيريــة‬\n‫لقــاء ذلــك ثالثــا لــم تثبــت لــدي إدانــة املدعــى عليهمــا بقصــد الترويــج‬\n‫وصرفــت النظــر عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليهمــا‬\n‫ومجازاتهمــا يف ضــوء املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ وثبتــت لــدي إدانــة املدعــى عليهمــا باالشــتراك يف حيــازة‬\n‫كميــة القــات املذكــورة أعــاه بقصــد التعاطــي وهمــا يســتحق العقوبــة‬\n‫علــى ذلــك وفــق املــادة (‪ )4‬مــن قــرار ســمو زيــر الداخليــة رقــم (‪)2057‬‬\n‫وتاريــخ ‪1404/5/26‬ه ـ املعدلــة بالقــرار الــوزاري رقــم (‪ )3818‬وتاريــخ‬\n‫‪1410/9/28‬ه ـ وملــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة‬\n‫قــال العالمــة البهوتــي (ولــو توجــه عليــه تعزيــرات علــى معــاص شــتى‬\n‫فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل أجنبيــة مــرار ًا أو‬\n‫اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــد ًا تداخلــت وكفــاه‬\n‫تعزيــر واحــد) كشــاف القنــاع عــن مــن اإلقنــاع (ج‪20‬ص‪ )485‬لذلــك‬\n\n\n                                                                                      ‫‪264‬‬\n\f      ‫كلــه فقــد قــررت االكتفــاء مبجــازاة املدعــى عليهمــا لقــاء حيازتهمــا‬\n      ‫لكميــة القــات املضبوطــة بقصــد االســتعمال الشــخصي ونظــرا لكبــر‬\n      ‫حجــم الكميــة فــإن ذلــك يوجــه إليهمــا الشــبهة بقصــد الترويــج وقــد‬\n      ‫حكمــت علــى املدعــى عليــه األول لذلــك تعزيــرا بالســجن مــدة ثمانيــة‬\n      ‫أشــهر تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة‬\n      ‫يف ‪1434/7/3‬ه ـ وجلــده ســبعني جلــدة دفعــة واحــدة كمــا حكمــت‬\n      ‫علــى املدعــى عليــه الثانــي لذلــك تعزيــرا بالســجن مــدة ثمانيــة أشــهر‬\n      ‫تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة يف‬\n      ‫‪1434/7/3‬ه ـ وجلــده ســبعني جلــدة دفعــة واحــدة هــذا مــا ثبــت لــدي‬\n      ‫وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي العــام معارضتــه‬\n      ‫وطلــب رفعــه حملكمــة االســتئناف دون الئحــة فأجبتــه لذلــك وقــرر‬\n      ‫املدعــى عليهمــا القناعــة بــه وقــد جــرى النطــق بــه يف متــام الســاعة الثانيــة‬\n      ‫عشــرة والربــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n      ‫وصحبــه أجمعــن حــرر يف ‪1434/8/15‬هــ‪ .‬احلمــد هلل وحــده وبعــد فقــد‬\n      ‫اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق القضايــا اجلزائيــة مبحكمــة‬\n      ‫االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بجــازان برقــم ‪ 341953035‬وتاريــخ ‪1434/8/20‬ه ـ‬\n      ‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬‬\n      ‫برقــم ‪ 34298921‬وتاريــخ ‪1434/8/16‬ه ـ اخلــاص بدعــوى املدعــي العام‬\n      ‫ضــد كل مــن ‪ ..... /‬و‪.....‬يف قضيــة (قــات) علــى الصفــة املوضحــة يف‬\n      ‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪.‬‬\n              ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪265‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":259,"source_page_end":265,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fb8e7a78f9cbabb729ebe58bb1ed340ada35769c90c85325c0862fab8b19507d","normalized_text_hash":"73f58aff949667eacf0d3d8881ec8a3d106908a4def47d46939204c538aa6cbd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p259-34298921"},{"id":"25588ae4-3b56-506d-85ed-d704add4d02a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج -قات -حتايل على رجال األمن -املدعى عليه أجنبي -إبراز رخصة قيادة مزورة -التعزير بالسجن","document_number":"34311440","case_number":"34407562","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/09/02","year":"1434","subject":"مخدرات -حيازة بقصد الترويج -قات -حتايل على رجال األمن -املدعى عليه أجنبي -إبراز رخصة قيادة مزورة -التعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34311440 :‬تاريخه‪1434/09/02 :‬هـ‬\n                     ‫رقم الدعوى‪34407562 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34328587‬تاريخه‪1434/10/12:‬هـ‬\n\n\n  ‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج ‪ -‬قــات ‪ -‬حتايــل علــى رجــال األمــن‬\n  ‫‪ -‬املدعــى عليــه أجنبــي ‪ -‬إبــراز رخصــة قيــادة مــزورة ‪ -‬التعزيــر بالســجن‬\n                                                                       ‫واجللــد‪.‬‬\n\n\n\n         ‫‪ -1‬املادة الرابعة من قرار مجلس الوزراء رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n                        ‫‪ -2‬قرار وزير الداخلية رقم (‪ )2057‬لعام ‪1404‬هـ ‪.‬‬\n                      ‫‪ -3‬قرار وزير الداخلية رقم (‪ )3818‬لعام ‪ 1410‬هـ ‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد الترويــج‬\n  ‫والتحايــل علــى رجــال األمــن بــاإلدالء مبعلومــات غيــر صحيحــة وطلــب‬\n  ‫إثبــات مــا أســند إليــه وتعزيــره ‪،‬وتعزيــره لقــاء التحايــل وإبعــاده عــن‬\n  ‫البــاد ‪،‬حيــث مت االشــتباه يف الســيارة التــي يقودهــا املدعــى عليــه ومت‬\n  ‫اســتيقافه وطلــب إثباتــه فقــام بإبــراز رخصــة قيــادة مــزورة وبتفتيــش‬\n  ‫الســيارة عثــر علــى نبــات يشــتبه أن يكــون نبــات القــات مبخبــأ ســري‬\n  ‫داخــل خــزان الوقــود ‪،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n  ‫العينــة املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى عليــه علــى‬\n  ‫حيــازة القــات وأنهــا لالســتعمال الشــخصي وأنكــر الترويــج وأقــر‬\n\n                                                                                    ‫‪266‬‬\n\f      ‫بتضليلــه والكــذب علــى رجــال األمــن ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بتعزيــره بســجنه ســنة وصــرف النظــر عــن طلــب املدعــي العــام‬\n      ‫لعــدم وجــود مــا يؤيــد الترويــج وتعزيــر املدعــى عليــه لكبــر الكميــة‬\n      ‫وشــبهة الترويــج وحتايلــه علــى رجــال األمــن بجلــده مائــة وخمســن جلــدة‬\n      ‫مفرقــة علــى ثــاث دفعــات وقنــع بــه املدعــى عليــه واعترض املدعــي العام‬\n                     ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬   ‫بــدون الئحــة ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34407562‬وتاريــخ ‪ 1434/09/01‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 342098319‬وتاريــخ ‪ 1434/09/01‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/09/02‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪00‬‬\n      ‫‪ 10 :‬وفيهــا حضــر املدعــي العــام ‪..... /‬املوجــه باخلطــاب رقــم (‪ ).....‬يف‬\n      ‫‪1434/8/29‬ه ـ وأدعــى علــى احلاضــر معــه الســجني‪..... /‬مينــي اجلنســية‬\n      ‫مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬حيــث إنــه بتاريــخ ‪1434/7/9‬ه ـ‬\n      ‫وأثنــاء قيــام الدوريــات األمنيــة بواجبهــا املعتــاد مبحافظــة الــدرب مت‬\n      ‫االشــتباه يف ســيارة نــوع اللــون ذهبــي موديــل ‪2003‬م اللوحــة(‪).....‬‬\n      ‫تعــود ملكيتهــا للمدعــو‪(...../‬مت حجزهــا حلــن مراجعــة مالكهــا)‬\n      ‫وبقيــادة املدعــى عليــه وباســتيقاف الســيارة وطلــب إثبــات قائدهــا قــام‬\n      ‫بإبــراز رخصــة قيــادة مــزورة باســم (‪ ).....‬وبســؤاله عنهــا ذكــر بأنــه‬\n      ‫اشــتراها مببلــغ (‪ 1000‬ريــال) مــن مكــة املكرمــة (مت فــرز أوراق‬\n      ‫مســتقلة بشــأن الرخصــة املــزورة) وبتفتيــش الســيارة عثــر علــى مخبــأ‬\n\n‫‪267‬‬\n\f‫ســري داخــل خــزان الوقــود وبداخلــه كميــة مــن نبــات أخضــر يشــتبه‬\n‫أن يكــون مــن نبــات القــات احملظــور بلــغ وزنهــا(‪ 19.500‬كجــم)‬\n‫تســعة عشــر كيلــو وخمســمائة جــرام أثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقــم (‪ ).....‬بتاريــخ ‪1434/7/17‬ه ـ الصــادر مــن مركــز‬\n‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بجــازان إيجابيــة‬\n‫العينــة املرســلة مــن الكميــة املضبوطــة لنبــات القــات احملظــور املــدرج‬\n‫باجلــدول رقــم(‪ )2‬فئــة(أ‪،‬ج) واجلــدول رقــم(‪ )4‬امللحقــن بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف‬\n‫‪1426/7/8‬ه ـ ومت إيقافــه اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n‫وباســتجواب املدعــى عليــه أقــر بحيازتــه للكميــة املضبوطــة وذكــر‬\n‫بأنــه قــام بشــرائها مــن شــخص مينــي ال يعرفــه مببلــغ (‪ 500‬ريــال) كمــا‬\n‫ذكــر بــأن قصــده منهــا االســتعمال الشــخصي وأفــاد بــأن الرخصــة‬\n‫املــزورة التــي قــام بإبرازهــا لرجــال األمــن وحتمــل اســم (‪ ).....‬أنــه اســم‬\n‫شــقيق مالــك الســيارة (‪.).....‬وقــد أســفر التحقيــق عــن اتهــام‪..... /‬بحيــازة‬\n‫مــا وزنــه (‪ 19,500‬كجــم) تســعة عشــر كيلــو وخمســمائة جــرام مــن‬\n‫نبــات القــات احملظــور بقصــد الترويــج واملجــرم مبوجــب الفقــرة رقــم‬\n‫(‪ )2‬مــن املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫والتحايــل علــى رجــال األمــن بــاإلدالء مبعلومــات غيــر صحيحــة‪ .‬وذلــك‬\n                                                    ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n                 ‫‪ -1‬ما جاء يف أقواله مبحضر االستجواب لفه رقم(‪.)16‬‬\n‫‪ -2‬مــا جــاء مبحضــر القبــض والتفتيــش املشــار لــه املرفــق بــاألوراق لفــه‬\n\n\n                                                                                      ‫‪268‬‬\n\f                                                                              ‫رقــم (‪. )2-1‬‬\n      ‫‪ -3‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفه (‪.)17‬‬\n      ‫ولــم يعثــر لــه علــى ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫فعــل محــرم شــرع ًا و معاقــب عليــه نظامـ ًا مبوجــب قــرار مجلــس الــوزراء‬\n                 ‫رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات ‪ ،‬لــذا أطلــب‪:‬‬\n                                               ‫إثبات إدانته مبا أسند إليه واحلكم‪:‬‬\n      ‫‪ -1‬بتعزيــره يف ضــوء املــادة (الثالثة)و(الرابعــة) مــن القــرار الــوزاري‬\n      ‫املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n                                                                         ‫‪1432/12/9‬هــ‪.‬‬\n                 ‫‪ -2‬إبعاده إلى بالده بعد انتهاء محكوميته استناد ًا لذات املادة‪.‬‬\n      ‫‪ -3‬عقوبــة تعزيريــة لقــاء حتايلــه علــى رجــال األمــن بــاإلدالء بأقــوال غيــر‬\n                                                                                  ‫صحيحة‪.‬‬\n      ‫وبعــرض مــا جــاء يف الئحــة الدعــوى علــى املدعــى عليــه صــدق على صحة‬\n      ‫مــا جــاء فيهــا وأن الكميــة املض ــبوطة بح ــوزته والب ــالغ وزن ــها (‪19,500‬‬\n      ‫كجــم) تســعة عشــر كيلــو وخمســمائة جــرام مــن ن ــبات ال ــقات تعــود‬\n      ‫لــه شــخصي ًا لغــرض االســتعمال الشــخصي و أنكــر قصــد الترويــج‬\n      ‫وأقــر بتضليلــه والكــذب علــى رجــال األمــن ليتمكــن مــن اإلفــات مــن‬\n      ‫العقوبــة هكــذا أجــاب وقــد جــرى ســؤال املدعــي العــام عــن بينتــه علــى‬\n      ‫أن الكميــة معــدة للترويــج قــال بينتــي كبــر حجــم الكميــة املضبوطــة‬\n      ‫وال يتصــور أن تكــون لالســتعمال الشــخصي وبعــرض ذلــك على املدعى‬\n      ‫عليــه قــال الصحيــح مــا ذكــرت وأنهــا لالســتعمال الشــخصي هكــذا‬\n      ‫أجــاب وباالطــاع علــى محضــر القبــض والتحقيــق وجــد مطابــق ملــا جــاء‬\n      ‫يف الئحــة الدعــوى وباالطــاع علــى التقريــر الكيميائــي الشــرعي لفــة‬\n\n\n‫‪269‬‬\n\f‫رقــم (‪ )17‬وجــد إيجابيــة العينــة املرســلة لنبــات القــات وباإلطــاع علــى‬\n‫ـاء علــى مــا تقــدم‬\n                   ‫صحيفــة الســوابق لــم يعثــر لــه علــى ســوابق مســجلة فبنـ ً‬\n‫مــن الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه بحيازتــه للكميــة‬\n‫املرصــودة أعــاه لغــرض االســتعمال الشــخصي وحيــث أنكــر قصــد‬\n‫الترويــج وال بينــة للمدعــي العــام ســوى كبــر حجــم الكميــه املضبوطــة‬\n‫وحيــث إن مــا أقــدم عليــه فعــل محــرم فقــد ثبــت لــدى إدانــة املدعــى عليــه‬\n‫بحيازتــه ملــا وزنــه (‪ 19,500‬كجــم) تســعة عشــر كيلــو وخمســمائة‬\n‫جــرام مــن نبــات القــات لغــرض االســتعمال الشــخصي وحكمــت‬\n‫عليــه تعزيــر ًا بالســجن ملــدة ســنة اعتبــارا مــن تاريــخ إيقافــه علــى ذمــة‬\n‫هــذه القضيــة اســتنادا للمــادة الرابعــة مــن القــرار الــوزاري رقــم(‪)11‬‬\n‫لعام‪1374‬ه ـ واملعــدل بقــراري وزيــر الداخليــة رقــم(‪ )2057‬لعام‪1404‬ه ـ‬\n‫ورقــم(‪ )3818‬لعام‪1410‬ه ـ وصرفــت النظــر عــن طلــب املدعــي العــام‬\n‫لعــدم وجــود مــا يؤيــد الترويــج ونظــر ًا لكبــر حجــم الكميــة ولوجــود‬\n‫شــبهة الترويــج و لتحايلــه علــى رجــال األمــن فهــو يســتحق التعزيــر علــى‬\n‫ذلــك بجلــده ألجــل ذلــك مائــة و خمســون جلــدة مفرقــة علــى ثــاث فتــرات‬\n‫بــن كل فتــرة واألخــرى ال يقــل عــن أســبوع ومبــا ســبق حكمــت وبهــذا‬\n‫انتهــت هــذه الدعــوى وبعــرض مــا حكمنــا بــه املدعــى عليــه قنــع بــه وقرر‬\n‫املدعــي العــام املعارضــة وطلــب رفعهــا إلــى محكمــة االســتئناف بــدون‬\n‫الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/02‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n\n\n                                                                                      ‫‪270‬‬\n\f      ‫‪ 342098319‬وتاريــخ ‪1434/9/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪.....‬برقــم ‪ 34311440‬وتاريــخ‬\n      ‫‪1434/9/2‬هـ اخلاص بدعوى املدعي العام ض ـ ـ ـ ـ ــد‪ ..... /‬ـ ميني اجلنســية‬\n      ‫ـ يف قضيــة ( قــات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n                                              ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪271‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":266,"source_page_end":271,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ff4c134b728688323d4df61d9e69261df165989278af9390cf5f28230f5c2aaa","normalized_text_hash":"5cced0fcf78ceac8a621885c6c1bdb306440e61e6fe5a28c1f0b5f5eef0fcefe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p266-34311440"},{"id":"73bfc4f4-189c-5e5b-a536-abf27f3f6396","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -عدم ثبوت اإلدانة بالترويج والتعاطي -خيانة األمانة ونكث القسم -املدعى عليهما عسكريان -تداخل العقوبات التعزيرية -التعزير بالسجن -1ما قرره أهل العلم يف تداخل العقوبات التعزيرية حيث جاء يف كشاف القناع ج 485/ 20للبهوتي ( ولو توجه عليه تعزيرات على معاص شتى فإن متحضت هلل تعالى واحتد نوعها كأن قبل أجنبية مرارا أو اختلف نوعها بأن قبل أجنبية وملس أخرى قصدا","document_number":"34350704","case_number":"34429116","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/5","year":"1434","subject":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -عدم ثبوت اإلدانة بالترويج والتعاطي -خيانة األمانة ونكث القسم -املدعى عليهما عسكريان -تداخل العقوبات التعزيرية -التعزير بالسجن -1ما قرره أهل العلم يف تداخل العقوبات التعزيرية حيث جاء يف كشاف القناع ج 485/ 20للبهوتي ( ولو توجه عليه تعزيرات على معاص شتى فإن متحضت هلل تعالى واحتد نوعها كأن قبل أجنبية مرارا أو اختلف نوعها بأن قبل أجنبية وملس أخرى قصدا","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34350704 :‬تاريخه ‪1434/11/5:‬هـ‬\n                         ‫رقم القضية‪34429116:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 35110775‬تاريخه‪1434/01/09:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬عــدم ثبــوت‬\n      ‫اإلدانــة بالترويــج والتعاطــي ‪ -‬خيانــة األمانــة ونكــث القســم ‪ -‬املدعــى‬\n      ‫عليهمــا عســكريان ‪ -‬تداخــل العقوبــات التعزيريــة ‪ -‬التعزيــر بالســجن‬\n\n\n\n      ‫‪ -1‬مــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة حيــث جــاء‬\n      ‫يف كشــاف القنــاع ج ‪ 485/ 20‬للبهوتــي ( ولــو توجــه عليــه تعزيــرات‬\n      ‫علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل‬\n      ‫أجنبيــة مــرارا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــدا‬\n                                              ‫تداخلــت وكفــاه تعزيــر واحــد )‪.‬‬\n      ‫‪ -2‬املــادة الرابعــة مــن قــرار ســمو وزيــر الداخليــة رقــم (‪ )2057‬يف‬\n                                                                 ‫‪1404/5/26‬هــ‪.‬‬\n                            ‫‪ -3‬القرار الوزاري رقم (‪ )3818‬يف ‪1410/9/28‬هـ ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بحيــازة قــات بقصــد الترويــج‬\n      ‫والتعاطــي وخيانــة األمانــة ونكــث القســم ‪،‬حيــث مت القبــض عليهمــا‬\n      ‫وهمــا يســتخدمان الســيارة الرســمية التابعــة حلــرس احلــدود وبحيازتهمــا‬\n      ‫القــات وطلــب إثبــات مــا أســند إليهمــا ومعاقبتهمــا وبتشــديد العقوبــة‬\n\n‫‪279‬‬\n\f‫خليانــة األمانــة كونهمــا رجلــي أمن وأثبت التقرير الكيميائي الشــرعي‬\n‫إيجابيــة العينــة املضبوطــة لنبــات القات احملظور وصــادق املدعى عليهما‬\n‫علــى حيازتهمــا القــات وأنهــا بقصــد االســتعمال الشــخصي وأنكــرا‬\n‫الترويــج ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة علــى املدعــى عليهمــا‬\n‫بالســجن ســنتني نظــر ًا لتداخــل العقوبــات التعزيريــة واعتــرض املدعــي‬\n     ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n                                             ‫العــام واملدعــى عليهمــا ُ‬\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )342206477‬وتاريــخ ‪1434/9/17‬هـ‬\n‫واحملالة من فضيلة الرئيس برقم (‪ )34429116‬وتاريخ ‪1434/9/17‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪.....‬و‪.....‬املتهمــن يف قضيــة حيــازة‬\n‫كميــة مــن نبــات القــات وخيانــة األمانــة ونكــث القســم عليــه ففــي‬\n‫هــذا اليــوم الثالثــاء ‪1434/11/4‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة العاشــرة وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم‬\n‫(‪ ).....‬وتاريــخ ‪1434/8/29‬ه ـ وادعــى علــى األول ‪.....‬ســعودي اجلنســية‬\n‫يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي ‪.....‬والثانــي ‪.....‬ســعودي‬\n‫اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي ‪.....‬أنــه بتاريــخ‬\n‫‪1434/2/27‬ه ـ وأثنــاء قيــام رئيــس قســم االســتخبارات بواجبــه يف‬\n‫حــدود مســئولياته يف مركــز ‪.....‬شــوهدت إحــدى الســيارات الرســمية‬\n‫التابعــة حلــرس احلــدود وهــي تقــف بجــوار أحــد املنــازل املهجــورة ونــزل‬\n‫مــن الســيارة اجلنــدي املدعــى عليــه ‪.....‬وبيــده عتلتــان مــن نبــات القــات‬\n\n                                                                                      ‫‪280‬‬\n\f      ‫احملظــور وقــام بإدخالهــا لذلــك املنــزل بداخــل إحــدى غــرف املنــزل وعلــى‬\n      ‫الفــور مت التوجــه إليــه وقبــض عليــه وهــو خــارج مــن املنــزل وليــس بيــده‬\n      ‫شــيء وبالدخــول إلــى املنــزل وتفتيشــه عثــر بــه علــى كميــة نبــات القــات‬\n      ‫وكانــت الســيارة بقيــادة اجلنــدي املدعــى عليــه ‪.....‬وبتفتيــش الســيارة‬\n      ‫عثــر حتــت مرتبــة الراكــب علــى حبــة مــن نبــات القــات ومت القبــض‬\n      ‫عليــه وبلــغ وزن الكميــات املضبوطــة (‪7،600‬كجــم) ســبعة كيلــوات‬\n      ‫وســتمائة جــرام أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ ).....‬بتاريــخ‬\n      ‫‪1434/3/11‬ه ـ الصــادر مــن مركــز مراقبــة الســموم والكيميــاء‬\n      ‫الشــرعية بجــازان إيجابيــة العينــة املرســلة مــن الكميــة املضبوطــة‬\n      ‫لنبــات القــات احملظــور املــدرج باجلــدول رقــم (‪ )2‬فئــة (أ‪،‬ج) واجلــدول‬\n      ‫رقــم (‪ )4‬امللحقــن بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ وباســتجواب‬\n      ‫املدعــى عليــه األول أقــر بصحــة واقعــة الضبــط وأفــاد بأنــه قــام بإنــزال‬\n      ‫الكميــة لذلــك املنــزل حتــى يأتيــه التوجيــه مــن قبــل عمليــات املركــز‬\n      ‫وحتــى ال يشــاهد أحــد الكميــة بداخــل الســيارة ويتــم اتهامــه فيهــا‬\n      ‫كمــا أقــر بأنــه يريــد وضعهــا يف املنــزل حتــى يتعاطــى منهــا هــو ورفيقــه‬\n      ‫علــى فتــرات وأن الكميــة التــي عثــر عليهــا بداخــل الســيارة ســقطت‬\n      ‫مــن العتلتــن أثنــاء نزولــه مــن الســيارة وصــادق علــى أقوالــه وباســتجواب‬\n      ‫املدعــى عليــه الثانــي أقــر بصحــة واقعــة الضبــط وأفــاد بــأن رفيقــه قــام‬\n      ‫بإنــزال الكميــة لذلــك املنــزل حتــى يأتيــه التوجيــه مــن قبــل عمليــات‬\n      ‫املركــز وحتــى ال يشــاهد أحــد الكميــة بداخــل الســيارة ويتــم اتهامهمــا‬\n      ‫فيهــا كمــا أقــر بأنهمــا يريــدان وضعهــا يف املنــزل حتــى يتعاطــى منهــا‬\n      ‫هــو ورفيقــه علــى فتــرات وصــادق علــى أقوالــه وبالبحــث عــن ســوابقهما‬\n\n\n‫‪281‬‬\n\f‫لــم يعثــر لهمــا علــى ســوابق مســجلة وقــد أســفر التحقيــق معــه عــن توجيــه‬\n‫االتهــام إليهمــا بحيازتهمــا كميــة مــن القــات تزن (‪7،600‬كجم) ســبعة‬\n‫كيلــوات وســتمائة جــرام بقصــد الترويــج والتعاطــي واملجــرم مبوجــب‬\n‫واملجــرم مبوجــب الفقــرة رقــم (‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ ونكــث القســم وخيانــة األمانــة وألن مــا أقــدم‬\n‫عليــه املدعــى عليهمــا فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب‬\n‫قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات‬\n‫فقــد طلــب املدعــي العــام إثبــات إدانتهمــا مبــا أســند إليهمــا واحلكــم‬\n‫بتعزيرهمــا يف ضــوء املادتــن الثالثــة والرابعــة مــن القــرار الــوزاري‬\n‫املشــار إليــه أعــاه إنفــاذا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ وتشــديد العقوبــة عليهمــا لكونهمــا رجلــي أمــن ومنوط‬\n‫بهمــا حفــظ األمــن وتعزيرهمــا شــرعا لقــاء نكثهمــا القســم وخيانــة‬\n‫األمانــة وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه األول صــدق‬\n‫القبــض عليــه يف الزمــان واملــكان املشــار إليهمــا واشــتراكه يف حيــازة‬\n‫كميــة القــات املذكــورة وقــرر أن قصــده مــن حيازتــه لنبــات القــات هــو‬\n‫االســتعمال الشــخصي لبعضــه وتســليم املتبقــي إلــى جهــة عملــه لســبق‬\n‫تبليغــه عــن ضبطــه لــه وأنكــر قصــد الترويــج هكــذا أجــاب وبعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه الثانــي صــدق القبــض عليــه يف‬\n‫الزمــان واملــكان املشــار إليهمــا واشــتراكه يف حيــازة كميــة القــات‬\n‫املذكــورة وقــرر أن قصــده مــن حيازتــه لنبــات القــات هــو االســتعمال‬\n‫الشــخصي لبعضــه وتســليم املتبقــي إلــى جهــة عملــه لســبق تبليغــه عــن‬\n‫ضبطــه لــه وأنكــر قصــد الترويــج هكــذا أجــاب عنــد ذلــك جــرى‬\n\n\n                                                                                     ‫‪282‬‬\n\f      ‫ســؤال املدعــي العــام هــل لديــك بينــة علــى قصــد املدعــى عليهمــا للترويــج‬\n      ‫ا بينتــي مــا يف أوراق املعاملــة إضافــة إلــى كبــر حجــم‬      ‫فأجــاب قائ ـ ً‬\n      ‫الكميــة املضبوطــة وطريقــة تقســيمها ووجــود رقــم جــوال مينــي بجــوال‬\n      ‫املتهــم األول واســتخدام الســيارة الرســمية ولبســهما الرســمي هكــذا‬\n      ‫أجــاب وبالرجــوع إلــى أوراق املع ــاملة جــرى االطــاع علــى التقريــر‬\n      ‫الكيميائــي الشــرعي وثبــت ســوابق املدعــى عليهمــا فوجــدت مطابقــة‬\n      ‫ملــا يف الدعــوى كمــا جــرى االطــاع علــى بقيــة لفــات املعاملــة ولــم أجــد‬\n      ‫بهــا مــا يديــن املدعــى عليهمــا بقصــد الترويــج ســوى قرينــة كبــر حجــم‬\n      ‫الكميــة عنــد ذلــك جــرى ســؤال املدعــي العــام هــل لديــك مزيــد بينــة‬\n      ‫ا ال أعلــم لــي مزيــد بينــة هكــذا أجــاب عليــه فبنــاء علــى‬  ‫فأجــاب قائ ـ ً‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وملــا تضمنــه األمــر الســامي الكــرمي رقــم‬\n      ‫(‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ يف فقرتــه األولــى مــن املوافقــة علــى‬\n      ‫أن تطبــق احملاكــم علــى مرتكبــي جرائــم القــات العقوبــات املعمــول‬\n      ‫بهــا قبــل نفــاذ نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ولعجــز‬\n      ‫املدعــي العــام عــن إقامــة البينــة املثبتــة إلدانــة املدعــى عليهمــا بقصــد‬\n      ‫الترويــج فقــد قــررت مــا يلــي أوال لــم تثبــت لــدي إدانــة املدعــى عليهمــا‬\n      ‫بقصــد الترويــج يف حيازتهمــا لكميــة القــات املضبوطــة وصرفــت النظــر‬\n      ‫عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليهمــا ومجازاتهمــا يف‬\n      ‫ضــوء املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n      ‫ثانيــا ثبتــت لــدي إدانــة املدعــى عليهمــا باالشــتراك يف حيــازة كميــة‬\n      ‫القــات املذكــورة أعــاه بقصــد التعاطــي وهمــا يســتحقان العقوبــة‬\n      ‫علــى ذلــك وفــق املــادة (‪ )4‬مــن قــرار ســمو زيــر الداخليــة رقــم (‪)2057‬‬\n      ‫وتاريــخ ‪1404/5/26‬ه ـ املعدلــة بالقــرار الــوزاري رقــم (‪ )3818‬وتاريــخ‬\n\n\n‫‪283‬‬\n\f‫‪1410/9/28‬ه ـ ثالثــا ثبتــت لــدي إدانــة املدعــى عليهمــا بخيانــة األمانــة‬\n‫التــي حملهمــا إياهــا ولــي األمــر ونكثهمــا القســم املأخــوذ عليهمــا يف‬\n‫ذلــك وهمــا يســتحقان العقوبــة التعزيريــة لقــاءه وملــا قــرره أهــل العلــم‬\n‫يف تداخــل العقوبــات التعزيريــة قــال العالمــة البهوتــي (ولــو توجــه‬\n‫عليــه تعزيــرات علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد‬\n‫نوعهــا كأن قبــل أجنبيــة مــرار ًا أو اختلــف نوعهــا بــأن قبــل أجنبيــة‬\n‫وملــس أخــرى قصــد ًا تداخلــت وكفــاه تعزيــر واحــد) كشــاف القنــاع‬\n‫عــن مــن اإلقنــاع (ج‪20‬ص‪ )485‬لذلــك كلــه فقــد قــررت االكتفــاء‬\n‫مبجــازاة املدعــى عليهمــا لقــاء خيانتهمــا لألمانــة ونكثهمــا للقســم وقــد‬\n‫حكمــت علــى املدعــى عليــه األول لذلــك بالســجن مــدة ســنتني تبــدأ مــن‬\n‫تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة يف ‪1434/8/29‬ه ـ‬\n‫حتســب منهــا املــدد التــي أمضاهــا يف التوقيــف علــى ذمــة القضيــة قبــل‬\n‫ذلــك كمــا حكمــت علــى املدعــى عليــه الثانــي لذلــك بالســجن مــدة‬\n‫ســنتني تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة‬\n‫يف ‪1434/8/29‬ه ـ حتســب منهــا املــدد التــي أمضاهــا يف التوقيــف علــى‬\n‫ذمــة القضيــة قبــل ذلــك هــذا مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى‬\n‫أطــراف القضيــة قــرر املدعــي العــام معارضتــه وطلــب رفعــه حملكمــة‬\n‫االســتئناف دون الئحــة فأجبتــه لذلــك وقــررا املدعــى عليهمــا معارضتــه‬\n‫وطلبــا رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة فأجبتهمــا لذلــك‬\n‫وأفهمتهمــا مبراجعــة احملكمــة يــوم الثالثــاء ‪1434/11/11‬ه ـ الســتالم‬\n‫صــورة القــرار وتقــدمي االعتــراض عليــه يف املهلــة املقــررة نظامــا وقدرهــا‬\n‫ثالثــون يومــا اعتبــارا مــن اقــرب األجلــن تاريــخ اســتالمه لصــورة القــرار‬\n‫او املوعــد احملــدد ففهمــاه وقــد جــرى النطــق بــه يف متــام الســاعة العاشــرة‬\n\n\n                                                                                      ‫‪284‬‬\n\f      ‫والنصــف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                      ‫وصحبــه أجمعــن حــرر يف ‪1434/11/4‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n      ‫‪ 342206477‬وتاريــخ ‪1434/12/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬برقــم ‪ 34350704‬وتاريــخ‬\n      ‫‪1434/11/5‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪..... /‬و ‪.....‬‬\n      ‫يف قضيــة (قــات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪.‬‬\n            ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪285‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":279,"source_page_end":285,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"296bc2720d4aa9707e9fb4e00cdbb8ad28e793161b167326b3753ce181e0601a","normalized_text_hash":"cf5779ffdc5171ccf81ae43509085ada256bc404969c08425a8043feb259d7d5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p279-34350704"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"55663ac6-4ea3-5786-ad61-177e05c24c03","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة لقصد التعاطي -إقرار - التعزير باجللد والسجن واإلبعاد عن الباد لقاء تعاطي احلبوب","document_number":"34275893","case_number":"34321229","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/23","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة لقصد التعاطي -إقرار - التعزير باجللد والسجن واإلبعاد عن الباد لقاء تعاطي احلبوب","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34275893:‬تاريخه ‪1434/7/23:‬هـ‬\n                  ‫رقم القضية ‪34321229:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34294097‬تاريخه‪1434/08/10:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة لقصــد التعاطــي ‪ -‬إقــرار ‪-‬‬\n‫التعزيــر باجللــد والســجن واإلبعــاد عــن البــاد لقــاء تعاطــي احلبــوب‬\n                                                               ‫احملظــورة‪.‬‬\n\n\n\n\n         ‫‪ -1‬قوله تعالى( وال تقتلوا النفس التي حرم اهلل إال باحلق )‪.‬‬\n               ‫‪ -2‬قوله تعالى ( والتفسدوا يف األرض بعد إصالحها )‪.‬‬\n           ‫‪ -3‬املادة(‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n           ‫‪ -4‬املادة(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n          ‫‪ -5‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة حبــة واحــدة مــن حبــوب‬\n‫اإلمفيتامــن وربــع حبــة مــن حبــوب الترامــادول ‪ -‬و طلــب املدعــى العــام‬\n‫تعزيــر املدعــى عليــه لقــاء تعاطيــه للحبــوب احملظــورة ‪ -‬طلــب املدعــي‬\n‫العــام ســجن املدعــى عليــه وتســفيره إلــى بالده بناء على املــواد (‪)56/ 41‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -‬أقــر املدعــى عليــه‬\n‫مبــا جــاء يف دعــوى املدعــي العــام حيــث أنــه مت القبــض عليــه وبتفتيــش‬\n‫الســيارة وجــد حبــة واحــدة وربــع احلبــة يشــتبه أن تكــون محظــورة ‪ ،‬بناء‬\n\n                                                                                  ‫‪222‬‬\n\f      ‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه لقــاء اســتعماله‬\n      ‫احلبــوب احملظــورة واحلكــم بتعزيــر املدعــى عليــه بالســجن واإلبعــاد عــن‬\n      ‫اململكــة العربيــة الســعودية وال يســمح بالعــودة إليهــا إال فيمــا تســمح بــه‬\n      ‫تعليمــات احلــج والعمــرة‪ ،‬وقــرر املدعــى عليــه اعتراضــه علــى احلكــم‬\n      ‫بــدون الئحــة‪ ،‬وقنــع املدعــى عليــه مبــا صــدر بحقــه مــن حكــم و صــدق‬\n                                                   ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫ـدي‬\n        ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n      ‫ـاء علــى املعاملــة الــواردة إلينــا‬\n                                           ‫أنــا ‪ ....‬باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n      ‫مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة اإلحســاء برقــم وتاريــخ‬\n      ‫‪1434/7/9‬ه ـ واملقيــدة بهــذه احملكمــة برقــم وتاريــخ ‪1434/7/11‬ه ـ‬\n      ‫واحملالــة إلينــا مــن فضيلــة الرئيــس برقــم وتاريــخ ‪1434/7/11‬ه ـ‬\n      ‫فتحــت اجللســة األولــى يــوم األربعــاء ‪1434/7/19‬ه ـ الســاعة العاشــرة‬\n      ‫وفيهــا حضــر املدعــي العــام امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n      ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n       ‫ا‪:‬‬  ‫األحســاء ذي الرقــم والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لدائــرة التحقيــق واالدعــاء‬\n      ‫العــام مبحافظــة اإلحســاء أدعــي علــى ‪ ......‬اجلنــس ‪ ،‬ذكــر اجلنســية‪،‬‬\n      ‫مصــري‪ ،‬الديانــة‪ :‬مســلم‪ ،‬تاريــخ امليــاد‪1409/02/20 :‬هـ‪،‬العمــر‪:‬‬\n      ‫‪ ،25‬نــوع الهويــة‪ :‬رخصــة إقامــة رقــم الهويــة‪ ..........:‬تاريــخ اإلصــدار‪:‬‬\n      ‫‪1432/10/23‬هــ‪ ،‬جهــة اإلصــدار‪ :‬جــوازات جنــران املهنــة‪ :‬موظــف‬\n      ‫أهلــي احلالــة االجتماعيــة ‪ :‬أعــزب‪ ،‬مــكان اإلقامــة‪ ...........:‬الهاتــف‬\n\n‫‪223‬‬\n\f‫احملمول‪..............:‬جهــة اإليقــاف‪ :‬ســجن األحســاء‪ ،‬تاريــخ القبــض‪:‬‬\n‫‪1434/6/9‬ه ـ ‪ ،‬حالــة املتهــم ‪ :‬موقــوف‪ ،‬االتهــام ‪ :‬تعاطــي املؤثــرات‬\n‫العقليــة وحيــازة مؤثــرات عقليــة بقصــد التعاطــي أو االســتعمال‬\n‫الشــخصي أنــه باإلطــاع علــى تنفيــذ املهمــة رقــم (‪ )9150‬املعــد مــن قبــل‬\n‫رجــال ضبــط أمــن الطــرق بطريــق الريــاض الدمــام الســريع تبــن أنــه‬\n‫مت القبــض علــى املدعــى عليــه وبقيادتــه ســيارة مــن نــوع (‪ ).....‬وبتفتيــش‬\n‫الســيارة ضبــط بهــا (‪ )1‬حبــة واحــدة و ربــع حبــة وربــع حبــة أخــرى يشــتبه‬\n‫أنهــا محظــورة مت ضبطهــا جميعهــا يف علبــة (الفيــوزات) وقــد اثبــت‬\n‫التقريــر الكيمــاوي الشــرعي رقــم (‪ 2857‬ك ش) لعــام ‪1434‬هـ الصادر‬\n‫مــن املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية إيجابيــة احلبــة‬\n‫ملــادة اإلمفيتامــن املنبــه احملظــور املــدرج يف اجلــدول رقــم (‪ )2‬فئــة (ب)‬\n‫وربــع احلبــة وربــع احلبــة لعقــار الترامــادول املــدرج يف اجلــدول رقــم (‪)1‬‬\n‫فئــة (هــ) وبســماع أقوالــه أقــر بحيازتــه مــا ضبــط معــه بقصــد التعاطــي‬\n‫وتعاطيــه لنوعــه‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام لــ‪ /‬بحيــازة (‪)1‬‬\n‫حبــة مــن حبــوب اإلمفتيامــن املنبــه احملظــور وربــع حبــة وربــع حبــة مــن‬\n‫عقــار الترامــادول لقصــد التعاطــي وتعاطيــه اإلمفيتامــن املنبــه احملظــور‬\n                                 ‫والترامــادول‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n                          ‫‪ -1‬محضر تنفيذ املهمة املرفق على اللفة رقم (‪.)4‬‬\n‫‪ -2‬أقــوال املدعــى عليــه املدونــة علــى الصفحــات رقــم (‪ )3،2‬مــن دفتــر‬\n                               ‫االســتدالالت األوليــة املرفــق علــى اللفــة رقــم (‪.)8‬‬\n                          ‫‪ -3‬التقرير الكيماوي املرفق على اللفة رقم (‪)16‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا ‪ -‬فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا وفقـ ًا للفقــرة الثانيــة‬\n\n\n                                                                                           ‫‪224‬‬\n\f      ‫مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫الصــادر باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n                       ‫لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪:‬‬\n      ‫‪-1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة حيازتــه مــا ضبــط معــه بقصــد‬\n                                                            ‫التعاطــي وتعاطيــه لنوعــه‪.‬‬\n      ‫‪-2‬بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املــادة (‪ )56‬مــن النظــام وذلــك‬\n      ‫بإبعــاده عــن البــاد بعــد تنفيــذ محكوميتــه‪ .‬وبــاهلل التوفيــق‪ ،‬هكــذا‬\n      ‫ا َّدعــى؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى‬\n      ‫ا ‪ :‬صحيــح مــا نســبه لــي‬   ‫عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـ ً‬\n      ‫املدعــي العــام مــن واقعــة القبــض ومــن حيازتــي لعــدد حبــة واحــدة مــن‬\n      ‫حبــوب االمفيتامــن احملظــورة وربعــي حبــة مــن عقــار الترامــدول املنبــه‬\n      ‫احملظــور بقصــد التعاطــي ومــن اســتعمالي للحب ــوب احملظــورة وصحيح‬\n      ‫اعتــرايف هكــذا أجــاب‪ .‬ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة‬\n      ‫ومنهــا‪ :‬التقريــر الكيمــاوي الشــرعي الصــادر مــن قســم الكيميــاء‬\n      ‫الشــرعية باملركــز اإلقليمــي ملراقبــة الســموم التابــع للمديريــة العامــة‬\n      ‫للشــؤون الصحيــة باملنطقــة الشــرقية برقــم (‪ 2857‬ك ش) لعــام ‪1434‬ه ـ‬\n      ‫املتضمــن إيجابيــة عي ــنة مــا ضبــط ملــادة اإلمفيتامــن املنبــه احملظــور‬\n      ‫ولعقــار الترامــدول املنبــه احملظــور كمــا جــرى اإلطــاع علــى كــرت‬\n      ‫ســوابق املدعــى عليــه املتضمــن خلــوه مــن الســوابق كمــا جــرى اإلطــاع‬\n      ‫علــى مذكــرة إيقــاف املدعــى عليــه املتضمنــة أنــه أوقــف بتاريــخ‬\n                                                                       ‫‪1434/06/09‬ه ـ‬\n      ‫فبنــاء علــى مــا ورد مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى‬\n\n\n‫‪225‬‬\n\f‫عليــه والتأكــد مــن أهليتــه وملــا ورد يف محضــر القبــض واعتــراف‬\n‫املدعــي عليــه ومبــا أنــه صــادق علــى صحــة مــا نســب إليــه مــن حيــازة‬\n‫احلبــوب احملظــورة علــى صفــة مــا ورد يف الدعــوى ومبــا أن مــا صــدر منــه‬\n‫حــرام يف الشــريعة ملــا يف احلبــوب احملظــورة مــن اخلطــر و الضــرر علــى‬\n‫البــاد والعبــاد وعلــى مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس‬\n‫التــي حــرم اهلل إال باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا)‬\n‫ممــا يســتوجب معاقبــة املدعــى عليــه و تعزيــزه بالعقوبــة الــواردة يف املــادة‬\n‫الواحــدة واألربعــن مــن نظــام مكافحــة املخــدرات ويتوجــه أن يكــون‬\n‫أقــل عقوبــة ملــا ظهــر مــن حالــه مــن النــدم وألنــه ال ســوابق لــه ولصغــر‬\n‫ســنه ولقلــة الكميــة التــي وجــدت بحيازتــه كمــا يتوجــه تخفيــف تلــك‬\n‫العقوبــة أيضــا حســب مقتضــى املــادة الســتني مــن النظــام نفســه ملــا‬\n‫ظهــر مــن حالــه مــن النــدم ولصغــر ســنه ولظروفــه االجتماعيــة التــي‬\n‫اقتنعــت بهــا احملكمــة وألنــه ال ســوابق لــه كمــا يتوجــه اســتحقاقه‬\n‫للعقوبــة الــواردة يف املــادة السادســة واخلمســن الفقــرة الثانيــة منهــا ومبــا‬\n‫أن املدعــى عليــه أقـ َّـر باســتعمال احلبــوب احملظــورة واســتعمالها ال يأخــذ‬ ‫َّ‬\n‫حكــم املســكر لعــدم التوافــق بينهمــا يف منــاط احلكــم ممــا يتوجــه‬\n‫معــه تعزيــر املدعــى عليــه باجللــد دون حــد املســكر لــذا كلــه وألجــل‬\n‫ـدي إدانــة‬\n          ‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي‪ :‬أوالً‪ /‬ثبــت لـ َّ‬\n‫املدعــى عليــه باســتعمال احلبــوب احملظــورة ويجلــد تعزيــز ًا لقــاء ذلــك‬\n‫بجلــده خمــس وســبعني جلــد ًة دفعــة واحــدة علنـاً‪ .‬ثانيـاً‪ /‬ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بحيــازة احلبــوب احملظــورة املوصــوف يف الدعــوى وعــدده‬\n‫حبــة واحــدة مــن حبــوب االمفيتامــن احملظــورة وربعــي حبــة مــن عقــار‬\n‫الترامــدول املنبــه احملظــور بقصــد التعاطــي وأن يعــزر بســجنه شــهرين‬\n\n\n                                                                                       ‫‪226‬‬\n\f      ‫مــن تاريــخ توقيفــه علــى ذمــة القضيــة وذلــك مبوجــب املــادة الواحــدة‬\n      ‫واألربعــن مــن نظــام مكافحــة املخــدرات واملــادة الســتني‪ .‬ثالثــا‪ /‬وأن‬\n      ‫يبعــد عــن اململكــة بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه واســتيفاء مــا‬\n      ‫لــه ومــا عليــه مــن حقــوق وال يســمح لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح‬\n      ‫بــه تعليمــات احلــج والعمــرة حســب مقتضــى مــا ورد يف املــادة السادســة‬\n      ‫واخلمســن مــن النظــام نفســه الفقــرة الثانيــة ‪ .‬وبتــاوة احلكــم علــى‬\n      ‫الطرفــن وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم‬\n      ‫وطلــب املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة‬\n      ‫هــي الئحــة الدعــوى هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن‬\n      ‫ذلــك حرمــة اســتعمال احلبــوب احملظــورة وأثــره الســيئ علــى العقــل واملــال‬\n      ‫وأقفلــت اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف ‪1434/07/19‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم وتاريــخ ‪1434/08/07‬ه ـ الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف برقــم وتاريــخ‬\n      ‫‪1434/08/01‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ ....‬املســجل برقــم‪ ....‬وتاريــخ ‪1434/07/23‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد‪( ....‬مصــري اجلنســية) يف قضيــة مخــدرات‬\n      ‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه وســلم‪.‬‬\n                                                            ‫حــرر يف ‪1434/08/10‬هــ‪.‬‬\n\n\n‫‪227‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":222,"source_page_end":227,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b0dc362ba545a91495ac6b7af6c0bf764ae2dd4f28fb952870c081e3c33d0db6","normalized_text_hash":"729f546bec2e46bbeb817fd31bc31376f4366b55c19a2fb324ba7ce648d359ac","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p222-34275893"},{"id":"5aa68656-f73b-5fe2-bd64-75bfddcbc17b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد االجتار وتعاطيها -صدم الدورية الرسمية -بينة غير موصلة -إدانة باحليازة بقصد التعاطي -عقوبة بحدها األعلى -إقامة حد املسكر -تعزير بالسجن واجللد واملنع من السفر -رد دعوى لعدم كفاية األدلة.","document_number":"34278299","case_number":"34327580","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/24","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد االجتار وتعاطيها -صدم الدورية الرسمية -بينة غير موصلة -إدانة باحليازة بقصد التعاطي -عقوبة بحدها األعلى -إقامة حد املسكر -تعزير بالسجن واجللد واملنع من السفر -رد دعوى لعدم كفاية األدلة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34278299:‬تاريخه‪1434/07/24 :‬هـ‬\n                    ‫رقم الدعوى‪34327580:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34298169‬تاريخه‪1434/8/15:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصد االجتــار وتعاطيها‬\n ‫‪ -‬صــدم الدوريــة الرســمية ‪ -‬بينــة غيــر موصلــة ‪ -‬إدانــة باحليــازة بقصــد‬\n ‫التعاطــي ‪ -‬عقوبــة بحدهــا األعلــى ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر‬\n ‫بالســجن واجللــد واملنــع مــن الســفر ‪ -‬رد دعــوى لعــدم كفايــة األدلــة‪.‬‬\n\n\n\n\n     ‫املادتان (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة بقصــد االجتــار وصــدم‬\n ‫الدوريــة الرســمية‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n ‫وعقوبــة تعزيريــة لقــاء صدمــه للدوريــة األمنيــة‪ ،‬طلــب رجــال األمــن‬\n ‫منــه التوقــف فــاذ بالفــرار وهــو يقــود ســيارته بســرعة جنونيــة وأثنــاء‬\n ‫محاولتهــم اســتيقافه شــوهد وهــو يرمــي كيــس بــه عــدد مــن احلبــوب‬\n ‫احملظــورة‪ ،‬وبعــد القبــض عليــه مت تفتيــش منزلــه فعثــر بــه علــى قطعــة‬\n ‫يشــتبه كونهــا مــن احلشــيش املخــدر وحبــة يشــتبه أن تكــون مــن احلبــوب‬\n ‫احملظــورة‪ -‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n\n                                                                                  ‫‪228‬‬\n\f      ‫للحشــيش املخــدر واإلمفيتامــن‪ ،‬أقــر أمــام احملكمــة بحيــازة مــا ضبــط‬\n      ‫معــه بقصــد التعاطــي وتعاطيــه لنوعهمــا وأنكــر قصد االجتــار‪ ،‬املدعي‬\n      ‫العــام لــم يقــدم بينــة موصلــة وال مــا يكفــي مــن القرائــن إلدانــة املدعــى‬\n      ‫عليــه بقصــد االجتــار‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه بحيــازة‬\n      ‫احلشــيش املخــدر واحلبــوب احملظــورة بقصــد التعاطــي وتعاطيــه لهمــا‬\n      ‫وقــررت إقامــة حــد املســكر عليــه بجلــده ثمانــن جلــدة دفعــة واحــدة‬\n      ‫علنــا وســجنه ملــدة ســنتني ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‬\n      ‫كمــا قضــت بــرد دعــوى املدعــي العــام بطلــب إدانتــه بقصــد االجتــار‬\n      ‫لعــدم كفايــة األدلــة‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‬\n          ‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم ‪ 34327580‬وتاريــخ ‪1434/07/16‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341710405‬وتاريــخ ‪1434/07/16‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق ‪1434/07/22‬ه ـ افتتحــت اجللســة الســاعة ‪11 :30‬‬\n      ‫وفيهــا حضــر املدعــي العــام مبوجــب التكليــف الصــادر مــن هيئــة‬\n      ‫التحقيــق واالدعــاء العــام بنجــران رقــم ه ـ ن ‪ 11178/2/1‬بتاريــخ‬\n      ‫‪1430/12/29‬ه ـ وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ‪....‬‬\n      ‫ســعودي مبوجــب الســجل املدنــي رقــم‪ ....‬قائــا يف دعــواه عليــه حيث ورد‬\n      ‫مبحضــر البــاغ املعــد مــن قبــل الفرقــة القابضــة تؤكــد امتهــان املتهــم‬\n      ‫الترويــج ويتــردد عليــه أشــخاص مشــبوهني‪ .‬و ورد مبحضــر القبــض‬\n\n‫‪229‬‬\n\f‫املعــد مــن قبــل الفرقــة القابضــة أنــه بنــاء علــى إخباريــة احــد مصادرهــم‬\n‫الســرية تفيــد بــأن املتهــم ميتهــن الترويــج ‪ ،‬وأفــاد املصــدر بــان املتهــم‬\n‫يتواجــد حاليــا يف حــي ‪ ....‬بالقــرب مــن مستشــفى القلــب ويســتقل ســيارة‬\n‫مــن نــوع ‪ .......‬حتمــل اللوحــة رقــم (‪ )........‬وعنــد االقتراب منــه الذ بالفرار‬\n‫ومت توجيــه الدوريــة الرســمية لــه وطلبــوا منــه الوقــوف ولــم يســتجب ومت‬\n‫التضيــق عليــه وتوجيــه كامــل الفــرق للمذكــور والســيطرة عليــه وعنــد‬\n‫احتكاكــه باجليــب الرســمي قــام بصــدم جــدار احــد املنــازل نتــج عــن‬\n‫ذلــك تلفيــات باجلــدار بطــول ثالثــة أمتــار تقريبــا وتلفيــات بســيارة املتهــم‪،‬‬\n‫إال أنــه لــم يســتجب وأســتمر بالهــرب بســرعة جنونيــة وخوفا على ســامة‬\n‫ســالك الطريــق ولعــدم اســتجابته لنــداء الفرقــة مت إطــاق طلقتــن‬\n‫حتذيريــة يف الهــواء ولــم يســتجب أيضـ ًا عندهــا مت إطــاق طلقتــن علــى‬\n‫إطــار الســيارة ممــا أدى إلــى إعطابــه وارتــداد الطلقــات لزجــاج الســيارة‬\n‫اخللفــي و بــودي الســيارة مــن اخللــف ‪ ،‬و واصــل املتهــم الهــرب وشــوهد‬\n‫وهــو يقــوم برمــي كيــس أبيــض اللــون تبــن فيمــا بعــد أنــه يحتــوي علــى‬\n‫حبــوب بيضــاء اللــون بلــغ عددهــا (‪ )135‬حبــة وفتــات مــن نفــس النــوع بلــغ‬\n‫وزنهــا (‪8,3‬جــم) ‪ ،‬وبعــد مســافة تقــدر بســبعمائة متــر تقريبــا وقــع املتهــم‬\n‫يف منطقــة وحــل تغمرهــا امليــاه أجبرتــه علــى التوقــف‪ .‬ومت عمــل رســم‬\n‫تخطيطــي للحــادث متهيدنــا ملطالبتهــم للمتهــم بإصــاح التلفيــات التــي‬\n‫أحدثهــا‪ ،‬ومت إرســاله إلــى مستشــفى امللــك خالــد لتلقــي العــاج الــازم‪.‬‬\n‫كمــا أنــه بتاريــخ ‪1434/6/26‬ه ـ ورد محضــر تفتيــش منــزل املتهــم‬\n‫املتضمــن أنــه بنــاء علــى مــا توفــر مــن معلومــات مؤكــدة عــن وجــود‬\n‫كميــات مــن احلشــيش املخــدر لــدى املتهــم أعــاه فقــد مت أخــذ أذن‬\n‫بتفتيــش منزلــه ‪ ،‬وباالنتقــال للمنــزل وهــو عبــارة عــن حــوش بــه هنقــر‬\n\n\n                                                                                        ‫‪230‬‬\n\f      ‫مكــون مــن غرفــة نــوم ومجلــس ومطبــخ وبتفتيــش الغرفــة وجــدت قطعــة‬\n      ‫ســمراء اللــون بلــغ وزنهــا (‪182.6‬جــم) أثــان وثمانــون جرام ـ ًا وســته مــن‬\n      ‫العشــرة مــن اجلــرام حتــت الســرير ‪ ،‬كمــا عثــر علــى حبــة يشــتبه أن‬\n      ‫تكــون مــن احلبــوب احملظــورة فــوق دوالب املالبــس‪ .‬مت إيقافــه وإيداعــه‬\n      ‫شــعبة الســجن العــام بنجــران اســتنا ًدا للمــادة (‪)112‬من نظــام اإلجراءات‬\n      ‫اجلزائيــة‪ .‬وبســماع أقــوال املتهــم‪ ......./‬لــم يفــد التحقيــق معــه بشــيء‪.‬‬\n      ‫وباســتجواب املتهــم أقــر بــأن ســبب القبــض عليــه حيازتــه لعــدد (‪)180‬‬\n      ‫حبــه وأنهــا لالســتخدام الشــخصي وأنــه حصــل عليهــا من شــخص يدعى‬\n      ‫ورقــم جوالــه مخــزن بجــوال املتهــم وقــد أدلــى بــه للمكافحــة وقــد‬\n      ‫اشــترى منــه قرابــة (‪ )200‬حبــة مــن احلبــوب احملظــورة مقابــل (‪)4000‬‬\n      ‫ريــال ســعودي ولــم يعطــي أحــدا منهــا شــيئا وأنــه يعمــل يف الصبــاح لــدى‬\n      ‫شــركة و يعمــل ويكــد بســيارته مشــاوير طويلــة ‪ ،‬وأن ســبب هروبــه‬\n      ‫مــن الفرقــة القابضــة هــو عــدم معرفتــه بهــم يف بدايــة األمــر كــون‬\n      ‫الســيارة األولــى كانــت مدنيــة وبعــد ذلــك حضــرت الدوريــة الرســمية‬\n      ‫وقامــت بصدمــه جهــة اجلــدار وتوقــف يف مــكان بــه مــاء ‪ ،‬وأن الســيارة‬\n      ‫عائــدة ألخيــه ‪ ،‬وأنــه لديــه ســابقة مخــدرات يف حفــر الباطــن وحكــم‬\n      ‫بثالثــة أشــهر وســابقة يف القصيــم وحكــم بأربــع ســنوات ‪ ،‬ومبــا جهتــه‬\n      ‫مبحضــر تفتيــش منزلــه أقــر بحيازتــه حلبــة مــن احلبــوب احملظــورة ‪،‬‬\n      ‫وحيــازة لقطعــة حشــيش بلــغ وزنهــا (‪182.6‬جــم) أثــان وثمانــون جرام ـ ًا‬\n      ‫وســته مــن العشــرة مــن اجلــرام بقصــد التعاطــي ‪ ،‬وتعاطيــه لــه بالســابق‬\n      ‫وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )11555‬الصــادر مــن‬\n      ‫مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة‬\n      ‫املكرمــة أن العينــة املرســلة باحلــرز الســري رقــم (‪334‬س) حتتــوي علــى‬\n\n\n‫‪231‬‬\n\f‫مــادة اإلمفيتامــن املؤثــر عقلي ـاً‪ ،‬واإلمفيتامــن مــن املــواد املدرجــة‬\n‫بجــداول املخــدرات واملؤثــرات العقليــة رقــم (‪ 2‬فئــة ب) امللحقــة بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ .‬وأثبــت التقريــر الكيميائــي الشــرعي‬\n‫رقــم (‪/11560‬س‪1434/2‬ه ـ ) الصــادر مــن مركــز مراقبــة الســموم‬\n‫والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة املكرمــة أن العينــة‬\n‫املرســلة للتحليــل باحلــرز الســري رقــم (‪ )339‬ثبــت أنهــا حشــيش مخــدر‬\n‫وحتتــوي علــى املــادة الفعالــة للحشــيش املخــدر‪ ،‬وتعاطيــه لــه بالســابق ‪،‬‬\n‫واحلشــيش املخــدر مــن املــواد املدرجــة بجــداول املخــدرات واملؤثــرات‬\n‫العقليــة رقــم (‪ 1‬فئــة أ) امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n‫وقــد انتهــى التحقيــق بتوجيــه االتهــام لــ‪ ،....‬بحيــازة (‪ )136‬مائــة وســت‬\n‫وثالثــون حبــة و وفتــات مكســور مــن نفــس احلبــوب بلــغ وزنــه (‪81,3‬جــم)‬\n‫مــن احلبــوب احملتويــة علــى مــادة اإلمفيتامــن املؤثــرة عقليــا بقصــد‬\n‫االجتــار ‪ ،‬وحيــازة (‪182.6‬جــرام) مــن احلشــيش املخــدر بقصــد االجتــار‬\n‫ا مجرم ـ ًا اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن‬\n                                                                      ‫‪ ،‬ممــا يعــد فع ـ ً‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وعــدم االمتثــال لرجــال األمــن‬\n‫وصــدم دوريتهــم‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جــاء يف إقــراره‬\n‫حتقيقــا املــدون مبحضــر االســتجواب املرفــق لفــة رقــم ( ‪ )15‬ص (‪)3-1‬‬\n‫‪ ،‬وعلــى ص(‪ )2-1‬مــن دفتــر االســتجواب املرفــق لفــة (‪ -2 .)16‬مــا جــاء‬\n‫يف محاضــر البــاغ والقبــض والتفتيــش املنــوه عنــه املــدون علــى دفتــر‬\n‫االســتدالل املرفــق لفــه رقــم (‪ )1‬علــى ص (‪ ، )2.11.12‬وعلــى ص(‪)11‬‬\n\n\n                                                                                             ‫‪232‬‬\n\f      ‫مــن دفتــر االســتدالل املرفــق لفــة(‪ -3 .)19‬مــا تضمنــاه التقريريــن‬\n      ‫الكيميائيــن الشــرعيني املنــوه عنهمــا املرفقــن لفــة رقــم ( ‪.) 18 ،17‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املتهــم ‪ /‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n      ‫فعــل مجــرم ومعاقــب عليــه نظام ـ ًا مبوجــب نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة يف عقوباتــه األصليــة والتكميليــة لــذا أطلــب إثبــات‬\n      ‫إدانتــه مبــا أســند إليــه ‪ ،‬واحلكــم عليــه مبــا يلــي‪ .1 :‬العقوبــة الــواردة يف‬\n      ‫الفقــرة األولــى مــن املــادة (‪ )38‬الثامنــة والثالثــن مــن نظــام مكافحــة‬\n      ‫املخــدرات املنــوه عنــه‪ .2 .‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ‬\n      ‫محكوميته اســتناد ًا للفقرة األولى من املادة (‪ )56‬السادســة واخلمســن‬\n      ‫مــن نظــام مكافحــة املخــدرات املنــوه عنــه‪ .3 .‬معاقبتــه بعقوبــة تعزيريــة‬\n      ‫رادعــة لــه وزاجــرة لغيــره لعــدم امتثالــه لرجــال األمــن وصــدم دوريتهــم‪.‬‬\n      ‫(علمــا بــان احلــق اخلــاص مــازال قائمــا) هــذه دعــواي وبعــرض الدعــوى‬\n      ‫علــى املدعــى عليــه وســؤاله اجلــواب أجــاب بقولــه مــا ذكــره املدعــي‬\n      ‫العــام يف دعــواه مــن أننــي حــزت (‪ )136‬مائــة وســت وثالثــون حبــة وفتــات‬\n      ‫مكســور مــن نفــس احلبــوب بلــغ وزنــه (‪81,3‬جــم) مــن احلبــوب احملتويــة‬\n      ‫علــى مــادة اإلمفيتامــن املؤثــرة عقليــا‪ ،‬وأننــي حــزت قطعــة مــن احلشــيش‬\n      ‫املخــدر تــزن (‪182.6‬جــرام) فهــذا صحيــح وأنــا أتعاطــى احلشــيش املخــدر‬\n      ‫واحلبــوب احملظــورة‪ ،‬وأمــا مــا ذكــره مــن أن قصــدي مــن حيازتهــا‬\n      ‫االجتــار فهــذا غيــر صحيــح والصحيــح أن قصــدي مــن حيازتهــا‬\n      ‫االســتعمال الشــخصي‪ ،‬وغيــر صحيــح أننــي لــم أمتثــل لرجــال األمــن‬\n      ‫وصدمــت دوريتهــم فأنــا لــم أكــن أعلــم بأنهــم مــن رجــال املكافحــة ولــم‬\n      ‫أصطــدم بدوريتهــم الرســمية بــل هــم الذيــن اصطدمــوا بــي وقــد تبــت‬\n      ‫إلــى اهلل تعالــى وندمــت علــى مــا فعلــت وعلــي ســابقتي مخــدرات هــذه‬\n\n\n‫‪233‬‬\n\f‫إجابتــي وقــال املدعــي العــام الصحيــح مــا ذكرتــه وال صحــة ملــا أنكــره‬\n‫املدعــى عليــه ممــا جــاء يف الئحــة الدعــوى وبينتــي علــى ذلــك مــا جــاء يف‬\n‫الئحــة الدعــوى وأوراق املعاملــة‪ .‬أ‪.‬ه ـ وبالرجــوع إليهــا وجــدت مطابقــة ملــا‬\n‫جــاء يف جــواب املدعــى عليــه وبســؤال املدعــي العــام هــل لديــه زيــادة بينــة‬\n‫علــى أن املدعــى عليــه قصــد مــن حيازته االجتار فقــال إن كبر الكمية‬\n‫دليــل علــى قصــد االجتــار كمــا أن الفرقــة القابضــة وردتهــم إخباريــة‬\n‫مــن أحــد مصادرهــم الســرية تفيــد بــأن املتهــم ميتهــن الترويــج وبســؤال‬\n‫املدعــي العــام هــل لديــه زيــادة بينة على أن املدعــى عليه تعمد االصطدام‬\n‫بالدوريــة الرســمية وإحــداث تلفيــات بهــا ليعاقــب علــى ذلــك القصــد‬\n‫اجلنائــي قــال ليــس لــدي ســوى مــا جــاء يف الئحــة الدعــوى وأوراق املعاملة‪.‬‬\n‫أ‪.‬ه ـ وبعــد ســماع الدعــوى واإلجابــة جــرى االطالع على صــورة التقريرين‬\n‫الكيميائيــة الشــرعية املشــار إليــه يف الدعــوى فوجــدا يتضمننــا إيجابية‬\n‫مــا ضبــط بحــوزة املدعــى عليــه للحشــيش املخــدر ولإلمفيتامــن‪ .‬أ‪.‬هــ‪.‬‬\n‫فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وبعــد دراســة القضيــة‬\n‫واالطــاع علــى أوراق املعاملــة ومبــا أن املدعــى عليــه أقــر مبــا جــاء يف‬\n‫دعــوى املدعــي العــام مــن حيازتــه ملائــة وســت وثالثــن حبــة وفتــات‬\n‫مكســور مــن نفــس احلبــوب بلــغ وزنــه (‪81,3‬جــم) مــن احلبــوب احملتويــة‬\n‫علــى مــادة اإلمفيتامــن املؤثــرة عقليــا‪ ،‬وحيازتــه لقطعــة مــن احلشــيش‬\n‫املخــدر تــزن (‪182.6‬جــرام) وتعاطيــه للحشــيش املخــدر واحلبــوب‬\n‫احملظــورة يف الســابق‪ ،‬وألنــه أقــر بــأن قصــده مــن حيازتهــا االســتعمال‬\n‫الشــخصي وأنكــر أن يكــون قصــده االجتــار‪ ،‬كمــا أنــه أقــر‬\n‫باالصطــدام بالدوريــة الرســمية ودفــع بأنــه لــم يتعمــد ذلــك وأن قائــد‬\n‫الدوريــة انحــرف عليــه‪ ،‬وألن املدعــي العــام لــم يقــم بينــة موصلــة وال مــا‬\n\n\n                                                                                       ‫‪234‬‬\n\f      ‫يكفــي مــن القرائــن إلثبــات إدانــة املدعــى عليــه بحيــازة مــا ضبــط معــه‬\n      ‫بقصــد االجتــار إذ أن الكميــة املضبوطــة معــه ليســت كبيــرة بالقــدر‬\n      ‫الــذي يجــزم معــه بحيازتــه لهــا بقصــد االجتــار ومــا ذكــره املدعــي العــام‬\n      ‫مــن وجــود إخباريــة بحــق املدعــى عليــه ال يعــول عليهــا يف إثبــات اإلدانــة‬\n      ‫مبــا ذكــر‪ ،‬كمــا أن املدعــي العــام لــم يقــم بينــة موصلــة وال مــا يكفــي‬\n      ‫مــن القرائــن إلثبــات إدانــة املدعــى عليــه بتعمــد القصــد اجلنائــي بهــذا‬\n      ‫االصطــدام‪ ،‬وألن املدعــى عليــه لــه عــدة ســوابق مــن نفــس جنــس هــذه‬\n      ‫اجلرميــة لــم تردعــه عقوباتهــا‪ ،‬واســتناد ًا إلــى املــواد (‪ )56-41‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬ولــكل هــذه األســباب فقــد‬\n      ‫قــررت اآلتــي‪ :‬أوالً‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي احلشــيش‬\n      ‫املخــدر واحلبــوب احملظــورة وقــررت تعزيــره لقــاء ذلــك بإقامــة حــد‬\n      ‫املســكر عليــه بجلــده ثمانــن جلــدة دفعــة واحــدة علنــا‪ .‬ثانيـاً‪ :‬حكمــت‬\n      ‫بــرد دعــوى املدعــي العــام بطلــب إثبــات إدانــة املدعــى عليــه بحيــازة‬\n      ‫احلبــوب املنبهــة احملظــورة واحلشــيش املخــدر بقصــد االجتــار وطلبــه‬\n      ‫تطبيــق العقوبــة الــواردة يف املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة بحقــه لعــدم كفايــة األدلــة‪ .‬ثالث ـاً‪ :‬ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بحيــازة (‪ )136‬مائــة وســت وثالثــون حبــة وفتــات مكســور‬\n      ‫مــن نفــس احلبــوب بلــغ وزنــه (‪81,3‬جــم) مــن احلبــوب احملتويــة علــى مــادة‬\n      ‫اإلمفيتامــن املؤثــرة عقليــا‪ ،‬وقطعــة مــن احلشــيش املخــدر تــزن‬\n      ‫(‪182.6‬جــرام) بقصــد االســتخدام الشــخصي وقــررت تعزيــره لقــاء ذلــك‬\n      ‫بســجنه ملــدة ســنتني اعتبــار ًا مــن تاريــخ توقيفــه‪ .‬رابعــا‪ :‬مينــع املدعــى عليــه‬\n      ‫مــن الســفر خــارج البــاد ملــدة ســنتني تبــدأ بعــد انتهــاء مــدة تنفيــذ عقوبــة‬\n      ‫الســجن‪ .‬خامس ـاً‪ :‬حكمــت بــرد دعــوى املدعــي العــام بطلــب تعزيــر‬\n\n\n‫‪235‬‬\n\f‫املدعــى عليــه لقــاء صدمــه للدوريــة الرســمية التابعــة للفرقــة القابضــة‬\n‫لعــدم ثبــوت موجبــه‪ .‬وبذلــك كلــه حكمــت وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر قناعتــه باحلكــم كمــا قــرر املدعــي العــام اعتراضــه‬\n‫علــى احلكــم بــدون الئحــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                      ‫محمد وآله وصحبه أجمعني‪ .‬حرر يف ‪1434/7/22‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n‫‪ 341710405‬وتاريــخ ‪1434/7/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ................./‬برقــم ‪34278299‬‬\n‫وتاريــخ ‪1434/7/24‬ه ـ اخلــاص بدعوى املدعــي العام ضد ‪.................../‬‬\n‫يف قضيــة (مخــدرات ‪ ،‬والهــروب مــن رجــال األمــن وصــدم ســيارة‬\n‫رســمية) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪236‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":228,"source_page_end":236,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d7a5ef2aa466c577c5ff2e61d8bace2c8c1060e7d4274b1218d84765671f022","normalized_text_hash":"1d362b4b1308712de1e54f6d6ecf566c464199e0a9b06cb4fad77c7352d8d8d6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p228-34278299"},{"id":"9bf36e3e-9bcf-5146-96d0-0d0928d74a7f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي والترويج وتعاطيه -إثبات بالقرائن -إدانة باحليازة املجردة -تعزير للتهمة القوية -سجن وجلد وإبعاد عن الباد -براءة أحد املتهمن لعدم","document_number":"34293242","case_number":"34367823","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/09","year":"1434","subject":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي والترويج وتعاطيه -إثبات بالقرائن -إدانة باحليازة املجردة -تعزير للتهمة القوية -سجن وجلد وإبعاد عن الباد -براءة أحد املتهمن لعدم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34293242:‬تاريخه‪1434/08/09 :‬هـ‬\n                          ‫رقم الدعوى‪34367823:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34374737‬تاريخه‪1434/12/01:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬اشــتراك يف حيــازة حشــيش بقصــد التعاطــي والترويــج‬\n       ‫وتعاطيــه‪ -‬إثبــات بالقرائــن‪ -‬إدانــة باحليــازة املجــردة‪ -‬تعزيــر للتهمــة‬\n       ‫القويــة ‪ -‬ســجن وجلــد وإبعــاد عــن البــاد ‪ -‬بــراءة أحــد املتهمــن لعــدم‬\n                                                                      ‫ثبــوت التهمــة‪.‬‬\n\n\n\n\n                    ‫‪ -1‬قول اهلل تعالى‪ ( :‬وتعاونوا على البر والتقوى‪ ..‬اآلية )‪.‬‬\n        ‫‪ -2‬قول اهلل تعالى‪ ( :‬يا أيها الذين آمنوا إمنا اخلمر وامليسر‪ ..‬اآلية)‪.‬‬\n       ‫‪ -3‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                          ‫حــرام )‪.‬رواه مســلم‪.‬‬\n           ‫‪ -4‬املواد (‪ )39‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهــم تتضمــن طلــب إثبــات إدانتهــم‬\n       ‫بحيــازة احلشــيش املخــدر بقصــد الترويــج والتعاطــي‪ ،‬واحلكــم عليهــم‬\n       ‫بعقوبــة الســجن واجللــد والغرامــة واملصــادرة واإلبعــاد عــن البــاد طبقــا‬\n       ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -‬مت متابعــة الســيارة‬\n       ‫التــي يســتقلونها وبعــد توقفهــا وترجلهــم منهــا مت القبــض عليهــم يف أحــد‬\n       ‫احملــات املجــاورة وبتفتيــش املركبــة عثــر فيهــا علــى احلشــيش املخــدر‪-‬‬\n\n‫‪243‬‬\n\f‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش‬\n‫املخــدر‪ -‬أنكــر املدعــى عليهــم أمــام احملكمــة مــا أســنده إليهــم املدعــي‬\n‫العــام وأقــر الثالــث بتعاطــي احلشــيش‪ -‬قضــت احملكمــة بإدانــة املدعــى‬\n‫عليــه الثالــث بتعاطــي احلشــيش املخــدر وقــررت إقامة حد املســكر عليه‬\n‫بجلــده ثمانــن جلــدة دفعــة واحــدة علنــا‪ ،‬وقضــت بإدانــة األول والثالــث‬\n‫بحيــازة احلشــيش املخــدر حيــازة مجــردة مــع توجــه الشــبهة بــأن يكــون‬\n‫قصدهمــا مــن حيازتهــا الترويــج والتعاطــي وقــررت ســجن كل واحــد‬\n‫منهمــا ثــاث ســنوات وجلــده خمســن جلــدة تكــرر عليــه ثمــان مــرات‬\n‫وتغرميــه مبلــغ خمســة آالف ريــال وإبعادهمــا عــن البــاد‪ ،‬كمــا قضــت‬\n‫بــرد مطالبــة املدعــي العــام تطبيــق العقوبــات الــواردة يف املــادة (‪)53-38‬‬\n‫بحقهمــا وقضــت بــرد الدعــوى جتــاه الثانــي وأخلــت ســبيله منهــا‪ -‬قنــع‬\n‫املدعــى عليهــم باحلكــم وعــارض املدعــي العــام عليــه‪ -‬قــررت محكمــة‬\n                              ‫االســتئناف باألكثريــة املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34367823‬وتاريــخ‬\n‫‪ 1434/08/07‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341895628‬وتاريــخ‬\n‫‪ 1434/08/06‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/08/09‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 :30‬لســماع دعــوى املدعــي العــام ضــد ويف هــذه‬\n‫اجللســة حضــر املدعــي العــام ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم واملكلــف مــن قبــل هيئــة التحقيــق واالدعــاء العــام مبباشــرة‬\n\n                                                                                   ‫‪244‬‬\n\f      ‫الدعــاوى بهــذه احملكمــة مبوجــب كتابهم رقم هــ‪ 15832/6/2‬وتاريخ‬\n      ‫‪1433/03/06‬ه ـ نيابــة عــن املدعــى العــام بفرع هيئــة التحقيق مبحافظة‬\n      ‫وادعــى علــى‪)38( ،‬عام ـاً‪ ،‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫() غيــر متعلــم ‪ ،‬يقيــم بطريقــة غيــر نظاميــة ‪ ،‬املقبــوض عليــه بتاريــخ‬\n      ‫‪1434/6/6‬ه ـ واملوقــوف بالســجن العــام مبحافظــة جــدة بأمــر متديــد‬\n      ‫التوقيــف رقــم (ه ـ م‪ )40774/5/2‬بتاريــخ ‪1434/6/17‬ه ـ اســتناد ًا‬\n      ‫للقــرار الــوزاري رقــم (‪ )1900‬الصــادر بتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى‬\n      ‫املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪)28( ،‬عامـ ًا ‪ ،‬مينــي اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم () متعلــم ‪ ،‬مهنتــه عامــل بالقطــاع اخلــاص‪،‬‬\n      ‫املقبوض عليه بتاريخ ‪1434/6/6‬هـ واملوقوف بالســجن العام مبحافظة‬\n      ‫جــدة بأمــر متديــد التوقيــف رقــم (ه ـ م‪ )40743/5/2‬بتاريــخ‬\n      ‫‪1434/6/17‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬الصــادر بتاريــخ‬\n      ‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫و‪)23( .....‬عام ًا ‪ ...‬ميني اجلنسية مبوجب البطاقة البديلة رقم (‪)34/795‬‬\n      ‫الصــادرة مــن مكافحــة املخــدرات مبحافظة جــدة بتاريخ ‪1434/6/7‬هـ‬\n      ‫متعلــم ‪ ،‬يقيــم بطريقــة غيــر نظاميــة‪ ،‬املقبــوض عليــه بتاريــخ‬\n      ‫‪1434/6/6‬ه ـ واملوقــوف بالســجن العــام مبحافظــة جــدة بأمــر متديــد‬\n      ‫التوقيــف رقــم (ه ـ م‪ )40742/5/2‬بتاريــخ ‪1434/6/17‬ه ـ اســتناد ًا‬\n      ‫للقــرار الــوزاري رقــم (‪ )1900‬الصــادر بتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى‬\n      ‫املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة قائــا يف الئحتــه إنــه بتاريــخ‬\n      ‫‪1434/6/6‬ه ـ وبنــاء علــى معلومــات ســابقه لــدى مكافحــة املخــدرات‬\n      ‫مت رصــد املدعــى عليهــم يســتقلون مركبــه مــن نــوع (‪ )....‬حتمــل اللوحــة‬\n      ‫رقــم (‪ )....‬بقيــادة املدعــى عليــه األول ويرافقــه يف املقعــد األمامــي املدعى‬\n\n\n‫‪245‬‬\n\f‫عليــه الثانــي ويف املقعــد اخللفــي املدعــى عليــه الثالــث ومبتابعهــم إلــى‬\n‫حــي الكنــدرة توقفــت املركبــة وترجلــوا املدعــى عليهــم الثالثــة و‬\n‫توجهــوا إلــى أحــد محــات االتصــاالت املجــاورة وبالقبــض عليهــم‬\n‫وتفتيشــهم شــخصي ًا ضبــط بحــوزة األول علــى مبلــغ مالــي قــدره (‪)29‬‬\n‫ريــاالً‪ ،‬ومبلــغ (‪ )1288‬ريــا ًال بحــوزة الثانــي ‪ ،‬ومبلــغ (‪ )480‬ريــاال بحــوزة‬\n‫الثالــث‪ ،‬وبســؤالهم عــن املركبــة أنكــروا عالقتهــم بهــا وبتفتيشــها‬\n‫ضبــط عنــد موضــع أقــدام الراكــب الثالــث (كيــس نايلــون) كبيــر‬\n‫احلجــم لونــه أخضــر بداخلــه عــدد (‪ )7‬ســبع قطــع ســوداء اللــون بلــغ‬\n‫مجمــوع أوزانهــا (‪)7073‬جــم‪ ،‬ســبعة آالف وثالثــة وســبعني جرامـاً‪ ،‬مــن‬\n‫مــادة احلشــيش املخــدر‪ .‬و أثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪/2130‬ك ش م) لعــام ‪1434‬ه ـ الصــادر مــن مركــز مراقبــة الســموم‬\n‫والكيميــاء الطبيــة الشــرعية بجــدة ايجابيــة عينــة ممــا ضبط للحشــيش‬\n‫املخــدر واحتوائهــا علــى املــادة الفعالــة لــه املــدرج بجــدول املــواد املخــدرة‬\n‫رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصادر باملرســوم امللكي رقم م‪ 39/‬بتاريخ ‪1426/7/8‬هـ وباســتجواب‬\n‫املدعــى عليــه األول أقــر بــأن قطــع احلشــيش املخــدر املضبوطــة عائــدة‬\n‫لشــقيقه املدعــى عليــه الثالــث‪ .‬باســتجواب املدعــى عليــه الثالــث‪ :‬أفــاد‬\n‫بــأن املضبوطــات لشــخص يدعــى هــرب عنــد القبــض عليهــم‪ .‬وأســفر‬\n‫التحقيــق عــن توجيــه االتهــام إلــى املدعــى عليهــم‪ :‬بحيــازة (‪ )7073‬جــم‪،‬‬\n‫ســبعة آالف وثالثــة وســبعني جرام ـ ًا مــن مــادة احلشــيش املخــدر بقصــد‬\n‫الترويــج والتعاطــي وتعاطــي الثالــث لنوعهــا مــن الســابق املجــرم اســتناد ًا‬\n‫للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة املنــوه عنــه وذلــك لألدلة والقرائن التاليــة‪.1 :‬ما ورد يف إقراراتهم‬\n\n\n                                                                                         ‫‪246‬‬\n\f      ‫املنــوه عنهــا واملدونــة علــى الصفحــات املرفقــة لفــة (‪.2 .)35،37،39‬‬\n      ‫شــهادة الشــهود الــواردة يف محضــر البــاغ و القبــض والتفتيــش املنــوه‬\n      ‫عنهــا واملدونــة علــى الصفحتــن رقــم (‪ )18-12‬من ملــف ضبط إجراءات‬\n      ‫االســتدالل املرفــق لفــه (‪.3 .)1‬مــا ورد يف التقريــر الكيميائــي الشــرعي‬\n      ‫املنــوه عنــه واملرفــق لفــه (‪.4 .)54‬كبــر الكميــة قرينــة علــى قصــد‬\n      ‫ترويجهــا‪ .‬وبالبحــث عــن ســوابقهم عثــر لــأول علــى خمســة ســوابق‪:‬‬\n      ‫ثالثــة منهــا ترويــج القــات وســابقتي حيــازة قــات كمــا عثــر للثالــث علــى‬\n      ‫ثالثــة ســوابق‪ :‬األولــى اختــاء محــرم مقترنــة بشــرب املســكرات وقيــادة‬\n      ‫الســيارة بحالــة ســكر والثانيــة‪ :‬حيــازة قــات والثالثــة‪ :‬مخــدرات‪ .‬بينمــا‬\n      ‫لــم يعثــر للثانــي علــى ســوابق وحيــث إن مــا أقــدم عليــه املدعــى عليهــم‬\n      ‫وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظامــا‬\n      ‫طبقـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫واملعاقــب عليهــا اســتنادا للمادتــن (‪ )38،41‬مــن النظــام املشــار إليــه مــع‬\n      ‫مراعــاة مــا ورد يف الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن ذات النظــام فيمــا‬\n      ‫يتعلــق بالثالــث لــذا فإننــي أطلــب إثبــات إدانتهــم مبــا أســند إليهــم‬\n      ‫واحلكــم عليهــم بالعقوبــات األصليــة والتكميليــة التاليــة‪.1 :‬الســجن‬\n      ‫واجللــد والغرامــة ‪ ،‬اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة املنــوه عنــه‪.2 .‬مصــادرة املبالــغ‬\n      ‫املاليــة املضبوطــة بحوزتهــم والبالــغ مجموعهــا (‪)1797‬ريــاالً‪ ،‬اســتناد ًا‬\n      ‫للفقــرة (‪ )2‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املنــوه عنــه‪.3 .‬إبعادهــم عــن اململكــة بعــد االنتهــاء مــن تنفيــذ‬\n      ‫عقوبتهــم اســتناد ًا للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة املنــوه عنــه‪ .‬كمــا أطلــب تشــديد العقوبــة‬\n\n\n‫‪247‬‬\n\f‫علــى األول والثالــث مبــا يردعهمــا لقــاء تعــدد ســوابقهما اســتنادا لتعميــم‬\n‫ســمو نائــب وزيــر الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ‬\n‫‪1429/8/23‬ه ـ هــذه دعــواي وبتــاوة الئحــة املدعــي العــام علــى املدعــى‬\n‫عليهــم احلاضريــن يف مجلــس احلكــم وســؤالهم اجلــواب أجــاب املدعــى‬\n‫ا مــا ذكــره املدعــي العــام مــن أنــه قبــض علـ ّـي مــن قبــل‬‫عليــه األول قائـ ً‬\n‫مكافحــة املخــدرات بتاريــخ ‪1434/06/06‬ه ـ فذلــك كلــه صحيــح‬\n‫وقــد كنــت أنــا وشــخص آخــر يدعــى وأخــي املدعــى الثالــث يف الســيارة‬\n‫وعنــد القبــض علينــا هــرب املدعــو وبعــد القبــض علينــا أخرجــوا مــن‬\n‫الســيارة التــي كنــت أقودهــا قطــع مــن احلشــيش ال عالقــة لــي بهــا وال‬\n‫عالقــة لنــا باملدعــى عليــه الثانــي فلــم نشــاهده قبــل هــذا اليــوم ومــا‬\n‫ذكــره املدعــي العــام مــن وجــود عــدد خمــس ســوابق منهــا ثــاث منهــا يف‬\n‫ترويــج القــات وســابقتني يف حيازتــه كلهــا مســجلة علـ ّـي فذلــك صحيــح‬\n‫أيضــا أمــا مــا طالــب بــه املدعــي العــام مــن مصــادرة املبلــغ الــذي بحوزتــي‬\n‫فهــو لــي وعائــد مــن غيــر الترويــج هكــذا أجــاب وأجــاب املدعــى عليــه‬\n‫ا كل مــا ذكــره املدعــي العــام مــن أنــه قبــض علـ ّـي مــن قبــل‬  ‫الثانــي قائـ ً‬\n‫مكافحــة املخــدرات بتاريــخ ‪1434/06/06‬ه ـ فذلــك كلــه صحيــح أمــا‬\n‫مــا ذكــره املدعــي العــام مــن قيامــي باالشــتراك يف حيــازة احلشــيش‬\n‫املخــدر مــع بقيــة املدعــى عليهــم فغيــر صحيــح جملــة وتفصيــا فــا‬\n‫عالقــة بــي بهــم وبحمــد اهلل ال توجــد لــدي ســوابق مســجلة أمــا مــا طالــب‬\n‫بــه املدعــي العــام مــن مصــادرة املبلــغ الــذي بحوزتــي فهــو لــي وعائــد مــن‬\n‫ا‬\n‫غيــر الترويــج علـ ّـي هكــذا أجــاب وأجــاب املدعــى عليــه الثالــث قائ ـ ً‬\n‫مــا ذكــره املدعــي العــام مــن أنــه قبــض علـ ّـي مــن قبــل مكافحــة‬\n‫املخــدرات بتاريــخ ‪1434/06/06‬ه ـ فذلــك كلــه صحيــح وقــد كنــت‬\n\n\n                                                                                         ‫‪248‬‬\n\f      ‫أنــا وشــخص آخــر يدعــى وأخــي املدعــى األول يف الســيارة وعنــد القبــض‬\n      ‫علينــا هــرب املدعــو وبعــد القبــض علينــا أخرجــوا مــن الســيارة التــي‬\n      ‫كنــت أركــب فيهــا قطعــا مــن احلشــيش ال عالقــة لــي بهــا وهــي عائــدة‬\n      ‫لصديقــي املدعــو وال عالقــة لنــا باملدعــى عليــه الثانــي فلــم نشــاهده قبــل‬\n      ‫هــذا اليــوم وصحيــح مــا ذكــره املدعــي العــام مــن أننــي كنــت راكبــا‬\n      ‫يف املقعــد اخللفــي ومــا ذكــره املدعــي العــام مــن أننــي تعاطيــت احلشــيش‬\n      ‫إلــى يــوم القبــض علــي فذلــك صحيــح أيضــا ومــا ذكــره املدعــي العــام‬\n      ‫مــن وجــود عــدد ثــاث ســوابق األولــى اختــاء محــرم مقترنــة بشــرب‬\n      ‫املســكرات وقيــادة الســيارة بحالــة ســكر والثانيــة‪ :‬حيــازة قــات‬\n      ‫والثالثــة‪ :‬مخــدرات مســجلة علـ ّـي فذلــك صحيــح أيضــا أمــا مــا طالــب بــه‬\n      ‫املدعــي العــام مــن مصــادرة املبلــغ الــذي بحوزتــي فهــو لــي وعائــد مــن غيــر‬\n      ‫الترويــج هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه علــى أن املدعى‬\n      ‫عليهــم كانــت الكميــة بحوزتهــم بقصــد الترويــج والتعاطــي وأن مــا‬\n      ‫وجــد معهــم مــن مبالــغ عائــد مــن ترويــج احلشــيش أجــاب قائــا بينتــي مــا‬\n      ‫ذكرتــه يف املعاملــة مــن أدلــة وقرائــن هكــذا أجــاب هــذا وقــد جــرى‬\n      ‫اطالعــي علــى أوراق املعاملــة وعلــى التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم(‪/2130‬ك ش م) لعــام ‪1434‬ه ـ املرفــق باملعاملــة لفــة رقــم (‪)54‬‬\n      ‫ويتضمــن إيجابيــة احتــواء العينــة للحشــيش املخــدر كمــا جــرى اطالعي‬\n      ‫علــى اقــرار املدعــى عليــه األول املرفــق باملعاملــة باللفــة رقــم (‪)37‬‬\n      ‫املتضمــن مــا نصــه أقــر أنــا مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ()‬\n      ‫أقــر وأنــا بكامــل قــواي العقليــة املعتبــرة شــرعا دون إكــراه أو إجبــار‬\n      ‫مــن احــد بأننــي مت القبــض علــى بتاريخ ‪1434/6/6‬هـ من قبل مكافحة‬\n      ‫املخــدرات أثنــاء تواجدنــا يف حــي الكنــدرة يف محــل جــواالت وكان‬\n\n\n‫‪249‬‬\n\f‫يرافقنــي أخــي ‪ /‬وشــخص مينــي اســمه ‪ /‬وكان املدعــو‪ /‬يف محــل‬\n‫اجلــواالت وليــس لنــا بــه عالقــة وليــس لــه أي علــم أو عالقــة مبــا ضبــط‬\n‫معنــا وبتفتيــش ســيارة أخــي ‪ /‬مــن نــوع (‪ )....‬صنــع (‪ )...‬لوحــه رقــم (‪)....‬‬\n‫لــون الســيارة (‪ ).....‬قمــت باســتئجارها وضبــط كيــس بداخلــة حشــيش‬\n‫مخــدر يــزن (‪ )7073‬ســبعه االف جــرام وثالثــة وســبعني جرامـ ًا ضبطــت‬\n‫يف املرتبــة اخللفيــة عائــد ألخــي ‪ /‬وصاحبــة حيــث كان مرافقــا لنــا يف‬\n‫الســيارة هــذا إقــرار منــي بذلــك وعليــه أوقــع كمــا جــرى اطالعــي علــى‬\n‫اقــرار املدعــى عليــه الثانــي املرفــق باملعاملــة باللفــة رقــم (‪ )35‬املتضمــن‬\n‫مــا نصــه أقــر أنــا مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم () أقــر وأنــا‬\n‫بكامــل قــواي العقليــة املعتبــرة شــرعا دون إكــراه أو إجبــار مــن احــد‬\n‫بأننــي مت القبــض علــى بتاريــخ ‪1434/6/6‬ه ـ مــن قبــل مكافحــة‬\n‫املخــدرات أثنــاء تواجدنــا يف حــي الكنــدرة يف محــل جــواالت وكان‬\n‫يرافقنــي املتهــم ‪ /‬واملتهــم وبتفتيــش ســيارة املتهــم ‪ /‬مــن نــوع (‪ )....‬صنــع‬\n‫(‪ )....‬لوحــه رقــم (‪ )....‬لــون الســيارة (‪ )....‬قمــت باســتئجارها ضبــط‬\n‫كيــس بداخلــة حشــيش مخــدر يــزن (‪ )7073‬ســبعه أالف جــرام وثالثــة‬\n‫وســبعني جرامـ ًا ضبطــت يف املرتبــة اخللفيــة ليــس بهــا أي علــم أو عالقــة‬\n‫وال اعــرف املتهمــن حيــث أنــي حضــرت للمحــل لشــراء جــوال‬\n‫وبإمكانكــم الرجــوع للمحــل للتأكــد وليــس لــي أي عالقــة باملتهمــن‬\n‫هــذا اقــرار منــي بذلــك وعليــه أوقــع كمــا جــرى اطالعــي علــى اقــرار‬\n‫املدعــى عليــه الثالــث املرفــق باملعاملــة باللفــة رقــم (‪ )39‬املتضمــن مــا‬\n‫نصــه أقــر انــا مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )...‬وتاريــخ‬\n‫‪1434/6/7‬ه ـ صــادرة مــن مكافحــة املخــدرات أقــر وأنــا بكامل قواي‬\n‫العقليــة املعتبــرة شــرعا دون إكــراه أو إجبــار مــن احــد بأننــي مت القبــض‬\n\n\n                                                                                         ‫‪250‬‬\n\f      ‫علــى بتاريــخ ‪1434/6/6‬ه ـ مــن قبــل مكافحــة املخــدرات أثنــاء تواجدنا‬\n      ‫يف حــي الكنــدرة يف محــل جــواالت وكان يرافقنــي أخــي ‪ /‬وشــخص‬\n      ‫مينــي اســمه ‪ /‬وكان املدعــو‪ /‬يف محــل اجلــواالت وليــس لنــا بــه عالقــة‬\n      ‫وليــس لــه أي علــم أو عالقــة مبــا ضبــط معنــا وبتفتيــش ســيارة أخــي ‪/‬‬\n      ‫مــن نــوع (‪ ).....‬صنــع (‪ ).....‬لوحــه رقــم (‪ )...‬لــون الســيارة (‪ )....‬قمــت‬\n      ‫باســتئجارها وضبــط كيــس بداخلــة حشــيش مخــدر يــزن (‪)7073‬‬\n      ‫ســبعه أالف جــرام وثالثــة وســبعني جرام ـ ًا ضبطــت يف املرتبــة اخللفيــة‬\n      ‫عائــد للشــخص الــذي كان معنــا‪ /‬حيــث كان مرافقــا لنــا يف الســيارة‬\n      ‫علمــا بأننــي أتعاطــى احلشــيش املخــدر منــذ خمــس ســنوات كان آخرهــا‬\n      ‫يــوم القبــض علــي هــذا إقــرار منــي بذلــك وعليــه أوقــع كمــا جــرى‬\n      ‫اطالعــي علــى شــهادة الشــهود يف محضــر القبــض املرفــق باملعاملــة‬\n      ‫باللفــة رقــم (‪ )1‬صحيفــة رقــم (‪ )13-12‬املتضمــن مــا نصــه بنــاء ملــا تقــدم‬\n      ‫جــرى اتخــاذ الــازم علــى النحــو التالــي جــرى االنتقــال يف متــام الســاعة‬\n      ‫السادســة مســاء برفقــة املصــدر ملوقــع املذكــور ومت البــدء يف اتخــاذ‬\n      ‫املوقــع املناســب علــى النحــو التالــي معاينــة املوقــع واتضــح أنــه عبــارة عــن‬\n      ‫شــارع وســط حــي البغداديــة وجــرى التمركــز بأحــد املواقــع الثانيــة‬\n      ‫وذلــك يف متــام الســاعة السادســة مســاء رصــد املوقــع ويف متــام الســاعة‬\n      ‫التاســعة شــوهدت ســيارة مــن نــوع (‪ ).....‬حتمــل اللوحــة رقــم (‪ )....‬بقيــادة‬\n      ‫شــخص ويرافقــه شــخصان آخــران أشــار املصــدر بــأن قائــد الســيارة هــو‬\n      ‫املقصــود ومتــت متابعتهــم حتــى وصلــوا حلــي الكنــدرة وأوقفــوا الســيارة‬\n      ‫وترجلــوا احــد محــات االتصــاالت وبالقبــض والتفتيــش ومت القبــض‬\n      ‫عليهــم وهــم املدونــة أســمائهم عوضــه األول املقصــود والثانــي املرافــق‬\n      ‫باملرتبــة األماميــة والثالــث املرافــق باملرتبــة اخللفيــة خلــف الســائق‬\n\n\n‫‪251‬‬\n\f‫وبتفتيشــهم شــخصيا لــم يعثــر بحوزتهــم علــى أي مــن املمنوعــات‬\n‫ومبناقشــتهم عــن الســيارة أنكروهــا وبتفتيــش الســيارة عثــر مــكان‬\n‫أقــدام الراكــب اخللفــي خلــف الســائق كيــس نايلــون اخضــر ملفــوف‬\n‫كبيــر احلجــم اتضــح بداخلــة ســبع قطــع مســتطيلة الشــكل مغلفــة‬\n‫بغــاف وضعــي بالســتيكي جميعهــا ســوداء اللــون يشــتبه أنهــا حشــيش‬\n‫مخــدر ومبناقشــة املتهمــن األول والثانــي والثالــث عــن مــا ضبــط‬\n‫بالســيارة أنكروهــا جميعــا وعــن مقــر ســكنهم املقصــود بأنــه يســكن‬\n‫بحــي ‪ ......‬والثالــث يســكن بقربــة يف حــي ‪ ........‬والثالــث أفــاد بأنــه ال‬\n‫يوجــد لديــه ســكن وبتفتيــش منــزل األول وهــو عبــارة عــن شــقة بعمــارة‬\n‫بحــي ‪ .....‬لــم يعثــر علــى شــيء مــن املمنوعــات واتضــح أن الثالــث يســكن‬\n‫بقربــة يف حــي الكنــدرة مكونــة مــن غرفــة مبنافعهــا لــم يعثــر بهــا علــى‬\n‫شــيء مــن املمنوعــات اتضــح أن للســيارة عقــد إيجــار باســم املقصــود‬\n‫األول مســتأجرة مــن شــركة (‪ ).....‬كمــا جــرى اطالعــي علــى محضــر‬\n‫البــاغ يف محضــر القبــض املرفــق باملعاملــة باللفــة رقــم (‪ )1‬صحيفــة رقــم‬\n‫(‪ )2‬املتضمــن مــا نصــه احلمــد هلل وحــدة والصــاة والســام علــى مــن ال‬\n‫نبــي بعــده أمــا بعــد فقــد جــرى بتاريــخ ‪1434/06/06‬ه ـ فتــح هــذا‬\n‫احملضــر مبكتــب الفرقــة امليدانيــة اخلامســة بقســم القيــادة والســيطرة‬\n‫بشــبعة التحريــات بــإدارة مكافحــة املخــدرات مبحافظــة جــدة وذلــك‬\n‫بنــاء للســيطرة علــى مروجــي املخدرات على مســتوى جــدة وحث املصادر‬\n‫الســرية على تزويدنا باملعلومات عنهم وعن وســائل تنقلهم ومســاكنهم‬\n‫واألماكــن التــي يتواجــدون فيهــا ومــن ضمــن هــؤالء األشــخاص شــخص‬\n‫يدعــي مينــي اجلنســية اشــتهر يف أوســاط مروجــي ومتعاطــي احلشــيش‬\n‫املخــدر ولــم تعــرف معلومــات كافيــة عنــه للقبــض عليــه باجلــرم املشــهود‬\n\n\n                                                                                    ‫‪252‬‬\n\f      ‫فقــد كان مــن ضمــن األشــخاص الذيــن نســعى للقبــض عليهــم ولذلــك‬\n      ‫جــرى حــث مصادرنــا بتزويدنــا مبــا يتوفــر عنــه مــن معلومــات وبتاريخــه‬\n      ‫أعــاه أبلغنــا أحــد مصادرنــا الســرية بتوصلــه ملعلومــات عــن مــكان ميــر‬\n      ‫منــه املقصــود وذلــك بحــي البغداديــة وذكــر املصــدر انــه لــم يســتطيع‬\n      ‫التوصــل الــى مســكنه أو وســيلة االتصــال بــه واســتعد باإلرشــاد علــى‬\n      ‫املوقــع وبنــاء عليــه متــت املباشــرة مبــا ذكــر حســب مــا يتضــح يف ثنايــا‬\n      ‫هــذا امللــف كمــا جــرى اطالعــي علــى صحيفــة ســوابق املدعــى عليــه‬\n      ‫األول املرفقــة باملعاملــة باللفــة رقــم (‪ )48-47‬املتضمنــة وجــود عــدد‬\n      ‫خمــس ســوابق منهــا ثــاث منهــا يف ترويــج القــات وســابقتني يف حيازتــه‬\n      ‫كلهــا مســجلة علــى املدعــى عليــه كمــا جــرى اطالعــي علــى صحيفــة‬\n      ‫ســوابق املدعــى عليــه الثالــث املرفقــة باملعاملــة باللفة رقــم (‪ )51‬املتضمنة‬\n      ‫وجــود عــدد ثــاث ســوابق منهــا عــدد ثــاث ســوابق األولــى‪ :‬اختــاء‬\n      ‫محــرم مقترنــة بشــرب املســكرات وقيــادة الســيارة بحالــة ســكر‬\n      ‫والثانيــة‪ :‬حيــازة قــات والثالثــة‪ :‬حيــازة حشــيش وقــات للتعاطــي كلهــا‬\n      ‫مســجلة علــى املدعــى عليــه كمــا جــرى اطالعــي علــى صحيفــة ســوابق‬\n      ‫املدعــى عليــه الثانــي املرفقــة باملعاملــة باللفــة رقــم ( ‪ ) 53‬املتضمنــة عــدم‬\n      ‫وجــود أيــة ســوابق مســجلة علــى املدعــى عليــه وبســؤال املدعــى عليــه‬\n      ‫األول والثالــث عــن احلشــيش أجابــا هــو للمدعــو وبســؤال األول عــن‬\n      ‫احلشــيش أجــاب قائــا هــو ألخــي وزميلــه هكــذا أجــاب عليــه فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره أطــراف الدعــوى وإلنــكار‬\n      ‫املدعــى عليهــم حيــازة الكميــة املضبوطــة بقصــد الترويــج وإنكارهــم‬\n      ‫معرفتهــم بوجودهــا وملــا ذكــره املدعــى عليهمــا األول والثالــث مــن وجود‬\n      ‫كميــة احلشــيش بالســيارة ووجودهــا بجانــب الثالــث يف اخللــف ومــا‬\n\n\n‫‪253‬‬\n\f‫قــرراه مــن عــدم معرفتهمــا باملدعــى عليــه الثانــي وكــون القبــض كان‬\n‫يف ســوق وإنــكار املدعــى عليــه الثانــي معرفتــه بهمــا ولعــدم وجــود‬\n‫ســوابق مســجلة عليــه وملــا ذكــره املدعــي العــام مــن أدلــة وقرائــن وملــا‬\n‫تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه بعاليــة ألجــل ذلــك‬\n‫كلــه فقــد ثبــت لــدي تعاطــي املدعــى عليــه الثالــث للحشــيش املخــدر من‬\n‫الســابق كمــا ثبــت لــدي إدانــة املدعــى عليهمــا األول والثالــث‬\n‫املذكوريــن بعاليــه مبــا نســب إليهمــا مــن اشــتراكهما بحيــازة (‪)7073‬‬\n‫جــم‪ ،‬ســبعة آالف وثالثــة وســبعني جرامـ ًا حتتــوي علــى احلشــيش املخــدر‬\n‫حيــازة مجــردة كمــا لــم يثبــت لــدي إدانــة املدعــى عليهــم املذكوريــن‬\n‫بعاليــه مبــا نســب إليهــم مــن اشــتراك املدعــى عليهــم بحيــازة (‪)7073‬‬\n‫جــم‪ ،‬ســبعة آالف وثالثــة وســبعني جرامـ ًا حتتــوي علــى احلشــيش املخــدر‬\n‫لقصــد الترويــج والتعاطــي لهــا إال أن الشــبهة تتجــه نحــو املدعــى عليهمــا‬\n‫األول والثالــث بحيازتهمــا لســبعة آالف وثالثــة وســبعني جرام ـ ًا حتتــوي‬\n‫علــى احلشــيش املخــدر لقصــد الترويــج والتعاطــي لهــا وذلــك للقرائــن‬\n‫التاليــة‪ :‬أوال‪ :‬وجــود الكميــة يف الســيارة التــي يســتقالنها‪ .‬ثانيــا‪ :‬عــدم‬\n‫قدرتهمــا علــى إثبــات أن الكميــة املضبوطــة عائــدة للشــخص املدعــو‬\n‫‪ ......‬وعــدم إرشــادهما عنــه‪ .‬ثالثــا‪ :‬وجــود ســوابق علــى املدعــى عليهمــا‪.‬‬\n‫رابعــا‪ :‬تعاطــي الثالــث مــن احلشــيش يقــوى الشــبه نحــوه‪ .‬خامســا‪ :‬وجــود‬\n‫املدعــى عليــه الثالــث باملقعــد اخللفــي حيــث وجــدت الكميــة‪ .‬سادســا‪:‬‬\n‫وجــود إخباريــة تفيــد أن املدعــى عليــه األول يقــوم بترويــج احلشــيش‪ .‬ولــم‬\n‫يتوجــه لــدي اجتــاه املدعــى عليــه الثانــي أي شــبهة وذلــك ملــا يلــي‪:‬‬\n‫وإنــكاره معرفــة املدعــى عليهمــا األول والثالــث ثانيــا‪ /‬مــا ذكــره‬\n‫املدعــى عليهمــا األول والثالــث مــن عــدم معرفتهمــا باملدعــى عليــه الثانــي‬\n\n\n                                                                                    ‫‪254‬‬\n\f      ‫ثالثــا‪ :‬كــون القبــض كان يف ســوق ويحتمــل أن يكــون القبــض علــى‬\n      ‫شــخص آخــر غيــر املطلــوب نظــرا ملــا هــو مشــاهد مــن ازدحــام عنــد‬\n      ‫مراكــز االتصــاالت‪ .‬رابعــا‪ :‬عــدم وجــود ســوابق مســجلة عليــه خامســا‪:‬‬\n      ‫مــا اســتند إليــه املدعــي العــام هــو اعتــراف املذكــور وباالطــاع عليــه‬\n      ‫وجدتــه ال يدينــه مبــا نســب إليــه سادســا‪ :‬أن غايــة مــا قدمــه املدعــي‬\n      ‫العــام اجتاهــه هــو مــا جــاء يف محضــر القبــض مــن أن املدعــى عليــه‬\n      ‫قبــض عليــه مــن قبــل الفرقــة‪ .‬ســابعا‪ :‬أن األصــل بــراءة الذمــة وال يجــوز‬\n      ‫شــغلها إال بيقــن يف ثبــوت التهمــة أو االدانــة والدليــل إذا ورد عليــه‬\n      ‫االحتمــال ســقط بــه االســتدالل ثامنــا‪ :‬أنــه ال يجــوز إيقــاع عقوبــة جزائيــة‬\n      ‫إال بعــد ثبــوت اإلدانــة وفقــا للمــادة الثالثــة مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫قبيحــا‬\n          ‫ً‬     ‫ا‬\n                ‫محرمــا وفع ـ ً‬\n                           ‫ً‬     ‫ا‬\n                                 ‫ومبــا أن مــا قــام بــه املدعــى عليهمــا يعــد عم ـ ً‬\n      ‫وجــرأة يف الباطــل يســتحقا العقــاب عليــه ومبــا أن ترويــج ذلــك فيــه نشــر‬\n      ‫للفســاد أوســاط املجتمــع وهــو مــن التعــاون علــى اإلثــم والعــدوان واهلل‬\n      ‫ســبحانه وتعالــى يقــول (وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى‬\n      ‫اإلثــم والعــدوان) ومبــا أن تعاطــي احلشــيش املخــدر يــؤول إلــى االســكار‬\n      ‫واهلل تعالــى يقــول‪ ( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n      ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر حــرام ) وملــا‬\n      ‫يف ذلــك مــن إضــرار بنفــس اإلنســان وعقلــه والواجــب عليــه حفظهمــا‬\n      ‫والشــريعة اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا حفــظ‬\n      ‫النفــس والعقــل والنتشــار هــذه احملظــورات أوســاط املجتمــع وهــذا‬\n      ‫يســتوجب األخــذ علــى مــن يقــوم بترويجهــا بحــزم الســيما مــع كثــرة‬\n      ‫ســوابق املدعى عليهما األول والثالث ولكون املدعى عليهم يســتحقون‬\n\n‫‪255‬‬\n\f‫طبقــا للقواعــد الشــرعية وكــون املدعــى عليهمــا األول الثالــث‬   ‫العقوبــة ً‬\n‫وفقــا للمــادة (‪ )56 -39‬مــن نظــام مكافحــة‬       ‫يســتحقا العقوبــة أيضــا ً‬\n‫املخــدرات فلمــا ســبق فقــد حكمــت علــى املدعــى عليهــم تعزيــر ًا مبــا‬\n‫يلــي‪ :‬أوالً‪ :‬إقامــة حــد املســكر علــى املدعــى عليــه الثالــث وذلــك بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة أمــام مــأ مــن النــاس لقــاء تعاطيــه للحشــيش‬\n‫املخــدر مــن الســابق ثانيـاً‪ :‬يســجن كل واحــد مــن املدعــى عليهمــا األول‬\n‫موقوفــا يف هــذه القضيــة‬\n                        ‫ً‬     ‫والثالــث ملــدة ســنتني يحتســب منهــا مــا أمضــاه‬\n‫ويجلــد كل واحــد منهمــا خمســن جلــدة مكــررة عليــه أربــع مــرات بــن‬\n‫كل مــرة وأخــرى مــدة ال تقــل عــن خمســة عشــر يومــا ويكــون بــن هــذا‬\n‫اجللــد وجلــد احلــد بالنســبة لــأول مــدة ال تقــل عــن خمســة عشــر يومــا‬\n‫ويدفــع كل واحــد منهمــا غرامــة ماليــة قدرهــا خمســة االف ريــال وفقــا‬\n‫للمــادة رقــم (‪ )39‬مــن النظــام املشــار إليــه‪ .‬ثالثــا‪ :‬يبعــد املدعــى عليهمــا‬\n‫األول الثالــث خــارج اململكــة وال يســمح لــه بالعــودة إليهــا إال وفــق‬\n‫تعليمــات احلــج والعمــرة وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن‬\n‫نظــام مكافحــة املخــدرات املشــار إليــه وذلــك لقــاء تعاطيــه للحشــيش‬\n‫املخــدر‪ .‬رابعــا‪ :‬رددت مطالبــة املدعــي العــام بتطبيــق الوصــف اجلرمــي‬\n‫الــوارد يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة والفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬من ذات النظام‬\n‫ومطالبتــه بالغرامــة والســجن واجللــد للمدعــى عليهــم وابعــاد املدعــى‬\n‫عليهمــا األول والثانــي وذلــك لعــدم قــدرة املدعــي العــام علــى اثبــات‬\n‫الوصــف اجلرمــي الــوراد يف املادتــن‪ .‬خامســا‪ :‬رددت مطالبــة املدعــي‬\n‫العــام بتطبيــق الوصــف اجلرمــي الــوارد يف الفقــرة (‪ )2‬مــن املــادة (‪)53‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ومصــادرة املبالــغ‬\n\n\n                                                                                       ‫‪256‬‬\n\f      ‫املاليــة املضبوطــة بحــوزة املدعــى عليهــم والبالــغ مجموعهــا (‪)1797‬ريــا ًال‬\n      ‫وذلــك لعــدم قــدرة املدعــي العــام علــى اثبــات الوصــف اجلرمــي الــوراد يف‬\n      ‫املــادة وعــدم قدرتــه علــى اثبــات عائديــة املبالــغ مــن الترويــج‪ .‬سادســا‪:‬‬\n      ‫يســجن كل واحــد مــن املدعــى عليهمــا األول والثالــث ملــدة ســنة تبــدأ‬\n      ‫مــن تاريــخ انتهــاء مــدة الســجن احملكــوم بهــا يف ثانيــا ويجلــد كل واحــد‬\n      ‫منهمــا خمســن جلــدة مكــررة عليــه أربــع مــرات بــن كل مــرة وأخــرى‬\n      ‫مــدة ال تقــل عــن خمســة عشــر يومــا ويكــون بــن هــذا اجللــد واجللــد‬\n      ‫الســابق مــدة ال تقــل عــن خمســة عشــر يومــا وذلــك لقــاء االشــتباه بهمــا‬\n      ‫فيمــا نســب إليهمــا‪ .‬سادســا‪ :‬أخليــت ســبيل املدعــى عليــه الثانــي وأمــرت‬\n      ‫باإلفــراج عنــه وفقــا للمــادة السادســة عشــرة بعــد املائتــن مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة وذلــك مبوجــب كتابــي رقــم ‪ 341935759‬وتاريــخ‬\n      ‫‪1434/08/09‬ه ـ وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n      ‫معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه‬\n      ‫باحلضــور يف يــوم األربعــاء املوافــق ‪1434/8/10‬ه ـ الســاعة ‪08 :00‬‬\n      ‫الســتالم نســخة مــن قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال مــدة‬\n      ‫ثالثــن يومــا اعتبــار ًا مــن التاريــخ املشــار إليــه فــان مضــت املــدة ولــم‬\n      ‫يســتلم نســخة مــن احلكــم أو لــم يقــدم اعتراضــه عليــه خاللهــا فــان حقــه‬\n      ‫يف تقــدمي الئحــة االعتــراض يكــون ســاقط ًا كمــا قــرر املدعــى عليهــم‬\n      ‫قناعتهــم بــه وجــرى النطــق باحلكــم يف يــوم الثالثــاء املوافــق‬\n      ‫‪1434/08/09‬ه ـ الســاعة ‪ 11 :00‬وبــه أقفلــت اجللســة وعلــى ذلــك جــرى‬\n      ‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                     ‫‪1434/08/09‬هـ ‪.‬‬\n      ‫احلمــد اهلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ....‬نحــن رئيــس‬\n\n\n‫‪257‬‬\n\f‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقة مكة‬\n‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 34293242‬وتاريــخ‬\n‫‪1434/8/9‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ....‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪ ....‬مينــي‬\n‫اجلنســية ورفيقيــه ‪ ،‬املتهمــن بحيــازة مخــدرات‪ ،‬احملكــوم فيــه مبــا دون‬\n‫باطنــه‪ .‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                            ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                  ‫‪258‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":243,"source_page_end":258,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5875388b8dcfbc51a83634c11a5e7e9090f38180ce324f7fc2277c52bea1d254","normalized_text_hash":"90b45546e5412e1a700a4a71018ddc545f207da6d7a9c1221d825728d7e7c883","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p243-34293242"},{"id":"778657fb-fd4a-546a-8669-1072a52b0c2d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة -اشتراك يف حيازة بقصد الترويج والتعاطي- قات -تداخل العقوبات التعزيرية -التعزير بالسجن واجللد .","document_number":"34298921","case_number":"34377739","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/16","year":"1434","subject":"مخدرات -حيازة -اشتراك يف حيازة بقصد الترويج والتعاطي- قات -تداخل العقوبات التعزيرية -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34298921:‬تاريخه‪1434/8/16:‬هـ‬\n                        ‫رقم القضية‪34377739:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34367386‬تاريخه‪1434/11/21:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة ‪ -‬اشــتراك يف حيــازة بقصــد الترويــج والتعاطــي‪-‬‬\n        ‫قــات ‪ -‬تداخــل العقوبــات التعزيريــة‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫‪ -1‬مــا رواه ابــن عبــاس قــال ( لعــن رســول اهلل صلــى اهلل عليــه وســلم‬\n      ‫املتشــبهني مــن الرجــال بالنســاء واملتشــبهات مــن النســاء بالرجــال )‪.‬‬\n                                                              ‫أخرجــه البخــاري‬\n      ‫‪ -2‬مــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة حيــث جــاء‬\n      ‫يف كشــاف القنــاع ج ‪ 485/ 20‬للبهوتــي ( ولــو توجــه عليــه تعزيــرات‬\n      ‫علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل‬\n      ‫أجنبيــة مــرارا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــدا‬\n                                            ‫تداخلــت وكفــاه تعزيــر واحــد ) ‪.‬‬\n      ‫‪ -3‬املادة الرابعة من قرار وزير الداخلية رقم (‪ )2057‬يف ‪1404/5/26‬هـ‪.‬‬\n                             ‫‪ -4‬القرار الوزاري رقم (‪ )3818‬يف ‪ 1410/9/28‬هـ ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه األول باالشــتراك يف حيــازة‬\n      ‫قــات بقصــد الترويــج والتعاطــي والتشــبه بالنســاء لتضليــل رجــال‬\n      ‫األمــن ‪،‬واملدعــى عليــه الثانــي بحيــازة قــات بقصــد الترويــج والتعاطــي‬\n\n‫‪259‬‬\n\f‫وطلــب إثبــات مــا أســند إليهمــا ومعاقبتهــا تعزيــرا ‪،‬حيــث مت االشــتباه‬\n‫يف الســيارة التــي يقودهــا املدعــى عليــه الثانــي عنــد نقطــة التفتيــش‬\n‫ويرافقــه املدعــى عليــه األول بــزي نســائي وعنــد تفتيــش الســيارة عثــر‬\n‫علــى القــات وأثبــت التقريــر الكيميائــي إيجابيــة العينــة املضبوطــة‬\n‫لنبــات القــات احملظــور ‪ ،‬صــادق املدعــى عليهمــا علــى دعــوى املدعــي‬\n‫العــام ماعــدا الترويــج فأنكــرا ذلــك ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n‫احملكمــة بســجنهما ثمانيــة أشــهر وجلدهمــا ســبعني جلــدة دفعــة واحــدة‬\n‫‪،‬وصــدق‬\n      ‫‪،‬وقنــع املدعــى عليهمــا اعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                      ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )341953035‬وتاريــخ ‪1434/8/13‬هـ‬\n‫واحملالة من فضيلة الرئيس برقم (‪ )34377739‬وتاريخ ‪1434/8/13‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪.....‬و‪ .....‬املتهمــن يف قضيــة حيــازة‬\n‫لنبــات القــات عليــه ففــي هــذا اليــوم االثنــن ‪1434/8/15‬ه ـ افتتحــت‬\n‫اجللســة األولــى يف متــام الســاعة الثانيــة عشــرة وفيهــا حضــر املدعــي العــام‬\n‫‪ .....‬املوجــه باخلطــاب رقــم (‪ ).....‬وتاريــخ ‪1431/8/14‬ه ـ وادعــى علــى‬\n‫احلاضريــن ‪.....‬ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله‬\n‫املدنــي (‪ ).....‬و‪ .....‬ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله‬\n‫املدنــي (‪ ).....‬أنــه بتاريــخ ‪1434/7/3‬ه ـ وأثنــاء قيــام الدوريــات األمنيــة‬\n‫بشــرطة العارضــة بواجبهــا يف نقطــة تفتيــش احلظــوة قدمــت ســيارة مــن‬\n\n                                                                                       ‫‪260‬‬\n\f      ‫نــوع ‪ ....‬مــن صنــع عــام (‪2009‬م) حتمــل اللوحــة رقــم (‪ .....‬مت تســليم‬\n      ‫الســيارة) كانــت بقيــادة املدعــى عليــه ‪ .....‬ترافقــه امــرأة حســب أقــوال‬\n      ‫قائــد الســيارة أنهــا زوجتــه وأبــرز لهــم كــرت العائلــة كإثبــات عائلتــه‬\n      ‫وتدعــى ‪.....‬وعنــد االشــتباه يف وضــع العائلــة اتضــح أنــه رجــل ويرتــدي‬\n      ‫الــزي النســائي ويدعــى ‪.....‬وبتفتيــش الســيارة عثــر علــى كميــة مــن نبات‬\n      ‫القــات احملظــور كانــت مخبــأة داخــل املرتبــة اخللفيــة والصــدام اخللفــي‬\n      ‫للســيارة بلــغ وزنهــا (‪25‬كجــم) خمســة وعشــرين كيلــو جــرام وقــد‬\n      ‫أثبــت التقريــر الكيميائــي الشــرعي رقــم(‪ ).....‬وتاريــخ ‪1434/7/11‬ه ـ‬\n      ‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n      ‫بجــازان إيجابيــة العينــة املرســلة منــه لنبــات القــات احملظــور املــدرج علــى‬\n      ‫اجلــدول رقــم (‪ )4‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة علم ًا‬\n      ‫ـاء علــى القــرار الــوزاري (‪ )1900‬يف ‪1428/7/9‬ه ـ‬          ‫أنــه مت إيقافهمــا بنـ ً‬\n      ‫املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة وباســتجواب‬\n      ‫املدعــى عليــه ‪.....‬ومواجهتــه بالتهمــة املنســوبة إليــه أقــر بصحــة واقعــة‬\n      ‫القبــض وذكــر بــأن الكميــة تعــود لــه ولقائــد الســيارة‪.....‬بقصد‬\n      ‫التعاطــي وأنــه حصــل عليهــا مــن محافظــة العارضــة مــن شــخص مينــي ال‬\n      ‫يعــرف اســمه لقيــه خلــف الســوق الشــعبي وأنــه حصــل علــى الكميــة عــن‬\n      ‫طريــق الشــراء مببلــغ قــدره (‪5000‬ريــال) خمســة آالف ريــال مناصفــة‬\n      ‫بينــه وبــن مرافقــه وأنــه كان ينــوي إيصــال الكميــة ملنزلــه الكائــن‬\n      ‫بقريــة ‪.....‬التابعــة حملافظــة العارضــة لغــرض تعاطيهــا وأنــه يقــوم بحفــظ‬\n      ‫القــات داخــل ثالجــة باملنــزل ويتنــاول يوميـ ًا حوالــي أربــع حــزم مــن نبــات‬\n      ‫القــات وأنــه لبــس العبــاءة النســائية خوفـ ًا مــن رجــال األمــن وقــد صــادق‬\n      ‫علــى أقوالــه حتقيقــا وباســتجواب املدعــى عليــه ‪ .....‬ومواجهتــه بالتهمــة‬\n\n\n‫‪261‬‬\n\f‫املنســوبة إليــه أقــر بصحــة واقعــة القبــض وذكــر أن الكميــة تعــود لــه‬\n‫وملرافقــه ‪.....‬بقصــد التعاطــي وأنــه حصــل عليهــا مــن محافظــة العارضــة‬\n‫مــن شــخص مينــي ال يعــرف اســمه لقيــه خلــف الســوق الشــعبي وأنــه‬\n‫حصــل علــى الكميــة عــن طريــق الشــراء مببلــغ قــدره (‪5000‬ريــال)‬\n‫ثالثــة آالف ريــال مناصفــة بينــه وبــن مرافقــه وأنــه كان ينــوي إيصــال‬\n‫الكميــة ملنزلــه الكائــن بقريــة ‪.....‬التابعــة حملافظــة العارضــة لغــرض‬\n‫تعاطيهــا وأنــه يقــوم بحفــظ القــات داخــل ثالجــة باملنــزل ويتنــاول يومي ـ ًا‬\n‫حوالــي ســت حــزم مــن نبــات القــات وأن الســيارة تعــود ألخيــه املدعــو ‪.....‬‬\n‫وليــس لــه علــم أو عالقــة بالكميــة املضبوطــة وأنــه ألبــس مرافقــه ‪.....‬‬\n‫عبــاءة نســائية وقــدم كــرت العائلــة للدوريــة األمنيــة علــى أنهــا زوجتــه‬\n‫وقــد صــادق علــى أقوالــه حتقيقــا وقــد أســفر التحقيــق مــع املدعــى‬\n‫عليهمــا عــن توجيــه االتهــام إلــى ‪.....‬باالشــتراك يف حيــازة مــا وزنــه‬\n‫(‪25‬كجــم) خمســة وعشــرين كيلــو جــرام مــن نبــات القــات احملظــور‬\n‫بقصــد الترويــج والتعاطــي والتشــبه بالنســاء لتضليــل رجــال األمــن‬\n‫وتوجيــه االتهــام إلــى ‪.....‬بحيــازة مــا وزنــه (‪25‬كجــم) خمســة وعشــرين‬\n‫كيلــو جــرام مــن نبــات القــات احملظــور بقصــد الترويــج والتعاطــي‬\n‫واملجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ وألن مــا أقــدم عليــه املدعــى عليهمــا فعــل محــرم‬\n‫شــرع ًا ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات فقــد طلــب املدعــي العــام إثبــات‬\n‫إدانتهمــا مبــا أســند إليهمــا واحلكــم بتعزيرهمــا يف ضــوء املادتــن الثالثــة‬\n‫والرابعــة مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذا لألمــر الســامي‬\n\n\n                                                                                      ‫‪262‬‬\n\f      ‫الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ واحلكــم بتعزيــر املتهــم‬\n      ‫األول لقــاء قيامــه مبحاولــة تضليــل رجــال األمــن والتشــبه بالنســاء‬\n      ‫وبعــرض الدعــوى علــى املدعــى عليه األول صدق القبض عليه يف الزمان‬\n      ‫واملــكان املشــار إليهمــا واشــتراكه يف حيــازة كميــة القــات املضبوطــة‬\n      ‫بقصــد االســتعمال الشــخصي وارتــداءه للعبــاءة النســائية عنــد القبــض‬\n      ‫بقصــد التخفــي لتجــاوز نقطــة التفتيــش هكــذا أجــاب وأنكــر قصــد‬\n      ‫الترويــج وبعــرض الدعــوى علــى املدعــى عليــه الثانــي صــدق القبــض‬\n      ‫عليــه يف الزمــان واملــكان املشــار إليهمــا واشــتراكه يف حيــازة كميــة‬\n      ‫القــات املضبوطــة بقصــد االســتعمال الشــخصي وأنــه أبــرز صــورة مــن‬\n      ‫ســجل أســرته لرجــال األمــن وذكــر لهــم أن مرافقــه امــرأة وأنهــا زوجتــه‬\n      ‫وأقــر بأنــه قبــل الوصــول إلــى نقطــة التفتيــش أشــار علــى املدعــى عليــه‬\n      ‫األول بارتــداء العبــاءة النســائية بقصــد التخفــي لتجــاوز نقطــة التفتيــش‬\n      ‫هكــذا أجــاب وأنكــر قصــد الترويــج عنــد ذلــك جــرى ســؤال املدعــي‬\n      ‫ا‬\n      ‫العــام هــل لديــك بينــة علــى قصــد املدعــى عليهمــا للترويــج فأجــاب قائـ ً‬\n      ‫بينتــي مــا يف أوراق املعاملــة إضافــة إلــى كبــر حجــم الكميــة املضبوطــة‬\n      ‫هكــذا أجــاب وبالرجــوع إلى أوراق املع ــاملة جــرى االطالع على التقرير‬\n      ‫الكيميائــي الشــرعي وثبــت ســوابق املدعــى عليهمــا فوجــدت مطابقــة‬\n      ‫ملــا يف الدعــوى كمــا جــرى االطــاع علــى بقيــة لفــات املعاملــة ولــم أجــد‬\n      ‫بهــا مــا يديــن املدعــى عليهمــا بقصــد الترويــج ســوى قرينــة كبــر حجــم‬\n      ‫الكميــة عنــد ذلــك جــرى ســؤال املدعــي العــام هــل لديــك مزيــد بينــة‬\n      ‫ا ال أعلــم لــي مزيــد بينــة هكــذا أجــاب عليــه فبنــاء علــى مــا‬\n                                                                           ‫فأجــاب قائـ ً‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وملــا رواه ابــن عبــاس رضــي اهلل عنهمــا قــال‬\n      ‫لعــن رســول اهلل صلــى اهلل عليــه وســلم املتشــبهني مــن الرجــال بالنســاء‬\n\n\n‫‪263‬‬\n\f‫واملتشــبهات مــن النســاء بالرجــال رواه البخــاري (‪ )2207/5‬برقــم‬\n‫(‪ )5546‬وملــا تضمنــه األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ يف فقرتــه األولــى مــن املوافقــة علــى أن تطبــق احملاكــم‬\n‫علــى مرتكبــي جرائــم القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة ولعجــز املدعــي العــام عــن‬\n‫إقامــة البينــة املثبتــة إلدانــة املدعــى عليــه بقصــد الترويــج فقــد قــررت‬\n‫مــا يلــي أوال ثبتــت لــدي إدانــة املدعــى عليــه األول بلبســه الــزي النســائي‬\n‫بقصــد التخفــي وجتــاوز نقطــة التفتيــش وهــو يســتحق العقوبــة التعزيريــة‬\n‫لقــاء ذلــك ثانيــا ثبتــت لــدي إدانــة املدعــى عليــه الثانــي بتضليــل رجــال‬\n‫األمــن بدعــواه أن مرافقــه امــرأة وأنهــا زوجتــه وإبــرازه صــورة مــن ســجل‬\n‫أســرته بقصــد جتــاوز نقطــة التفتيــش وهــو يســتحق العقوبــة التعزيريــة‬\n‫لقــاء ذلــك ثالثــا لــم تثبــت لــدي إدانــة املدعــى عليهمــا بقصــد الترويــج‬\n‫وصرفــت النظــر عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليهمــا‬\n‫ومجازاتهمــا يف ضــوء املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ وثبتــت لــدي إدانــة املدعــى عليهمــا باالشــتراك يف حيــازة‬\n‫كميــة القــات املذكــورة أعــاه بقصــد التعاطــي وهمــا يســتحق العقوبــة‬\n‫علــى ذلــك وفــق املــادة (‪ )4‬مــن قــرار ســمو زيــر الداخليــة رقــم (‪)2057‬‬\n‫وتاريــخ ‪1404/5/26‬ه ـ املعدلــة بالقــرار الــوزاري رقــم (‪ )3818‬وتاريــخ‬\n‫‪1410/9/28‬ه ـ وملــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة‬\n‫قــال العالمــة البهوتــي (ولــو توجــه عليــه تعزيــرات علــى معــاص شــتى‬\n‫فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل أجنبيــة مــرار ًا أو‬\n‫اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــد ًا تداخلــت وكفــاه‬\n‫تعزيــر واحــد) كشــاف القنــاع عــن مــن اإلقنــاع (ج‪20‬ص‪ )485‬لذلــك‬\n\n\n                                                                                      ‫‪264‬‬\n\f      ‫كلــه فقــد قــررت االكتفــاء مبجــازاة املدعــى عليهمــا لقــاء حيازتهمــا‬\n      ‫لكميــة القــات املضبوطــة بقصــد االســتعمال الشــخصي ونظــرا لكبــر‬\n      ‫حجــم الكميــة فــإن ذلــك يوجــه إليهمــا الشــبهة بقصــد الترويــج وقــد‬\n      ‫حكمــت علــى املدعــى عليــه األول لذلــك تعزيــرا بالســجن مــدة ثمانيــة‬\n      ‫أشــهر تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة‬\n      ‫يف ‪1434/7/3‬ه ـ وجلــده ســبعني جلــدة دفعــة واحــدة كمــا حكمــت‬\n      ‫علــى املدعــى عليــه الثانــي لذلــك تعزيــرا بالســجن مــدة ثمانيــة أشــهر‬\n      ‫تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة يف‬\n      ‫‪1434/7/3‬ه ـ وجلــده ســبعني جلــدة دفعــة واحــدة هــذا مــا ثبــت لــدي‬\n      ‫وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي العــام معارضتــه‬\n      ‫وطلــب رفعــه حملكمــة االســتئناف دون الئحــة فأجبتــه لذلــك وقــرر‬\n      ‫املدعــى عليهمــا القناعــة بــه وقــد جــرى النطــق بــه يف متــام الســاعة الثانيــة‬\n      ‫عشــرة والربــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n      ‫وصحبــه أجمعــن حــرر يف ‪1434/8/15‬هــ‪ .‬احلمــد هلل وحــده وبعــد فقــد‬\n      ‫اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق القضايــا اجلزائيــة مبحكمــة‬\n      ‫االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بجــازان برقــم ‪ 341953035‬وتاريــخ ‪1434/8/20‬ه ـ‬\n      ‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬‬\n      ‫برقــم ‪ 34298921‬وتاريــخ ‪1434/8/16‬ه ـ اخلــاص بدعــوى املدعــي العام‬\n      ‫ضــد كل مــن ‪ ..... /‬و‪.....‬يف قضيــة (قــات) علــى الصفــة املوضحــة يف‬\n      ‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪.‬‬\n              ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪265‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":259,"source_page_end":265,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fb8e7a78f9cbabb729ebe58bb1ed340ada35769c90c85325c0862fab8b19507d","normalized_text_hash":"73f58aff949667eacf0d3d8881ec8a3d106908a4def47d46939204c538aa6cbd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p259-34298921"},{"id":"25588ae4-3b56-506d-85ed-d704add4d02a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج -قات -حتايل على رجال األمن -املدعى عليه أجنبي -إبراز رخصة قيادة مزورة -التعزير بالسجن","document_number":"34311440","case_number":"34407562","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/09/02","year":"1434","subject":"مخدرات -حيازة بقصد الترويج -قات -حتايل على رجال األمن -املدعى عليه أجنبي -إبراز رخصة قيادة مزورة -التعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34311440 :‬تاريخه‪1434/09/02 :‬هـ‬\n                     ‫رقم الدعوى‪34407562 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34328587‬تاريخه‪1434/10/12:‬هـ‬\n\n\n  ‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج ‪ -‬قــات ‪ -‬حتايــل علــى رجــال األمــن‬\n  ‫‪ -‬املدعــى عليــه أجنبــي ‪ -‬إبــراز رخصــة قيــادة مــزورة ‪ -‬التعزيــر بالســجن‬\n                                                                       ‫واجللــد‪.‬‬\n\n\n\n         ‫‪ -1‬املادة الرابعة من قرار مجلس الوزراء رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n                        ‫‪ -2‬قرار وزير الداخلية رقم (‪ )2057‬لعام ‪1404‬هـ ‪.‬‬\n                      ‫‪ -3‬قرار وزير الداخلية رقم (‪ )3818‬لعام ‪ 1410‬هـ ‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد الترويــج‬\n  ‫والتحايــل علــى رجــال األمــن بــاإلدالء مبعلومــات غيــر صحيحــة وطلــب‬\n  ‫إثبــات مــا أســند إليــه وتعزيــره ‪،‬وتعزيــره لقــاء التحايــل وإبعــاده عــن‬\n  ‫البــاد ‪،‬حيــث مت االشــتباه يف الســيارة التــي يقودهــا املدعــى عليــه ومت‬\n  ‫اســتيقافه وطلــب إثباتــه فقــام بإبــراز رخصــة قيــادة مــزورة وبتفتيــش‬\n  ‫الســيارة عثــر علــى نبــات يشــتبه أن يكــون نبــات القــات مبخبــأ ســري‬\n  ‫داخــل خــزان الوقــود ‪،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n  ‫العينــة املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى عليــه علــى‬\n  ‫حيــازة القــات وأنهــا لالســتعمال الشــخصي وأنكــر الترويــج وأقــر‬\n\n                                                                                    ‫‪266‬‬\n\f      ‫بتضليلــه والكــذب علــى رجــال األمــن ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بتعزيــره بســجنه ســنة وصــرف النظــر عــن طلــب املدعــي العــام‬\n      ‫لعــدم وجــود مــا يؤيــد الترويــج وتعزيــر املدعــى عليــه لكبــر الكميــة‬\n      ‫وشــبهة الترويــج وحتايلــه علــى رجــال األمــن بجلــده مائــة وخمســن جلــدة‬\n      ‫مفرقــة علــى ثــاث دفعــات وقنــع بــه املدعــى عليــه واعترض املدعــي العام‬\n                     ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬   ‫بــدون الئحــة ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34407562‬وتاريــخ ‪ 1434/09/01‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 342098319‬وتاريــخ ‪ 1434/09/01‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/09/02‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪00‬‬\n      ‫‪ 10 :‬وفيهــا حضــر املدعــي العــام ‪..... /‬املوجــه باخلطــاب رقــم (‪ ).....‬يف‬\n      ‫‪1434/8/29‬ه ـ وأدعــى علــى احلاضــر معــه الســجني‪..... /‬مينــي اجلنســية‬\n      ‫مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬حيــث إنــه بتاريــخ ‪1434/7/9‬ه ـ‬\n      ‫وأثنــاء قيــام الدوريــات األمنيــة بواجبهــا املعتــاد مبحافظــة الــدرب مت‬\n      ‫االشــتباه يف ســيارة نــوع اللــون ذهبــي موديــل ‪2003‬م اللوحــة(‪).....‬‬\n      ‫تعــود ملكيتهــا للمدعــو‪(...../‬مت حجزهــا حلــن مراجعــة مالكهــا)‬\n      ‫وبقيــادة املدعــى عليــه وباســتيقاف الســيارة وطلــب إثبــات قائدهــا قــام‬\n      ‫بإبــراز رخصــة قيــادة مــزورة باســم (‪ ).....‬وبســؤاله عنهــا ذكــر بأنــه‬\n      ‫اشــتراها مببلــغ (‪ 1000‬ريــال) مــن مكــة املكرمــة (مت فــرز أوراق‬\n      ‫مســتقلة بشــأن الرخصــة املــزورة) وبتفتيــش الســيارة عثــر علــى مخبــأ‬\n\n‫‪267‬‬\n\f‫ســري داخــل خــزان الوقــود وبداخلــه كميــة مــن نبــات أخضــر يشــتبه‬\n‫أن يكــون مــن نبــات القــات احملظــور بلــغ وزنهــا(‪ 19.500‬كجــم)‬\n‫تســعة عشــر كيلــو وخمســمائة جــرام أثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقــم (‪ ).....‬بتاريــخ ‪1434/7/17‬ه ـ الصــادر مــن مركــز‬\n‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بجــازان إيجابيــة‬\n‫العينــة املرســلة مــن الكميــة املضبوطــة لنبــات القــات احملظــور املــدرج‬\n‫باجلــدول رقــم(‪ )2‬فئــة(أ‪،‬ج) واجلــدول رقــم(‪ )4‬امللحقــن بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف‬\n‫‪1426/7/8‬ه ـ ومت إيقافــه اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n‫وباســتجواب املدعــى عليــه أقــر بحيازتــه للكميــة املضبوطــة وذكــر‬\n‫بأنــه قــام بشــرائها مــن شــخص مينــي ال يعرفــه مببلــغ (‪ 500‬ريــال) كمــا‬\n‫ذكــر بــأن قصــده منهــا االســتعمال الشــخصي وأفــاد بــأن الرخصــة‬\n‫املــزورة التــي قــام بإبرازهــا لرجــال األمــن وحتمــل اســم (‪ ).....‬أنــه اســم‬\n‫شــقيق مالــك الســيارة (‪.).....‬وقــد أســفر التحقيــق عــن اتهــام‪..... /‬بحيــازة‬\n‫مــا وزنــه (‪ 19,500‬كجــم) تســعة عشــر كيلــو وخمســمائة جــرام مــن‬\n‫نبــات القــات احملظــور بقصــد الترويــج واملجــرم مبوجــب الفقــرة رقــم‬\n‫(‪ )2‬مــن املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫والتحايــل علــى رجــال األمــن بــاإلدالء مبعلومــات غيــر صحيحــة‪ .‬وذلــك‬\n                                                    ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n                 ‫‪ -1‬ما جاء يف أقواله مبحضر االستجواب لفه رقم(‪.)16‬‬\n‫‪ -2‬مــا جــاء مبحضــر القبــض والتفتيــش املشــار لــه املرفــق بــاألوراق لفــه‬\n\n\n                                                                                      ‫‪268‬‬\n\f                                                                              ‫رقــم (‪. )2-1‬‬\n      ‫‪ -3‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفه (‪.)17‬‬\n      ‫ولــم يعثــر لــه علــى ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫فعــل محــرم شــرع ًا و معاقــب عليــه نظامـ ًا مبوجــب قــرار مجلــس الــوزراء‬\n                 ‫رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات ‪ ،‬لــذا أطلــب‪:‬‬\n                                               ‫إثبات إدانته مبا أسند إليه واحلكم‪:‬‬\n      ‫‪ -1‬بتعزيــره يف ضــوء املــادة (الثالثة)و(الرابعــة) مــن القــرار الــوزاري‬\n      ‫املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n                                                                         ‫‪1432/12/9‬هــ‪.‬‬\n                 ‫‪ -2‬إبعاده إلى بالده بعد انتهاء محكوميته استناد ًا لذات املادة‪.‬‬\n      ‫‪ -3‬عقوبــة تعزيريــة لقــاء حتايلــه علــى رجــال األمــن بــاإلدالء بأقــوال غيــر‬\n                                                                                  ‫صحيحة‪.‬‬\n      ‫وبعــرض مــا جــاء يف الئحــة الدعــوى علــى املدعــى عليــه صــدق على صحة‬\n      ‫مــا جــاء فيهــا وأن الكميــة املض ــبوطة بح ــوزته والب ــالغ وزن ــها (‪19,500‬‬\n      ‫كجــم) تســعة عشــر كيلــو وخمســمائة جــرام مــن ن ــبات ال ــقات تعــود‬\n      ‫لــه شــخصي ًا لغــرض االســتعمال الشــخصي و أنكــر قصــد الترويــج‬\n      ‫وأقــر بتضليلــه والكــذب علــى رجــال األمــن ليتمكــن مــن اإلفــات مــن‬\n      ‫العقوبــة هكــذا أجــاب وقــد جــرى ســؤال املدعــي العــام عــن بينتــه علــى‬\n      ‫أن الكميــة معــدة للترويــج قــال بينتــي كبــر حجــم الكميــة املضبوطــة‬\n      ‫وال يتصــور أن تكــون لالســتعمال الشــخصي وبعــرض ذلــك على املدعى‬\n      ‫عليــه قــال الصحيــح مــا ذكــرت وأنهــا لالســتعمال الشــخصي هكــذا‬\n      ‫أجــاب وباالطــاع علــى محضــر القبــض والتحقيــق وجــد مطابــق ملــا جــاء‬\n      ‫يف الئحــة الدعــوى وباالطــاع علــى التقريــر الكيميائــي الشــرعي لفــة‬\n\n\n‫‪269‬‬\n\f‫رقــم (‪ )17‬وجــد إيجابيــة العينــة املرســلة لنبــات القــات وباإلطــاع علــى‬\n‫ـاء علــى مــا تقــدم‬\n                   ‫صحيفــة الســوابق لــم يعثــر لــه علــى ســوابق مســجلة فبنـ ً‬\n‫مــن الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه بحيازتــه للكميــة‬\n‫املرصــودة أعــاه لغــرض االســتعمال الشــخصي وحيــث أنكــر قصــد‬\n‫الترويــج وال بينــة للمدعــي العــام ســوى كبــر حجــم الكميــه املضبوطــة‬\n‫وحيــث إن مــا أقــدم عليــه فعــل محــرم فقــد ثبــت لــدى إدانــة املدعــى عليــه‬\n‫بحيازتــه ملــا وزنــه (‪ 19,500‬كجــم) تســعة عشــر كيلــو وخمســمائة‬\n‫جــرام مــن نبــات القــات لغــرض االســتعمال الشــخصي وحكمــت‬\n‫عليــه تعزيــر ًا بالســجن ملــدة ســنة اعتبــارا مــن تاريــخ إيقافــه علــى ذمــة‬\n‫هــذه القضيــة اســتنادا للمــادة الرابعــة مــن القــرار الــوزاري رقــم(‪)11‬‬\n‫لعام‪1374‬ه ـ واملعــدل بقــراري وزيــر الداخليــة رقــم(‪ )2057‬لعام‪1404‬ه ـ‬\n‫ورقــم(‪ )3818‬لعام‪1410‬ه ـ وصرفــت النظــر عــن طلــب املدعــي العــام‬\n‫لعــدم وجــود مــا يؤيــد الترويــج ونظــر ًا لكبــر حجــم الكميــة ولوجــود‬\n‫شــبهة الترويــج و لتحايلــه علــى رجــال األمــن فهــو يســتحق التعزيــر علــى‬\n‫ذلــك بجلــده ألجــل ذلــك مائــة و خمســون جلــدة مفرقــة علــى ثــاث فتــرات‬\n‫بــن كل فتــرة واألخــرى ال يقــل عــن أســبوع ومبــا ســبق حكمــت وبهــذا‬\n‫انتهــت هــذه الدعــوى وبعــرض مــا حكمنــا بــه املدعــى عليــه قنــع بــه وقرر‬\n‫املدعــي العــام املعارضــة وطلــب رفعهــا إلــى محكمــة االســتئناف بــدون‬\n‫الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/02‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n\n\n                                                                                      ‫‪270‬‬\n\f      ‫‪ 342098319‬وتاريــخ ‪1434/9/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪.....‬برقــم ‪ 34311440‬وتاريــخ‬\n      ‫‪1434/9/2‬هـ اخلاص بدعوى املدعي العام ض ـ ـ ـ ـ ــد‪ ..... /‬ـ ميني اجلنســية‬\n      ‫ـ يف قضيــة ( قــات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n                                              ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪271‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":266,"source_page_end":271,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ff4c134b728688323d4df61d9e69261df165989278af9390cf5f28230f5c2aaa","normalized_text_hash":"5cced0fcf78ceac8a621885c6c1bdb306440e61e6fe5a28c1f0b5f5eef0fcefe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p266-34311440"},{"id":"73bfc4f4-189c-5e5b-a536-abf27f3f6396","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -عدم ثبوت اإلدانة بالترويج والتعاطي -خيانة األمانة ونكث القسم -املدعى عليهما عسكريان -تداخل العقوبات التعزيرية -التعزير بالسجن -1ما قرره أهل العلم يف تداخل العقوبات التعزيرية حيث جاء يف كشاف القناع ج 485/ 20للبهوتي ( ولو توجه عليه تعزيرات على معاص شتى فإن متحضت هلل تعالى واحتد نوعها كأن قبل أجنبية مرارا أو اختلف نوعها بأن قبل أجنبية وملس أخرى قصدا","document_number":"34350704","case_number":"34429116","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/5","year":"1434","subject":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -عدم ثبوت اإلدانة بالترويج والتعاطي -خيانة األمانة ونكث القسم -املدعى عليهما عسكريان -تداخل العقوبات التعزيرية -التعزير بالسجن -1ما قرره أهل العلم يف تداخل العقوبات التعزيرية حيث جاء يف كشاف القناع ج 485/ 20للبهوتي ( ولو توجه عليه تعزيرات على معاص شتى فإن متحضت هلل تعالى واحتد نوعها كأن قبل أجنبية مرارا أو اختلف نوعها بأن قبل أجنبية وملس أخرى قصدا","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34350704 :‬تاريخه ‪1434/11/5:‬هـ‬\n                         ‫رقم القضية‪34429116:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 35110775‬تاريخه‪1434/01/09:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬عــدم ثبــوت‬\n      ‫اإلدانــة بالترويــج والتعاطــي ‪ -‬خيانــة األمانــة ونكــث القســم ‪ -‬املدعــى‬\n      ‫عليهمــا عســكريان ‪ -‬تداخــل العقوبــات التعزيريــة ‪ -‬التعزيــر بالســجن‬\n\n\n\n      ‫‪ -1‬مــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة حيــث جــاء‬\n      ‫يف كشــاف القنــاع ج ‪ 485/ 20‬للبهوتــي ( ولــو توجــه عليــه تعزيــرات‬\n      ‫علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل‬\n      ‫أجنبيــة مــرارا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــدا‬\n                                              ‫تداخلــت وكفــاه تعزيــر واحــد )‪.‬‬\n      ‫‪ -2‬املــادة الرابعــة مــن قــرار ســمو وزيــر الداخليــة رقــم (‪ )2057‬يف‬\n                                                                 ‫‪1404/5/26‬هــ‪.‬‬\n                            ‫‪ -3‬القرار الوزاري رقم (‪ )3818‬يف ‪1410/9/28‬هـ ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بحيــازة قــات بقصــد الترويــج‬\n      ‫والتعاطــي وخيانــة األمانــة ونكــث القســم ‪،‬حيــث مت القبــض عليهمــا‬\n      ‫وهمــا يســتخدمان الســيارة الرســمية التابعــة حلــرس احلــدود وبحيازتهمــا‬\n      ‫القــات وطلــب إثبــات مــا أســند إليهمــا ومعاقبتهمــا وبتشــديد العقوبــة‬\n\n‫‪279‬‬\n\f‫خليانــة األمانــة كونهمــا رجلــي أمن وأثبت التقرير الكيميائي الشــرعي‬\n‫إيجابيــة العينــة املضبوطــة لنبــات القات احملظور وصــادق املدعى عليهما‬\n‫علــى حيازتهمــا القــات وأنهــا بقصــد االســتعمال الشــخصي وأنكــرا‬\n‫الترويــج ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة علــى املدعــى عليهمــا‬\n‫بالســجن ســنتني نظــر ًا لتداخــل العقوبــات التعزيريــة واعتــرض املدعــي‬\n     ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n                                             ‫العــام واملدعــى عليهمــا ُ‬\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )342206477‬وتاريــخ ‪1434/9/17‬هـ‬\n‫واحملالة من فضيلة الرئيس برقم (‪ )34429116‬وتاريخ ‪1434/9/17‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪.....‬و‪.....‬املتهمــن يف قضيــة حيــازة‬\n‫كميــة مــن نبــات القــات وخيانــة األمانــة ونكــث القســم عليــه ففــي‬\n‫هــذا اليــوم الثالثــاء ‪1434/11/4‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة العاشــرة وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم‬\n‫(‪ ).....‬وتاريــخ ‪1434/8/29‬ه ـ وادعــى علــى األول ‪.....‬ســعودي اجلنســية‬\n‫يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي ‪.....‬والثانــي ‪.....‬ســعودي‬\n‫اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي ‪.....‬أنــه بتاريــخ‬\n‫‪1434/2/27‬ه ـ وأثنــاء قيــام رئيــس قســم االســتخبارات بواجبــه يف‬\n‫حــدود مســئولياته يف مركــز ‪.....‬شــوهدت إحــدى الســيارات الرســمية‬\n‫التابعــة حلــرس احلــدود وهــي تقــف بجــوار أحــد املنــازل املهجــورة ونــزل‬\n‫مــن الســيارة اجلنــدي املدعــى عليــه ‪.....‬وبيــده عتلتــان مــن نبــات القــات‬\n\n                                                                                      ‫‪280‬‬\n\f      ‫احملظــور وقــام بإدخالهــا لذلــك املنــزل بداخــل إحــدى غــرف املنــزل وعلــى‬\n      ‫الفــور مت التوجــه إليــه وقبــض عليــه وهــو خــارج مــن املنــزل وليــس بيــده‬\n      ‫شــيء وبالدخــول إلــى املنــزل وتفتيشــه عثــر بــه علــى كميــة نبــات القــات‬\n      ‫وكانــت الســيارة بقيــادة اجلنــدي املدعــى عليــه ‪.....‬وبتفتيــش الســيارة‬\n      ‫عثــر حتــت مرتبــة الراكــب علــى حبــة مــن نبــات القــات ومت القبــض‬\n      ‫عليــه وبلــغ وزن الكميــات املضبوطــة (‪7،600‬كجــم) ســبعة كيلــوات‬\n      ‫وســتمائة جــرام أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ ).....‬بتاريــخ‬\n      ‫‪1434/3/11‬ه ـ الصــادر مــن مركــز مراقبــة الســموم والكيميــاء‬\n      ‫الشــرعية بجــازان إيجابيــة العينــة املرســلة مــن الكميــة املضبوطــة‬\n      ‫لنبــات القــات احملظــور املــدرج باجلــدول رقــم (‪ )2‬فئــة (أ‪،‬ج) واجلــدول‬\n      ‫رقــم (‪ )4‬امللحقــن بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ وباســتجواب‬\n      ‫املدعــى عليــه األول أقــر بصحــة واقعــة الضبــط وأفــاد بأنــه قــام بإنــزال‬\n      ‫الكميــة لذلــك املنــزل حتــى يأتيــه التوجيــه مــن قبــل عمليــات املركــز‬\n      ‫وحتــى ال يشــاهد أحــد الكميــة بداخــل الســيارة ويتــم اتهامــه فيهــا‬\n      ‫كمــا أقــر بأنــه يريــد وضعهــا يف املنــزل حتــى يتعاطــى منهــا هــو ورفيقــه‬\n      ‫علــى فتــرات وأن الكميــة التــي عثــر عليهــا بداخــل الســيارة ســقطت‬\n      ‫مــن العتلتــن أثنــاء نزولــه مــن الســيارة وصــادق علــى أقوالــه وباســتجواب‬\n      ‫املدعــى عليــه الثانــي أقــر بصحــة واقعــة الضبــط وأفــاد بــأن رفيقــه قــام‬\n      ‫بإنــزال الكميــة لذلــك املنــزل حتــى يأتيــه التوجيــه مــن قبــل عمليــات‬\n      ‫املركــز وحتــى ال يشــاهد أحــد الكميــة بداخــل الســيارة ويتــم اتهامهمــا‬\n      ‫فيهــا كمــا أقــر بأنهمــا يريــدان وضعهــا يف املنــزل حتــى يتعاطــى منهــا‬\n      ‫هــو ورفيقــه علــى فتــرات وصــادق علــى أقوالــه وبالبحــث عــن ســوابقهما‬\n\n\n‫‪281‬‬\n\f‫لــم يعثــر لهمــا علــى ســوابق مســجلة وقــد أســفر التحقيــق معــه عــن توجيــه‬\n‫االتهــام إليهمــا بحيازتهمــا كميــة مــن القــات تزن (‪7،600‬كجم) ســبعة‬\n‫كيلــوات وســتمائة جــرام بقصــد الترويــج والتعاطــي واملجــرم مبوجــب‬\n‫واملجــرم مبوجــب الفقــرة رقــم (‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ ونكــث القســم وخيانــة األمانــة وألن مــا أقــدم‬\n‫عليــه املدعــى عليهمــا فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب‬\n‫قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات‬\n‫فقــد طلــب املدعــي العــام إثبــات إدانتهمــا مبــا أســند إليهمــا واحلكــم‬\n‫بتعزيرهمــا يف ضــوء املادتــن الثالثــة والرابعــة مــن القــرار الــوزاري‬\n‫املشــار إليــه أعــاه إنفــاذا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n‫‪1432/12/9‬ه ـ وتشــديد العقوبــة عليهمــا لكونهمــا رجلــي أمــن ومنوط‬\n‫بهمــا حفــظ األمــن وتعزيرهمــا شــرعا لقــاء نكثهمــا القســم وخيانــة‬\n‫األمانــة وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه األول صــدق‬\n‫القبــض عليــه يف الزمــان واملــكان املشــار إليهمــا واشــتراكه يف حيــازة‬\n‫كميــة القــات املذكــورة وقــرر أن قصــده مــن حيازتــه لنبــات القــات هــو‬\n‫االســتعمال الشــخصي لبعضــه وتســليم املتبقــي إلــى جهــة عملــه لســبق‬\n‫تبليغــه عــن ضبطــه لــه وأنكــر قصــد الترويــج هكــذا أجــاب وبعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه الثانــي صــدق القبــض عليــه يف‬\n‫الزمــان واملــكان املشــار إليهمــا واشــتراكه يف حيــازة كميــة القــات‬\n‫املذكــورة وقــرر أن قصــده مــن حيازتــه لنبــات القــات هــو االســتعمال‬\n‫الشــخصي لبعضــه وتســليم املتبقــي إلــى جهــة عملــه لســبق تبليغــه عــن‬\n‫ضبطــه لــه وأنكــر قصــد الترويــج هكــذا أجــاب عنــد ذلــك جــرى‬\n\n\n                                                                                     ‫‪282‬‬\n\f      ‫ســؤال املدعــي العــام هــل لديــك بينــة علــى قصــد املدعــى عليهمــا للترويــج‬\n      ‫ا بينتــي مــا يف أوراق املعاملــة إضافــة إلــى كبــر حجــم‬      ‫فأجــاب قائ ـ ً‬\n      ‫الكميــة املضبوطــة وطريقــة تقســيمها ووجــود رقــم جــوال مينــي بجــوال‬\n      ‫املتهــم األول واســتخدام الســيارة الرســمية ولبســهما الرســمي هكــذا‬\n      ‫أجــاب وبالرجــوع إلــى أوراق املع ــاملة جــرى االطــاع علــى التقريــر‬\n      ‫الكيميائــي الشــرعي وثبــت ســوابق املدعــى عليهمــا فوجــدت مطابقــة‬\n      ‫ملــا يف الدعــوى كمــا جــرى االطــاع علــى بقيــة لفــات املعاملــة ولــم أجــد‬\n      ‫بهــا مــا يديــن املدعــى عليهمــا بقصــد الترويــج ســوى قرينــة كبــر حجــم‬\n      ‫الكميــة عنــد ذلــك جــرى ســؤال املدعــي العــام هــل لديــك مزيــد بينــة‬\n      ‫ا ال أعلــم لــي مزيــد بينــة هكــذا أجــاب عليــه فبنــاء علــى‬  ‫فأجــاب قائ ـ ً‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وملــا تضمنــه األمــر الســامي الكــرمي رقــم‬\n      ‫(‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ يف فقرتــه األولــى مــن املوافقــة علــى‬\n      ‫أن تطبــق احملاكــم علــى مرتكبــي جرائــم القــات العقوبــات املعمــول‬\n      ‫بهــا قبــل نفــاذ نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ولعجــز‬\n      ‫املدعــي العــام عــن إقامــة البينــة املثبتــة إلدانــة املدعــى عليهمــا بقصــد‬\n      ‫الترويــج فقــد قــررت مــا يلــي أوال لــم تثبــت لــدي إدانــة املدعــى عليهمــا‬\n      ‫بقصــد الترويــج يف حيازتهمــا لكميــة القــات املضبوطــة وصرفــت النظــر‬\n      ‫عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليهمــا ومجازاتهمــا يف‬\n      ‫ضــوء املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n      ‫ثانيــا ثبتــت لــدي إدانــة املدعــى عليهمــا باالشــتراك يف حيــازة كميــة‬\n      ‫القــات املذكــورة أعــاه بقصــد التعاطــي وهمــا يســتحقان العقوبــة‬\n      ‫علــى ذلــك وفــق املــادة (‪ )4‬مــن قــرار ســمو زيــر الداخليــة رقــم (‪)2057‬‬\n      ‫وتاريــخ ‪1404/5/26‬ه ـ املعدلــة بالقــرار الــوزاري رقــم (‪ )3818‬وتاريــخ‬\n\n\n‫‪283‬‬\n\f‫‪1410/9/28‬ه ـ ثالثــا ثبتــت لــدي إدانــة املدعــى عليهمــا بخيانــة األمانــة‬\n‫التــي حملهمــا إياهــا ولــي األمــر ونكثهمــا القســم املأخــوذ عليهمــا يف‬\n‫ذلــك وهمــا يســتحقان العقوبــة التعزيريــة لقــاءه وملــا قــرره أهــل العلــم‬\n‫يف تداخــل العقوبــات التعزيريــة قــال العالمــة البهوتــي (ولــو توجــه‬\n‫عليــه تعزيــرات علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد‬\n‫نوعهــا كأن قبــل أجنبيــة مــرار ًا أو اختلــف نوعهــا بــأن قبــل أجنبيــة‬\n‫وملــس أخــرى قصــد ًا تداخلــت وكفــاه تعزيــر واحــد) كشــاف القنــاع‬\n‫عــن مــن اإلقنــاع (ج‪20‬ص‪ )485‬لذلــك كلــه فقــد قــررت االكتفــاء‬\n‫مبجــازاة املدعــى عليهمــا لقــاء خيانتهمــا لألمانــة ونكثهمــا للقســم وقــد‬\n‫حكمــت علــى املدعــى عليــه األول لذلــك بالســجن مــدة ســنتني تبــدأ مــن‬\n‫تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة يف ‪1434/8/29‬ه ـ‬\n‫حتســب منهــا املــدد التــي أمضاهــا يف التوقيــف علــى ذمــة القضيــة قبــل‬\n‫ذلــك كمــا حكمــت علــى املدعــى عليــه الثانــي لذلــك بالســجن مــدة‬\n‫ســنتني تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة‬\n‫يف ‪1434/8/29‬ه ـ حتســب منهــا املــدد التــي أمضاهــا يف التوقيــف علــى‬\n‫ذمــة القضيــة قبــل ذلــك هــذا مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى‬\n‫أطــراف القضيــة قــرر املدعــي العــام معارضتــه وطلــب رفعــه حملكمــة‬\n‫االســتئناف دون الئحــة فأجبتــه لذلــك وقــررا املدعــى عليهمــا معارضتــه‬\n‫وطلبــا رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة فأجبتهمــا لذلــك‬\n‫وأفهمتهمــا مبراجعــة احملكمــة يــوم الثالثــاء ‪1434/11/11‬ه ـ الســتالم‬\n‫صــورة القــرار وتقــدمي االعتــراض عليــه يف املهلــة املقــررة نظامــا وقدرهــا‬\n‫ثالثــون يومــا اعتبــارا مــن اقــرب األجلــن تاريــخ اســتالمه لصــورة القــرار‬\n‫او املوعــد احملــدد ففهمــاه وقــد جــرى النطــق بــه يف متــام الســاعة العاشــرة‬\n\n\n                                                                                      ‫‪284‬‬\n\f      ‫والنصــف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                      ‫وصحبــه أجمعــن حــرر يف ‪1434/11/4‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n      ‫‪ 342206477‬وتاريــخ ‪1434/12/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬برقــم ‪ 34350704‬وتاريــخ‬\n      ‫‪1434/11/5‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪..... /‬و ‪.....‬‬\n      ‫يف قضيــة (قــات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪.‬‬\n            ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪285‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":279,"source_page_end":285,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"296bc2720d4aa9707e9fb4e00cdbb8ad28e793161b167326b3753ce181e0601a","normalized_text_hash":"cf5779ffdc5171ccf81ae43509085ada256bc404969c08425a8043feb259d7d5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p279-34350704"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
